import type { BankQuestion } from "@/lib/bank";

/** Preamble of the Constitution (Indian Polity): 223 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"polity-preamble-1","question":"The Preamble of the Indian Constitution begins with the words:","options":["We, the people of India","India, that is Bharat","Sovereign Socialist Secular","Justice, Liberty, Equality"],"answer":0,"explanation":"The Preamble opens with “We, the people of India”, showing that the people are the source of authority.","difficulty":"easy","questionHi":"भारतीय संविधान की उद्देशिका (प्रस्तावना) किन शब्दों से शुरू होती है?","optionsHi":["हम, भारत के लोग","इंडिया, अर्थात भारत","संप्रभु समाजवादी पंथनिरपेक्ष","न्याय, स्वतंत्रता, समता"],"explanationHi":"उद्देशिका “हम, भारत के लोग” से शुरू होती है, जो दर्शाता है कि सत्ता का स्रोत जनता है।"},
  {"id":"polity-preamble-2","question":"According to the Preamble, the source of authority of the Indian Constitution is:","options":["Parliament","The President","The people of India","The British Parliament"],"answer":2,"explanation":"“We, the people of India … adopt, enact and give to ourselves this Constitution.”","difficulty":"easy","questionHi":"उद्देशिका के अनुसार भारतीय संविधान की सत्ता का स्रोत क्या है?","optionsHi":["संसद","राष्ट्रपति","भारत के लोग","ब्रिटिश संसद"],"explanationHi":"“हम, भारत के लोग … इस संविधान को अंगीकृत, अधिनियमित और आत्मार्पित करते हैं।”"},
  {"id":"polity-preamble-3","question":"Which Constitutional Amendment added the words “Socialist” and “Secular” to the Preamble?","options":["24th Amendment","42nd Amendment","44th Amendment","52nd Amendment"],"answer":1,"explanation":"The 42nd Amendment Act, 1976 added Socialist, Secular and Integrity to the Preamble.","difficulty":"easy","questionHi":"किस संविधान संशोधन द्वारा उद्देशिका में “समाजवादी” और “पंथनिरपेक्ष” शब्द जोड़े गए?","optionsHi":["24वाँ संशोधन","42वाँ संशोधन","44वाँ संशोधन","52वाँ संशोधन"],"explanationHi":"42वें संशोधन अधिनियम, 1976 ने उद्देशिका में समाजवादी, पंथनिरपेक्ष और अखंडता शब्द जोड़े।"},
  {"id":"polity-preamble-4","question":"Which of these words was NOT added to the Preamble by the 42nd Amendment?","options":["Socialist","Secular","Integrity","Republic"],"answer":3,"explanation":"“Republic” was in the original Preamble. Socialist, Secular and Integrity were added in 1976.","difficulty":"moderate","questionHi":"इनमें से कौन-सा शब्द 42वें संशोधन द्वारा उद्देशिका में नहीं जोड़ा गया था?","optionsHi":["समाजवादी","पंथनिरपेक्ष","अखंडता","गणराज्य"],"explanationHi":"“गणराज्य” मूल उद्देशिका में पहले से था। समाजवादी, पंथनिरपेक्ष और अखंडता 1976 में जोड़े गए।"},
  {"id":"polity-preamble-5","question":"The Objectives Resolution, on which the Preamble is based, was moved by:","options":["B. R. Ambedkar","Rajendra Prasad","Jawaharlal Nehru","Sardar Vallabhbhai Patel"],"answer":2,"explanation":"Nehru moved the Objectives Resolution in the Constituent Assembly on 13 December 1946.","difficulty":"moderate","questionHi":"जिस उद्देश्य प्रस्ताव पर उद्देशिका आधारित है, उसे किसने प्रस्तुत किया था?","optionsHi":["बी. आर. अंबेडकर","राजेंद्र प्रसाद","जवाहरलाल नेहरू","सरदार वल्लभभाई पटेल"],"explanationHi":"नेहरू ने 13 दिसंबर 1946 को संविधान सभा में उद्देश्य प्रस्ताव प्रस्तुत किया था।"},
  {"id":"polity-preamble-6","question":"The Preamble declares India a “Republic”. This means that:","options":["The head of state holds office by hereditary succession","The head of state is elected, not hereditary","There is no single head of state, only a Cabinet","The head of state is appointed for life"],"answer":1,"explanation":"In a republic the head of state (the President) is elected, not a hereditary monarch.","difficulty":"moderate","questionHi":"उद्देशिका भारत को “गणराज्य” घोषित करती है। इसका अर्थ है कि:","optionsHi":["राज्य का प्रमुख वंशानुगत उत्तराधिकार से पद ग्रहण करता है","राज्य का प्रमुख निर्वाचित होता है, वंशानुगत नहीं","कोई एक राज्य प्रमुख नहीं होता, केवल मंत्रिमंडल होता है","राज्य प्रमुख की नियुक्ति आजीवन होती है"],"explanationHi":"गणराज्य में राज्य का प्रमुख (राष्ट्रपति) निर्वाचित होता है, वंशानुगत राजा नहीं।"},
  {"id":"polity-preamble-7","question":"In which case did the Supreme Court hold that the Preamble is a part of the Constitution?","options":["Berubari Union reference","Kesavananda Bharati case","I. C. Golaknath case","Minerva Mills Ltd. case"],"answer":1,"explanation":"Kesavananda Bharati (1973) reversed the Berubari (1960) view and held the Preamble is part of the Constitution.","difficulty":"hard","questionHi":"किस मामले में सर्वोच्च न्यायालय ने माना कि उद्देशिका संविधान का भाग है?","optionsHi":["बेरुबारी संघ संदर्भ","केशवानंद भारती मामला","आई. सी. गोलकनाथ मामला","मिनर्वा मिल्स लिमिटेड मामला"],"explanationHi":"केशवानंद भारती (1973) में बेरुबारी (1960) के मत को पलटते हुए न्यायालय ने माना कि उद्देशिका संविधान का भाग है।"},
  {"id":"polity-preamble-8","question":"In which case did the Supreme Court first hold that the Preamble is NOT a part of the Constitution?","options":["Berubari Union case (1960)","Golaknath case (1967)","Kesavananda Bharati case (1973)","Minerva Mills case (1980)"],"answer":0,"explanation":"In Berubari Union (1960) the Court said the Preamble is not part of the Constitution; this was overruled in Kesavananda Bharati (1973).","difficulty":"hard","questionHi":"किस मामले में सर्वोच्च न्यायालय ने पहली बार कहा कि उद्देशिका संविधान का भाग नहीं है?","optionsHi":["बेरुबारी संघ मामला (1960)","गोलकनाथ मामला (1967)","केशवानंद भारती मामला (1973)","मिनर्वा मिल्स मामला (1980)"],"explanationHi":"बेरुबारी संघ (1960) में न्यायालय ने कहा कि उद्देशिका संविधान का भाग नहीं है; इसे केशवानंद भारती (1973) में पलट दिया गया।"},
  {"id":"polity-preamble-9","question":"The ideals of Liberty, Equality and Fraternity in the Preamble were inspired by the:","options":["American Revolution","French Revolution","Russian Revolution","Irish Constitution"],"answer":1,"explanation":"Liberty, Equality and Fraternity was the motto of the French Revolution (1789).","difficulty":"hard","questionHi":"उद्देशिका में स्वतंत्रता, समता और बंधुता के आदर्श किससे प्रेरित हैं?","optionsHi":["अमेरिकी क्रांति","फ्रांसीसी क्रांति","रूसी क्रांति","आयरलैंड का संविधान"],"explanationHi":"स्वतंत्रता, समता और बंधुता फ्रांसीसी क्रांति (1789) का नारा था।"},
  {"id":"polity-preamble-10","question":"Which is the correct order of words in the Preamble?","options":["Sovereign, Secular, Socialist, Democratic, Republic","Sovereign, Socialist, Secular, Democratic, Republic","Socialist, Sovereign, Secular, Democratic, Republic","Sovereign, Democratic, Socialist, Secular, Republic"],"answer":1,"explanation":"The Preamble reads “Sovereign Socialist Secular Democratic Republic”.","difficulty":"very-hard","questionHi":"उद्देशिका में शब्दों का सही क्रम कौन-सा है?","optionsHi":["संप्रभु, पंथनिरपेक्ष, समाजवादी, लोकतंत्रात्मक, गणराज्य","संप्रभु, समाजवादी, पंथनिरपेक्ष, लोकतंत्रात्मक, गणराज्य","समाजवादी, संप्रभु, पंथनिरपेक्ष, लोकतंत्रात्मक, गणराज्य","संप्रभु, लोकतंत्रात्मक, समाजवादी, पंथनिरपेक्ष, गणराज्य"],"explanationHi":"उद्देशिका में “संप्रभु समाजवादी पंथनिरपेक्ष लोकतंत्रात्मक गणराज्य” लिखा है।"},
  {"id":"polity-preamble-11","question":"The Preamble was adopted by the Constituent Assembly on:","options":["26 November 1949","26 January 1950","9 December 1946","13 December 1946"],"answer":0,"explanation":"The Constitution, with its Preamble, was adopted on 26 November 1949 and came into force on 26 January 1950. 9 and 13 December 1946 are the Assembly's first sitting and the day the Objectives Resolution was moved.","difficulty":"very-hard","questionHi":"उद्देशिका को संविधान सभा ने किस तिथि को अंगीकृत किया?","optionsHi":["26 नवंबर 1949","26 जनवरी 1950","9 दिसंबर 1946","13 दिसंबर 1946"],"explanationHi":"उद्देशिका सहित संविधान 26 नवंबर 1949 को अंगीकृत किया गया और 26 जनवरी 1950 को लागू हुआ। 9 और 13 दिसंबर 1946 संविधान सभा की पहली बैठक और उद्देश्य प्रस्ताव प्रस्तुत होने की तिथियाँ हैं।"},
  {"id":"polity-preamble-12","question":"Consider: 1. The Preamble is justiciable. 2. The Preamble can be amended under Article 368. Which is correct?","options":["Only 1","Only 2","Both 1 and 2","Neither"],"answer":1,"explanation":"The Preamble is non-justiciable (not enforceable in court), but Kesavananda Bharati held it can be amended without altering the basic structure.","difficulty":"very-hard","questionHi":"विचार कीजिए: 1. उद्देशिका वादयोग्य (न्यायिक प्रवर्तनीय) है। 2. उद्देशिका में अनुच्छेद 368 के अंतर्गत संशोधन किया जा सकता है। कौन-सा सही है?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","दोनों में से कोई नहीं"],"explanationHi":"उद्देशिका वादयोग्य नहीं है (न्यायालय में प्रवर्तनीय नहीं), परंतु केशवानंद भारती मामले में कहा गया कि मूल ढाँचे को बदले बिना इसमें संशोधन किया जा सकता है।"},
  {"id":"polity-preamble-13","question":"The word “Integrity” in the phrase “unity and integrity of the Nation” was inserted into the Preamble by the:","options":["1st Amendment","7th Amendment","42nd Amendment","44th Amendment"],"answer":2,"explanation":"The 42nd Amendment (1976) added Socialist, Secular and “and integrity”.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"उद्देशिका में “राष्ट्र की एकता और अखंडता” वाक्यांश में “अखंडता” शब्द किसके द्वारा जोड़ा गया?","optionsHi":["पहला संशोधन","7वाँ संशोधन","42वाँ संशोधन","44वाँ संशोधन"],"explanationHi":"42वें संशोधन (1976) ने समाजवादी, पंथनिरपेक्ष और “और अखंडता” जोड़ा।"},
  {"id":"polity-preamble-14","question":"The Preamble describes the Indian state as “Secular”. In the Indian sense this means the state:","options":["Has an official religion but tolerates others","Promotes the religion of the majority community","Has no religion of its own, treats all alike","Bans all religious practice in public places"],"answer":2,"explanation":"Indian secularism is equal treatment of all religions by a state that has none of its own.","difficulty":"moderate","source":"SSC CGL · UPSC Prelims","questionHi":"उद्देशिका भारतीय राज्य को “पंथनिरपेक्ष” बताती है। भारतीय अर्थ में इसका तात्पर्य है कि राज्य:","optionsHi":["का एक आधिकारिक धर्म है पर वह अन्य धर्मों को सहन करता है","बहुसंख्यक समुदाय के धर्म को बढ़ावा देता है","का अपना कोई धर्म नहीं है और वह सभी के साथ समान व्यवहार करता है","सार्वजनिक स्थानों पर सभी धार्मिक आचरण पर प्रतिबंध लगाता है"],"explanationHi":"भारतीय पंथनिरपेक्षता का अर्थ है कि ऐसा राज्य जिसका अपना कोई धर्म नहीं, वह सभी धर्मों के साथ समान व्यवहार करे।"},
  {"id":"polity-preamble-15","question":"Which type of justice is NOT mentioned in the Preamble?","options":["Social","Economic","Political","Legal"],"answer":3,"explanation":"The Preamble promises social, economic and political justice; “legal” is not listed.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"उद्देशिका में किस प्रकार के न्याय का उल्लेख नहीं है?","optionsHi":["सामाजिक","आर्थिक","राजनीतिक","विधिक"],"explanationHi":"उद्देशिका सामाजिक, आर्थिक और राजनीतिक न्याय का वचन देती है; “विधिक” न्याय का उल्लेख नहीं है।"},
  {"id":"polity-preamble-16","question":"“Fraternity” in the Preamble assures the dignity of the individual and the:","options":["Sovereignty of the state","Unity and integrity of the Nation","Supremacy of Parliament","Independence and impartiality of judges"],"answer":1,"explanation":"The text reads “Fraternity assuring the dignity of the individual and the unity and integrity of the Nation”.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"उद्देशिका में “बंधुता” व्यक्ति की गरिमा और किसका आश्वासन देती है?","optionsHi":["राज्य की संप्रभुता","राष्ट्र की एकता और अखंडता","संसद की सर्वोच्चता","न्यायाधीशों की स्वतंत्रता और निष्पक्षता"],"explanationHi":"पाठ इस प्रकार है: “बंधुता जिससे व्यक्ति की गरिमा और राष्ट्र की एकता और अखंडता सुनिश्चित हो”।"},
  {"id":"polity-preamble-17","question":"Consider the statements: 1. The Preamble has been amended only once. 2. The original Preamble described India as a “Sovereign Democratic Republic”. 3. The word “Fraternity” was added by the 42nd Amendment. Which are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"The 42nd Amendment (1976) is the only amendment; it added Socialist, Secular and Integrity. Fraternity was in the original text.","difficulty":"hard","questionHi":"कथनों पर विचार कीजिए: 1. उद्देशिका में केवल एक बार संशोधन हुआ है। 2. मूल उद्देशिका में भारत को “संप्रभु लोकतंत्रात्मक गणराज्य” कहा गया था। 3. “बंधुता” शब्द 42वें संशोधन द्वारा जोड़ा गया। कौन-से सही हैं?","optionsHi":["केवल 1 और 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"explanationHi":"42वाँ संशोधन (1976) एकमात्र संशोधन है; इसने समाजवादी, पंथनिरपेक्ष और अखंडता जोड़ा। बंधुता मूल पाठ में थी।"},
  {"id":"polity-preamble-18","question":"Assertion (A): The Preamble cannot be enforced in a court of law. Reason (R): The Preamble is neither a source of power to the legislature nor a limit on its powers.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"The Preamble is non-justiciable precisely because it neither grants nor restricts legislative power.","difficulty":"hard","questionHi":"अभिकथन (A): उद्देशिका को न्यायालय में प्रवर्तित नहीं कराया जा सकता। कारण (R): उद्देशिका न तो विधायिका को शक्ति देने का स्रोत है और न ही उसकी शक्तियों पर सीमा है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"उद्देशिका वादयोग्य इसीलिए नहीं है क्योंकि यह न विधायी शक्ति देती है और न उसे सीमित करती है।"},
  {"id":"polity-preamble-19","question":"The ideal of “Justice — social, economic and political” in the Preamble is drawn from the:","options":["French Revolution","Russian Revolution","American Declaration of Independence","Irish Constitution"],"answer":1,"explanation":"The ideal of justice comes from the Russian Revolution (1917); Liberty, Equality and Fraternity from the French Revolution.","difficulty":"very-hard","questionHi":"उद्देशिका में “न्याय — सामाजिक, आर्थिक और राजनीतिक” का आदर्श किससे लिया गया है?","optionsHi":["फ्रांसीसी क्रांति","रूसी क्रांति","अमेरिकी स्वतंत्रता की घोषणा","आयरलैंड का संविधान"],"explanationHi":"न्याय का आदर्श रूसी क्रांति (1917) से लिया गया है; स्वतंत्रता, समता और बंधुता फ्रांसीसी क्रांति से।"},
  {"id":"polity-preamble-20","question":"Which of these is NOT among the liberties promised in the Preamble?","options":["Thought","Expression","Faith","Association"],"answer":3,"explanation":"The Preamble promises “liberty of thought, expression, belief, faith and worship”. Association is a right under Article 19, not a word in the Preamble.","difficulty":"very-hard","questionHi":"इनमें से कौन-सी स्वतंत्रता उद्देशिका में दिए गए वचन में शामिल नहीं है?","optionsHi":["विचार","अभिव्यक्ति","आस्था","संगम (संघ बनाना)"],"explanationHi":"उद्देशिका “विचार, अभिव्यक्ति, विश्वास, धर्म और उपासना की स्वतंत्रता” का वचन देती है। संगम अनुच्छेद 19 के अंतर्गत अधिकार है, उद्देशिका का शब्द नहीं।"},
  {"id":"polity-preamble-21","question":"How many of these statements are correct? I. The Preamble was adopted after the rest of the Constitution was finalised. II. The Preamble has been amended under Article 368. III. Courts use the Preamble to interpret ambiguous provisions. IV. The Preamble calls India a “Union of States”.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. “Union of States” is from Article 1, not the Preamble.","difficulty":"very-hard","questionHi":"इनमें से कितने कथन सही हैं? I. उद्देशिका को संविधान के शेष भाग के अंतिम रूप से तैयार होने के बाद अंगीकृत किया गया। II. उद्देशिका में अनुच्छेद 368 के अंतर्गत संशोधन हुआ है। III. अस्पष्ट प्रावधानों की व्याख्या के लिए न्यायालय उद्देशिका का उपयोग करते हैं। IV. उद्देशिका भारत को “राज्यों का संघ” कहती है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। “राज्यों का संघ” अनुच्छेद 1 से है, उद्देशिका से नहीं।"},
  {"id":"polity-preamble-22","question":"How many of these statements are correct? I. “Socialist” in the Preamble refers to democratic socialism. II. The words “unity” and “integrity” were both added in 1976. III. The Preamble mentions the dignity of the individual.","options":["Only one","Only two","All three","None"],"answer":1,"explanation":"Only I and III. “Unity” was in the original text; only “and integrity” was added by the 42nd Amendment.","difficulty":"very-hard","questionHi":"इनमें से कितने कथन सही हैं? I. उद्देशिका में “समाजवादी” का अर्थ लोकतांत्रिक समाजवाद है। II. “एकता” और “अखंडता” दोनों शब्द 1976 में जोड़े गए। III. उद्देशिका में व्यक्ति की गरिमा का उल्लेख है।","optionsHi":["केवल एक","केवल दो","सभी तीन","कोई नहीं"],"explanationHi":"केवल I और III सही हैं। “एकता” मूल पाठ में थी; 42वें संशोधन ने केवल “और अखंडता” जोड़ा।"},
  {"id":"polity-preamble-23","question":"How many of these statements are correct? I. In the Berubari Union reference (1960) the Supreme Court said the Preamble is not a part of the Constitution. II. In Kesavananda Bharati (1973) it held that the Preamble is a part of the Constitution. III. In LIC of India (1995) it again held the Preamble to be an integral part of the Constitution.","options":["Only one","Only two","All three","None"],"answer":2,"explanation":"All three. Berubari (1960) excluded the Preamble; Kesavananda Bharati (1973) reversed that, and LIC of India (1995) reaffirmed it.","difficulty":"very-hard","questionHi":"इनमें से कितने कथन सही हैं? I. बेरुबारी संघ संदर्भ (1960) में सर्वोच्च न्यायालय ने कहा कि उद्देशिका संविधान का भाग नहीं है। II. केशवानंद भारती (1973) में उसने माना कि उद्देशिका संविधान का भाग है। III. LIC ऑफ इंडिया (1995) में उसने पुनः उद्देशिका को संविधान का अभिन्न अंग माना।","optionsHi":["केवल एक","केवल दो","सभी तीन","कोई नहीं"],"explanationHi":"तीनों सही हैं। बेरुबारी (1960) ने उद्देशिका को बाहर रखा; केशवानंद भारती (1973) ने इसे पलट दिया और LIC ऑफ इंडिया (1995) ने इसकी पुनः पुष्टि की।"},
  {"id":"polity-preamble-24","question":"The Preamble is based on the Objectives Resolution, which Jawaharlal Nehru moved in the Constituent Assembly on:","options":["13 December 1946","22 January 1947","26 November 1949","9 December 1946"],"answer":0,"explanation":"Nehru moved it on 13 December 1946; the Assembly adopted it on 22 January 1947. 9 December 1946 was the Assembly’s first sitting.","difficulty":"very-hard","questionHi":"उद्देशिका उद्देश्य प्रस्ताव पर आधारित है, जिसे जवाहरलाल नेहरू ने संविधान सभा में किस तिथि को प्रस्तुत किया?","optionsHi":["13 दिसंबर 1946","22 जनवरी 1947","26 नवंबर 1949","9 दिसंबर 1946"],"explanationHi":"नेहरू ने इसे 13 दिसंबर 1946 को प्रस्तुत किया; सभा ने इसे 22 जनवरी 1947 को अंगीकृत किया। 9 दिसंबर 1946 सभा की पहली बैठक थी।"},
  {"id":"polity-preamble-25","question":"Assertion (A): Parliament can amend the Preamble under Article 368. Reason (R): The Supreme Court has held that the Preamble is a part of the Constitution.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Because the Preamble is part of the Constitution (Kesavananda Bharati), it can be amended under Article 368, subject to the basic structure. It was amended once, in 1976.","difficulty":"very-hard","questionHi":"अभिकथन (A): संसद अनुच्छेद 368 के अंतर्गत उद्देशिका में संशोधन कर सकती है। कारण (R): सर्वोच्च न्यायालय ने माना है कि उद्देशिका संविधान का भाग है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"क्योंकि उद्देशिका संविधान का भाग है (केशवानंद भारती), इसलिए मूल ढाँचे की सीमा के अधीन अनुच्छेद 368 के अंतर्गत इसमें संशोधन किया जा सकता है। इसमें 1976 में एक बार संशोधन हुआ।"},
  {"id":"polity-preamble-26","question":"Arrange in chronological order: 1. Adoption of the Objectives Resolution 2. Kesavananda Bharati judgment 3. 42nd Amendment to the Preamble 4. Berubari Union opinion of the Supreme Court","options":["1-4-2-3","1-2-4-3","4-1-2-3","1-4-3-2"],"answer":0,"explanation":"Objectives Resolution adopted (January 1947), Berubari Union (1960), Kesavananda Bharati (1973), 42nd Amendment (1976).","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"कालक्रम के अनुसार व्यवस्थित कीजिए: 1. उद्देश्य प्रस्ताव का अंगीकरण 2. केशवानंद भारती निर्णय 3. उद्देशिका में 42वाँ संशोधन 4. सर्वोच्च न्यायालय की बेरुबारी संघ राय","optionsHi":["1-4-2-3","1-2-4-3","4-1-2-3","1-4-3-2"],"explanationHi":"उद्देश्य प्रस्ताव का अंगीकरण (जनवरी 1947), बेरुबारी संघ (1960), केशवानंद भारती (1973), 42वाँ संशोधन (1976)।"},
  {"id":"polity-preamble-27","question":"How many of these statements are correct? I. “Republic” means the head of state is elected, not hereditary. II. India’s membership of the Commonwealth requires it to accept the British monarch as its head of state. III. The word “secular” was in the Preamble as adopted in 1949. IV. The Preamble records the date of adoption as 26 January 1950.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only I is correct. II is wrong: India is a republic with an elected President; it accepts the monarch only as the symbolic Head of the Commonwealth. III is wrong: “secular” came with the 42nd Amendment (1976). IV is wrong: the Preamble records 26 November 1949; 26 January 1950 is the date of commencement.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"इनमें से कितने कथन सही हैं? I. “गणराज्य” का अर्थ है कि राज्य का प्रमुख निर्वाचित होता है, वंशानुगत नहीं। II. राष्ट्रमंडल की भारत की सदस्यता के लिए उसे ब्रिटिश सम्राट को अपना राज्य प्रमुख मानना आवश्यक है। III. “पंथनिरपेक्ष” शब्द 1949 में अंगीकृत उद्देशिका में था। IV. उद्देशिका अंगीकरण की तिथि 26 जनवरी 1950 दर्ज करती है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल I सही है। II गलत है: भारत निर्वाचित राष्ट्रपति वाला गणराज्य है; वह सम्राट को केवल राष्ट्रमंडल के प्रतीकात्मक प्रमुख के रूप में स्वीकार करता है। III गलत है: “पंथनिरपेक्ष” 42वें संशोधन (1976) से आया। IV गलत है: उद्देशिका 26 नवंबर 1949 दर्ज करती है; 26 जनवरी 1950 प्रारंभ की तिथि है।"},
  {"id":"polity-preamble-28","question":"The idea of beginning the Constitution with a Preamble was borrowed from the Constitution of:","options":["Ireland","United Kingdom","United States","Canada"],"answer":2,"explanation":"The American Constitution was the first to begin with a Preamble (“We the People of the United States…”), and India followed that model. Ireland gave the Directive Principles, not the Preamble.","difficulty":"easy","source":"SSC CGL · RRB NTPC","questionHi":"संविधान को उद्देशिका से शुरू करने का विचार किस देश के संविधान से लिया गया?","optionsHi":["आयरलैंड","यूनाइटेड किंगडम","संयुक्त राज्य अमेरिका","कनाडा"],"explanationHi":"अमेरिकी संविधान उद्देशिका से शुरू होने वाला पहला संविधान था (“हम संयुक्त राज्य के लोग…”), और भारत ने उसी प्रारूप का अनुसरण किया। आयरलैंड से नीति निदेशक तत्व लिए गए, उद्देशिका नहीं।"},
  {"id":"polity-preamble-29","question":"Which of these words does NOT occur anywhere in the Preamble of the Indian Constitution?","options":["Sovereign","Federal","Secular","Democratic"],"answer":1,"explanation":"India is described as a Sovereign Socialist Secular Democratic Republic. The word “Federal” is not used in the Preamble (or anywhere in the Constitution); Article 1 calls India a “Union of States”.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"इनमें से कौन-सा शब्द भारतीय संविधान की उद्देशिका में कहीं भी नहीं आता?","optionsHi":["संप्रभु","संघीय","पंथनिरपेक्ष","लोकतंत्रात्मक"],"explanationHi":"भारत को संप्रभु समाजवादी पंथनिरपेक्ष लोकतंत्रात्मक गणराज्य कहा गया है। “संघीय” शब्द उद्देशिका (या पूरे संविधान) में कहीं प्रयुक्त नहीं है; अनुच्छेद 1 भारत को “राज्यों का संघ” कहता है।"},
  {"id":"polity-preamble-30","question":"Who described the Preamble as the “identity card of the Constitution”?","options":["K. M. Munshi","N. A. Palkhivala","Ernest Barker","Thakur Das Bhargava"],"answer":1,"explanation":"Nani Palkhivala called the Preamble the identity card of the Constitution. K. M. Munshi called it the “horoscope of our sovereign democratic republic”, Ernest Barker its “key-note” and Thakur Das Bhargava its “soul”.","difficulty":"easy","source":"SSC CGL · State PSC","questionHi":"उद्देशिका को संविधान का “पहचान पत्र” किसने कहा?","optionsHi":["के. एम. मुंशी","एन. ए. पालखीवाला","अर्नेस्ट बार्कर","ठाकुर दास भार्गव"],"explanationHi":"नानी पालखीवाला ने उद्देशिका को संविधान का पहचान पत्र कहा। के. एम. मुंशी ने इसे “हमारे संप्रभु लोकतंत्रात्मक गणराज्य की जन्मकुंडली”, अर्नेस्ट बार्कर ने “कुंजी-स्वर” और ठाकुर दास भार्गव ने “आत्मा” कहा।"},
  {"id":"polity-preamble-31","question":"The Objectives Resolution, moved by Nehru on 13 December 1946, was finally adopted by the Constituent Assembly on:","options":["9 December 1946","26 November 1947","15 August 1947","22 January 1947"],"answer":3,"explanation":"The resolution was moved on 13 December 1946 and adopted on 22 January 1947 after the Muslim League’s absence had delayed it. 9 December 1946 was the Assembly’s first sitting.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"13 दिसंबर 1946 को नेहरू द्वारा प्रस्तुत उद्देश्य प्रस्ताव को संविधान सभा ने अंततः किस तिथि को अंगीकृत किया?","optionsHi":["9 दिसंबर 1946","26 नवंबर 1947","15 अगस्त 1947","22 जनवरी 1947"],"explanationHi":"प्रस्ताव 13 दिसंबर 1946 को प्रस्तुत किया गया और मुस्लिम लीग की अनुपस्थिति से हुई देरी के बाद 22 जनवरी 1947 को अंगीकृत किया गया। 9 दिसंबर 1946 सभा की पहली बैठक थी।"},
  {"id":"polity-preamble-32","question":"Who called the Preamble the “horoscope of our sovereign democratic republic”?","options":["N. A. Palkhivala","Alladi Krishnaswami Ayyar","K. M. Munshi","Jawaharlal Nehru"],"answer":2,"explanation":"K. M. Munshi, a member of the Drafting Committee, used the phrase “horoscope”. Palkhivala’s phrase was “identity card”.","difficulty":"moderate","source":"SSC CGL · UPSC Prelims","questionHi":"उद्देशिका को “हमारे संप्रभु लोकतंत्रात्मक गणराज्य की जन्मकुंडली” किसने कहा?","optionsHi":["एन. ए. पालखीवाला","अल्लादि कृष्णास्वामी अय्यर","के. एम. मुंशी","जवाहरलाल नेहरू"],"explanationHi":"प्रारूप समिति के सदस्य के. एम. मुंशी ने “जन्मकुंडली” शब्द का प्रयोग किया। पालखीवाला का शब्द “पहचान पत्र” था।"},
  {"id":"polity-preamble-33","question":"The word “Sovereign” in the Preamble means that India:","options":["Cannot acquire foreign territory or cede any of its own","Is free to conduct its internal and external affairs","Must follow Commonwealth decisions on foreign policy","Has no written limits on the power of its Parliament"],"answer":1,"explanation":"Sovereignty means India is neither a dependency nor a dominion and is free to conduct its internal and external affairs. As a sovereign state it can acquire foreign territory or cede its own (Berubari case), and Parliament is still bound by the Constitution.","difficulty":"moderate","source":"SSC CGL · UPSC Prelims","questionHi":"उद्देशिका में “संप्रभु” शब्द का अर्थ है कि भारत:","optionsHi":["विदेशी क्षेत्र प्राप्त नहीं कर सकता और अपना कोई क्षेत्र नहीं सौंप सकता","अपने आंतरिक और बाहरी मामलों को चलाने के लिए स्वतंत्र है","विदेश नीति पर राष्ट्रमंडल के निर्णयों का पालन करने को बाध्य है","अपनी संसद की शक्ति पर कोई लिखित सीमा नहीं रखता"],"explanationHi":"संप्रभुता का अर्थ है कि भारत न तो किसी का अधीन राज्य है और न डोमिनियन, और अपने आंतरिक व बाहरी मामले चलाने में स्वतंत्र है। संप्रभु राज्य के रूप में वह विदेशी क्षेत्र प्राप्त कर सकता है या अपना क्षेत्र सौंप सकता है (बेरुबारी मामला), और संसद फिर भी संविधान से बँधी है।"},
  {"id":"polity-preamble-34","question":"Social justice and economic justice in the Preamble, taken together, are often referred to as:","options":["Procedural justice","Natural justice","Distributive justice","Retributive justice"],"answer":2,"explanation":"The combination of social and economic justice, which seeks to remove inequalities of status and wealth, is called distributive justice. Natural justice is a principle of administrative law, not a Preamble ideal.","difficulty":"moderate","source":"UPSC Prelims · State PSC","questionHi":"उद्देशिका में सामाजिक न्याय और आर्थिक न्याय को मिलाकर प्रायः क्या कहा जाता है?","optionsHi":["प्रक्रियात्मक न्याय","प्राकृतिक न्याय","वितरणात्मक न्याय","दंडात्मक न्याय"],"explanationHi":"सामाजिक और आर्थिक न्याय का संयोजन, जो प्रतिष्ठा और संपत्ति की असमानताएँ दूर करना चाहता है, वितरणात्मक न्याय कहलाता है। प्राकृतिक न्याय प्रशासनिक विधि का सिद्धांत है, उद्देशिका का आदर्श नहीं।"},
  {"id":"polity-preamble-35","question":"“Political justice” mentioned in the Preamble implies:","options":["Reservation of seats for religious minorities in all legislatures","Equal distribution of wealth and income among all citizens","A ban on political parties based on religion or caste","Equal political rights and equal access to office for all"],"answer":3,"explanation":"Political justice means every citizen has equal political rights, equal access to political offices and an equal voice in government, secured mainly through universal adult franchise (Article 326). Wealth distribution is economic justice.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"उद्देशिका में उल्लिखित “राजनीतिक न्याय” का तात्पर्य है:","optionsHi":["सभी विधायिकाओं में धार्मिक अल्पसंख्यकों के लिए सीटों का आरक्षण","सभी नागरिकों में धन और आय का समान वितरण","धर्म या जाति पर आधारित राजनीतिक दलों पर प्रतिबंध","सभी के लिए समान राजनीतिक अधिकार और पदों तक समान पहुँच"],"explanationHi":"राजनीतिक न्याय का अर्थ है कि प्रत्येक नागरिक को समान राजनीतिक अधिकार, राजनीतिक पदों तक समान पहुँच और शासन में समान आवाज़ मिले, जो मुख्यतः सार्वभौमिक वयस्क मताधिकार (अनुच्छेद 326) से सुनिश्चित होती है। धन का वितरण आर्थिक न्याय है।"},
  {"id":"polity-preamble-36","question":"Which ideal of the Preamble is promoted by the provision of single citizenship and by the Fundamental Duty under Article 51A(e)?","options":["Liberty","Equality","Justice","Fraternity"],"answer":3,"explanation":"Fraternity, a sense of common brotherhood, is promoted by single citizenship and by Article 51A(e), which asks citizens to promote harmony and the spirit of common brotherhood.","difficulty":"moderate","source":"UPSC Prelims · State PSC","questionHi":"एकल नागरिकता के प्रावधान और अनुच्छेद 51A(e) के मौलिक कर्तव्य से उद्देशिका का कौन-सा आदर्श बढ़ावा पाता है?","optionsHi":["स्वतंत्रता","समता","न्याय","बंधुता"],"explanationHi":"बंधुता, यानी साझा भाईचारे की भावना, एकल नागरिकता और अनुच्छेद 51A(e) से बढ़ावा पाती है, जो नागरिकों से सौहार्द और समान भ्रातृत्व की भावना को बढ़ावा देने को कहता है।"},
  {"id":"polity-preamble-37","question":"The Berubari Union opinion (1960) led to which Constitutional Amendment that gave effect to the Nehru–Noon Agreement with Pakistan?","options":["7th Amendment, 1956","9th Amendment, 1960","10th Amendment, 1961","1st Amendment, 1951"],"answer":1,"explanation":"The Supreme Court advised that ceding Indian territory needs a constitutional amendment under Article 368, so Parliament passed the 9th Amendment Act, 1960 to transfer the Berubari Union area to Pakistan. The 10th Amendment dealt with Dadra and Nagar Haveli.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"बेरुबारी संघ की राय (1960) के कारण कौन-सा संविधान संशोधन हुआ, जिसने पाकिस्तान के साथ नेहरू–नून समझौते को प्रभावी किया?","optionsHi":["7वाँ संशोधन, 1956","9वाँ संशोधन, 1960","10वाँ संशोधन, 1961","पहला संशोधन, 1951"],"explanationHi":"सर्वोच्च न्यायालय ने सलाह दी कि भारतीय क्षेत्र सौंपने के लिए अनुच्छेद 368 के अंतर्गत संविधान संशोधन आवश्यक है, इसलिए संसद ने बेरुबारी संघ क्षेत्र पाकिस्तान को देने के लिए 9वाँ संशोधन अधिनियम, 1960 पारित किया। 10वाँ संशोधन दादरा और नागर हवेली से संबंधित था।"},
  {"id":"polity-preamble-38","question":"In which case did the Supreme Court interpret the word “Socialist” in the Preamble as aiming to secure a decent standard of life and social security for working people, while deciding a pension case?","options":["Minerva Mills v. Union of India (1980)","Golaknath v. State of Punjab (1967)","Sajjan Singh v. State of Rajasthan (1965)","D. S. Nakara v. Union of India (1983)"],"answer":3,"explanation":"In D. S. Nakara (1983), a case about pensioners, the Court read “socialist” in the Preamble as a commitment to a decent standard of life and social security. Minerva Mills concerned the balance between Fundamental Rights and Directive Principles.","difficulty":"hard","source":"UPSC Prelims","questionHi":"किस मामले में सर्वोच्च न्यायालय ने पेंशन से जुड़े एक वाद का निर्णय करते हुए उद्देशिका के “समाजवादी” शब्द का अर्थ कामगारों के लिए सम्मानजनक जीवन स्तर और सामाजिक सुरक्षा सुनिश्चित करना बताया?","optionsHi":["मिनर्वा मिल्स बनाम भारत संघ (1980)","गोलकनाथ बनाम पंजाब राज्य (1967)","सज्जन सिंह बनाम राजस्थान राज्य (1965)","डी. एस. नकारा बनाम भारत संघ (1983)"],"explanationHi":"डी. एस. नकारा (1983) में, जो पेंशनभोगियों से जुड़ा मामला था, न्यायालय ने उद्देशिका के “समाजवादी” को सम्मानजनक जीवन स्तर और सामाजिक सुरक्षा की प्रतिबद्धता माना। मिनर्वा मिल्स मौलिक अधिकारों और नीति निदेशक तत्वों के संतुलन से संबंधित था।"},
  {"id":"polity-preamble-39","question":"In which case did the Supreme Court hold that secularism, as reflected in the Preamble, is a basic feature of the Constitution, and use it to uphold the dismissal of state governments after the 1992 Babri demolition?","options":["Kesavananda Bharati v. State of Kerala","S. R. Bommai v. Union of India","Indira Nehru Gandhi v. Raj Narain","Union of India v. LIC of India"],"answer":1,"explanation":"In S. R. Bommai (1994) a nine-judge bench held secularism to be part of the basic structure and said a state government acting against it could be dismissed under Article 356. Kesavananda (1973) laid down the basic-structure doctrine itself.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"किस मामले में सर्वोच्च न्यायालय ने माना कि उद्देशिका में परिलक्षित पंथनिरपेक्षता संविधान की मूल विशेषता है, और 1992 के बाबरी विध्वंस के बाद राज्य सरकारों की बर्खास्तगी को उचित ठहराने में इसका उपयोग किया?","optionsHi":["केशवानंद भारती बनाम केरल राज्य","एस. आर. बोम्मई बनाम भारत संघ","इंदिरा नेहरू गांधी बनाम राज नारायण","भारत संघ बनाम LIC ऑफ इंडिया"],"explanationHi":"एस. आर. बोम्मई (1994) में नौ न्यायाधीशों की पीठ ने पंथनिरपेक्षता को मूल ढाँचे का भाग माना और कहा कि इसके विरुद्ध कार्य करने वाली राज्य सरकार को अनुच्छेद 356 के अंतर्गत बर्खास्त किया जा सकता है। केशवानंद (1973) ने मूल ढाँचे का सिद्धांत स्वयं स्थापित किया था।"},
  {"id":"polity-preamble-40","question":"In November 2024 the Supreme Court dismissed petitions challenging the words “socialist” and “secular” added to the Preamble in 1976. On what ground were they upheld?","options":["The Preamble is not a part of the Constitution and so cannot be challenged","Article 368 extends to the Preamble, and the words have an Indian meaning","The words were added by the Constituent Assembly and not by Parliament","The petitions were time-barred because the 42nd Amendment was never notified"],"answer":1,"explanation":"A bench headed by Chief Justice Sanjiv Khanna held that the amending power includes the Preamble, that “socialist” in India means a welfare state and not a bar on private enterprise, and that “secular” means the state treats all faiths alike. The Preamble is a part of the Constitution (Kesavananda).","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"नवंबर 2024 में सर्वोच्च न्यायालय ने 1976 में उद्देशिका में जोड़े गए “समाजवादी” और “पंथनिरपेक्ष” शब्दों को चुनौती देने वाली याचिकाएँ खारिज कर दीं। इन्हें किस आधार पर बरकरार रखा गया?","optionsHi":["उद्देशिका संविधान का भाग नहीं है, इसलिए इसे चुनौती नहीं दी जा सकती","अनुच्छेद 368 उद्देशिका तक विस्तृत है, और इन शब्दों का भारतीय अर्थ है","ये शब्द संविधान सभा ने जोड़े थे, संसद ने नहीं","याचिकाएँ समय-सीमा से बाहर थीं क्योंकि 42वाँ संशोधन कभी अधिसूचित ही नहीं हुआ"],"explanationHi":"मुख्य न्यायाधीश संजीव खन्ना की अध्यक्षता वाली पीठ ने कहा कि संशोधन की शक्ति में उद्देशिका भी शामिल है, भारत में “समाजवादी” का अर्थ कल्याणकारी राज्य है, निजी उद्यम पर रोक नहीं, और “पंथनिरपेक्ष” का अर्थ है कि राज्य सभी धर्मों के साथ समान व्यवहार करता है। उद्देशिका संविधान का भाग है (केशवानंद)।"},
  {"id":"polity-preamble-41","question":"Equality in the Preamble has civic, political and economic dimensions. Which of these Articles secure POLITICAL equality?","options":["Articles 14 to 18","Articles 325 and 326","Articles 39(b) and 39(c)","Articles 25 to 28"],"answer":1,"explanation":"Article 325 (no person ineligible for the electoral roll on grounds of religion, race, caste or sex) and Article 326 (universal adult franchise) secure political equality. Articles 14–18 give civic equality and Article 39 economic equality.","difficulty":"hard","source":"UPSC Prelims","questionHi":"उद्देशिका में समता के नागरिक, राजनीतिक और आर्थिक आयाम हैं। इनमें से कौन-से अनुच्छेद राजनीतिक समता सुनिश्चित करते हैं?","optionsHi":["अनुच्छेद 14 से 18","अनुच्छेद 325 और 326","अनुच्छेद 39(b) और 39(c)","अनुच्छेद 25 से 28"],"explanationHi":"अनुच्छेद 325 (धर्म, मूलवंश, जाति या लिंग के आधार पर किसी व्यक्ति को निर्वाचक नामावली से अपात्र न ठहराना) और अनुच्छेद 326 (वयस्क मताधिकार) राजनीतिक समता सुनिश्चित करते हैं। अनुच्छेद 14–18 नागरिक समता और अनुच्छेद 39 आर्थिक समता देते हैं।"},
  {"id":"polity-preamble-42","question":"The 42nd Amendment Act, 1976 was passed in 1976, but its substitution of “Sovereign Socialist Secular Democratic Republic” in the Preamble came into force on:","options":["18 December 1976","3 January 1977","26 January 1977","1 April 1977"],"answer":1,"explanation":"Section 2 of the 42nd Amendment Act, which amended the Preamble, came into force on 3 January 1977. The Act received the President’s assent on 18 December 1976, and different sections commenced on different dates.","difficulty":"hard","source":"SSC CGL · State PSC","questionHi":"42वाँ संशोधन अधिनियम, 1976 में पारित हुआ था, परंतु उद्देशिका में “संप्रभु समाजवादी पंथनिरपेक्ष लोकतंत्रात्मक गणराज्य” का प्रतिस्थापन किस तिथि से लागू हुआ?","optionsHi":["18 दिसंबर 1976","3 जनवरी 1977","26 जनवरी 1977","1 अप्रैल 1977"],"explanationHi":"42वें संशोधन अधिनियम की धारा 2, जिसने उद्देशिका में संशोधन किया, 3 जनवरी 1977 से लागू हुई। अधिनियम को राष्ट्रपति की अनुमति 18 दिसंबर 1976 को मिली थी और अलग-अलग धाराएँ अलग-अलग तिथियों से लागू हुईं।"},
  {"id":"polity-preamble-43","question":"Who, in the Constituent Assembly, described the Preamble as “the soul of the Constitution… a key to the Constitution… a jewel set in the Constitution”?","options":["Pandit Thakur Das Bhargava","Alladi Krishnaswami Ayyar","Kanaiyalal Maneklal Munshi","H. V. Kamath"],"answer":0,"explanation":"Pandit Thakur Das Bhargava, a member of the Constituent Assembly, used these words. Ernest Barker was a British political scientist, not a member of the Assembly.","difficulty":"hard","source":"SSC CGL · State PSC","questionHi":"संविधान सभा में किसने उद्देशिका को “संविधान की आत्मा… संविधान की कुंजी… संविधान में जड़ा हुआ रत्न” कहा?","optionsHi":["पंडित ठाकुर दास भार्गव","अल्लादि कृष्णास्वामी अय्यर","कन्हैयालाल माणिकलाल मुंशी","एच. वी. कामथ"],"explanationHi":"संविधान सभा के सदस्य पंडित ठाकुर दास भार्गव ने ये शब्द कहे थे। अर्नेस्ट बार्कर ब्रिटिश राजनीति वैज्ञानिक थे, संविधान सभा के सदस्य नहीं।"},
  {"id":"polity-preamble-44","question":"The British political scientist who called the Preamble the “key-note” of the Constitution and quoted it at the start of his book “Principles of Social and Political Theory” was:","options":["Ivor Jennings","Ernest Barker","Granville Austin","Harold Laski"],"answer":1,"explanation":"Sir Ernest Barker was so impressed by the Preamble that he opened his 1951 book with it and called it the key-note of the Constitution. Granville Austin wrote on the Constitution as a “seamless web”.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"किस ब्रिटिश राजनीति वैज्ञानिक ने उद्देशिका को संविधान का “कुंजी-स्वर” कहा और अपनी पुस्तक “Principles of Social and Political Theory” के आरंभ में इसे उद्धृत किया?","optionsHi":["आइवर जेनिंग्स","अर्नेस्ट बार्कर","ग्रेनविल ऑस्टिन","हेरोल्ड लास्की"],"explanationHi":"सर अर्नेस्ट बार्कर उद्देशिका से इतने प्रभावित थे कि उन्होंने अपनी 1951 की पुस्तक इसी से शुरू की और इसे संविधान का कुंजी-स्वर कहा। ग्रेनविल ऑस्टिन ने संविधान को “निर्बाध जाल” कहकर लिखा।"},
  {"id":"polity-preamble-45","question":"Which pair of a Preamble feature and its source is NOT correctly matched?","options":["Justice (social, economic, political) – Soviet (Russian) Constitution","Liberty, Equality, Fraternity – French Revolution","Idea of a Preamble – Irish Constitution","Republic – France"],"answer":2,"explanation":"The idea of a Preamble was taken from the Constitution of the United States, not Ireland. Ireland contributed the Directive Principles and the method of electing the President.","difficulty":"hard","source":"SSC CGL · UPSC Prelims","questionHi":"उद्देशिका की विशेषता और उसके स्रोत का कौन-सा युग्म सही सुमेलित नहीं है?","optionsHi":["न्याय (सामाजिक, आर्थिक, राजनीतिक) – सोवियत (रूसी) संविधान","स्वतंत्रता, समता, बंधुता – फ्रांसीसी क्रांति","उद्देशिका का विचार – आयरलैंड का संविधान","गणराज्य – फ्रांस"],"explanationHi":"उद्देशिका का विचार आयरलैंड के नहीं, संयुक्त राज्य अमेरिका के संविधान से लिया गया। आयरलैंड ने नीति निदेशक तत्व और राष्ट्रपति के निर्वाचन की पद्धति दी।"},
  {"id":"polity-preamble-46","question":"How many of these statements are correct? I. The Objectives Resolution was moved on 13 December 1946 and adopted on 22 January 1947. II. The Preamble records 26 November 1949 as the date on which the Constitution was adopted. III. The Preamble has been amended only once, in 1978. IV. The Preamble describes India as a “Union of States”.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and II are correct. III is wrong: the only amendment to the Preamble was the 42nd Amendment of 1976, not 1978 (the 44th Amendment). IV is wrong: “Union of States” is in Article 1, not the Preamble.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"इनमें से कितने कथन सही हैं? I. उद्देश्य प्रस्ताव 13 दिसंबर 1946 को प्रस्तुत हुआ और 22 जनवरी 1947 को अंगीकृत हुआ। II. उद्देशिका संविधान के अंगीकरण की तिथि 26 नवंबर 1949 दर्ज करती है। III. उद्देशिका में केवल एक बार, 1978 में, संशोधन हुआ है। IV. उद्देशिका भारत को “राज्यों का संघ” कहती है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और II सही हैं। III गलत है: उद्देशिका का एकमात्र संशोधन 1976 का 42वाँ संशोधन है, 1978 (44वाँ संशोधन) नहीं। IV गलत है: “राज्यों का संघ” अनुच्छेद 1 में है, उद्देशिका में नहीं।"},
  {"id":"polity-preamble-47","question":"Assertion (A): The words “Socialist” and “Secular” were absent from the Preamble as adopted in 1949. Reason (R): The Constituent Assembly rejected K. T. Shah’s amendment to add them, Ambedkar arguing that the Constitution should not bind future generations to one economic policy and that its provisions already embodied these ideas.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"K. T. Shah moved to insert “Secular, Federal, Socialist”; the Assembly rejected it on the reasoning in R, and the words “socialist” and “secular” were added only by the 42nd Amendment in 1976.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): 1949 में अंगीकृत उद्देशिका में “समाजवादी” और “पंथनिरपेक्ष” शब्द नहीं थे। कारण (R): संविधान सभा ने इन्हें जोड़ने के के. टी. शाह के संशोधन को अस्वीकार कर दिया, क्योंकि अंबेडकर का तर्क था कि संविधान को भावी पीढ़ियों को किसी एक आर्थिक नीति से नहीं बाँधना चाहिए और इसके प्रावधान पहले से इन विचारों को समाहित करते हैं।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A सत्य है परंतु R असत्य है","A असत्य है परंतु R सत्य है"],"explanationHi":"के. टी. शाह ने “पंथनिरपेक्ष, संघीय, समाजवादी” जोड़ने का प्रस्ताव रखा; सभा ने R में दिए तर्क पर इसे अस्वीकार किया, और “समाजवादी” तथा “पंथनिरपेक्ष” 1976 में 42वें संशोधन द्वारा ही जोड़े गए।"},
  {"id":"polity-preamble-48","question":"Arrange in chronological order: 1. S. R. Bommai judgment (secularism a basic feature) 2. Berubari Union reference 3. LIC of India case (Preamble an integral part) 4. D. S. Nakara judgment (meaning of “socialist”)","options":["2, 4, 1, 3","2, 1, 4, 3","4, 2, 1, 3","2, 4, 3, 1"],"answer":0,"explanation":"Berubari Union (1960), D. S. Nakara (1983), S. R. Bommai (1994) and LIC of India (1995).","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"कालक्रम के अनुसार व्यवस्थित कीजिए: 1. एस. आर. बोम्मई निर्णय (पंथनिरपेक्षता मूल विशेषता) 2. बेरुबारी संघ संदर्भ 3. LIC ऑफ इंडिया मामला (उद्देशिका अभिन्न अंग) 4. डी. एस. नकारा निर्णय (“समाजवादी” का अर्थ)","optionsHi":["2, 4, 1, 3","2, 1, 4, 3","4, 2, 1, 3","2, 4, 3, 1"],"explanationHi":"बेरुबारी संघ (1960), डी. एस. नकारा (1983), एस. आर. बोम्मई (1994) और LIC ऑफ इंडिया (1995)।"},
  {"id":"polity-preamble-49","question":"Match the description of the Preamble with the person who gave it: A. “Identity card of the Constitution” B. “Horoscope of our sovereign democratic republic” C. “Key-note of the Constitution” D. “Soul of the Constitution”. 1. K. M. Munshi 2. Ernest Barker 3. N. A. Palkhivala 4. Thakur Das Bhargava","options":["A-3, B-1, C-2, D-4","A-1, B-3, C-2, D-4","A-3, B-1, C-4, D-2","A-2, B-1, C-3, D-4"],"answer":0,"explanation":"Palkhivala: identity card; Munshi: horoscope; Barker: key-note; Thakur Das Bhargava: soul and jewel of the Constitution.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"उद्देशिका के वर्णन को उसे कहने वाले व्यक्ति से सुमेलित कीजिए: A. “संविधान का पहचान पत्र” B. “हमारे संप्रभु लोकतंत्रात्मक गणराज्य की जन्मकुंडली” C. “संविधान का कुंजी-स्वर” D. “संविधान की आत्मा”। 1. के. एम. मुंशी 2. अर्नेस्ट बार्कर 3. एन. ए. पालखीवाला 4. ठाकुर दास भार्गव","optionsHi":["A-3, B-1, C-2, D-4","A-1, B-3, C-2, D-4","A-3, B-1, C-4, D-2","A-2, B-1, C-3, D-4"],"explanationHi":"पालखीवाला: पहचान पत्र; मुंशी: जन्मकुंडली; बार्कर: कुंजी-स्वर; ठाकुर दास भार्गव: संविधान की आत्मा और रत्न।"},
  {"id":"polity-preamble-50","question":"How many of these statements about secularism in the Preamble are correct? I. The word “secular” did not appear in the Preamble as originally adopted. II. Indian secularism is a positive concept of equal respect for all religions, not a strict wall of separation. III. In S. R. Bommai (1994) the Supreme Court held secularism to be a basic feature of the Constitution. IV. Articles 25 to 28 give effect to the Preamble’s ideal of secularism.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. “Secular” was inserted in 1976; the Indian model is “sarva dharma sambhava” rather than the American wall of separation; Bommai made it a basic feature; Articles 25–28 are the right to freedom of religion.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"उद्देशिका में पंथनिरपेक्षता के बारे में इनमें से कितने कथन सही हैं? I. मूल रूप से अंगीकृत उद्देशिका में “पंथनिरपेक्ष” शब्द नहीं था। II. भारतीय पंथनिरपेक्षता सभी धर्मों के प्रति समान सम्मान की सकारात्मक अवधारणा है, पृथक्करण की कठोर दीवार नहीं। III. एस. आर. बोम्मई (1994) में सर्वोच्च न्यायालय ने पंथनिरपेक्षता को संविधान की मूल विशेषता माना। IV. अनुच्छेद 25 से 28 उद्देशिका के पंथनिरपेक्षता के आदर्श को प्रभावी करते हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं। “पंथनिरपेक्ष” 1976 में जोड़ा गया; भारतीय मॉडल अमेरिकी पृथक्करण की दीवार के बजाय “सर्व धर्म संभाव” है; बोम्मई ने इसे मूल विशेषता बनाया; अनुच्छेद 25–28 धर्म की स्वतंत्रता का अधिकार हैं।"},
  {"id":"polity-preamble-51","question":"How many of these statements about “Sovereign” and “Republic” are correct? I. India can cede its territory to a foreign state, but only by a constitutional amendment. II. As a member of the Commonwealth, India owes allegiance to the British Crown. III. India’s head of state is elected directly by the people for a fixed term of five years. IV. “Republic” implies that all public offices are open to every citizen without discrimination.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I (Berubari, 1960) and IV are correct. II is wrong: Commonwealth membership is voluntary and India owes no allegiance to the Crown. III is wrong: the President is elected indirectly by an electoral college of elected MPs and MLAs, not directly by the people.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"“संप्रभु” और “गणराज्य” के बारे में इनमें से कितने कथन सही हैं? I. भारत अपना क्षेत्र किसी विदेशी राज्य को सौंप सकता है, परंतु केवल संविधान संशोधन द्वारा। II. राष्ट्रमंडल का सदस्य होने के नाते भारत ब्रिटिश ताज के प्रति निष्ठा रखता है। III. भारत का राज्य प्रमुख जनता द्वारा पाँच वर्ष के निश्चित कार्यकाल के लिए प्रत्यक्ष रूप से निर्वाचित होता है। IV. “गणराज्य” का अर्थ है कि सभी सार्वजनिक पद बिना भेदभाव के प्रत्येक नागरिक के लिए खुले हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I (बेरुबारी, 1960) और IV सही हैं। II गलत है: राष्ट्रमंडल की सदस्यता स्वैच्छिक है और भारत ताज के प्रति कोई निष्ठा नहीं रखता। III गलत है: राष्ट्रपति का निर्वाचन जनता द्वारा प्रत्यक्ष नहीं, बल्कि निर्वाचित सांसदों और विधायकों के निर्वाचक मंडल द्वारा अप्रत्यक्ष रूप से होता है।"},
  {"id":"polity-preamble-52","question":"Which of these statements about the Preamble is NOT correct?","options":["It is non-justiciable: its provisions cannot be enforced in a court of law","It can be amended by Parliament, subject to the basic structure","Courts use it to interpret ambiguous provisions in the body of the Constitution","In case of conflict, it overrides the express provisions of the Constitution"],"answer":3,"explanation":"The Preamble is neither a source of power nor a limitation on power, and it cannot override the express provisions of the Constitution; it only aids interpretation where the text is ambiguous.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"उद्देशिका के बारे में इनमें से कौन-सा कथन सही नहीं है?","optionsHi":["यह वादयोग्य नहीं है: इसके प्रावधान न्यायालय में प्रवर्तित नहीं कराए जा सकते","संसद मूल ढाँचे की सीमा के अधीन इसमें संशोधन कर सकती है","न्यायालय संविधान के मुख्य भाग के अस्पष्ट प्रावधानों की व्याख्या के लिए इसका उपयोग करते हैं","टकराव की स्थिति में यह संविधान के स्पष्ट प्रावधानों पर प्रभावी होती है"],"explanationHi":"उद्देशिका न तो शक्ति का स्रोत है और न शक्ति पर सीमा, और यह संविधान के स्पष्ट प्रावधानों को निरस्त नहीं कर सकती; पाठ अस्पष्ट होने पर यह केवल व्याख्या में सहायक होती है।"},
  {"id":"polity-preamble-53","question":"How many of these statements about Equality in the Preamble are correct? I. Equality of status and of opportunity has civic, political and economic dimensions. II. Articles 325 and 326 secure political equality. III. Article 39 secures economic equality through principles such as equal pay for equal work. IV. Articles 14 to 18 secure civic equality.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. Civic equality comes from the Right to Equality (Articles 14–18), political equality from Articles 325–326, and economic equality from Directive Principles like Article 39(d).","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"उद्देशिका में समता के बारे में इनमें से कितने कथन सही हैं? I. प्रतिष्ठा और अवसर की समता के नागरिक, राजनीतिक और आर्थिक आयाम हैं। II. अनुच्छेद 325 और 326 राजनीतिक समता सुनिश्चित करते हैं। III. अनुच्छेद 39 समान कार्य के लिए समान वेतन जैसे सिद्धांतों द्वारा आर्थिक समता सुनिश्चित करता है। IV. अनुच्छेद 14 से 18 नागरिक समता सुनिश्चित करते हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं। नागरिक समता समता के अधिकार (अनुच्छेद 14–18) से, राजनीतिक समता अनुच्छेद 325–326 से और आर्थिक समता अनुच्छेद 39(d) जैसे नीति निदेशक तत्वों से आती है।"},
  {"id":"polity-preamble-54","question":"Assertion (A): Adding the word “Socialist” to the Preamble in 1976 did not commit India to state ownership of all means of production. Reason (R): Indian socialism is “democratic socialism” with a mixed economy, as explained by the Supreme Court in cases such as D. S. Nakara and reaffirmed in 2024.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Indian socialism is democratic socialism aiming at a welfare state within a mixed economy, not communistic socialism; the Court in 2024 explicitly said the word does not bar private enterprise.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): 1976 में उद्देशिका में “समाजवादी” शब्द जोड़ने से भारत उत्पादन के सभी साधनों के राज्य स्वामित्व के लिए प्रतिबद्ध नहीं हुआ। कारण (R): भारतीय समाजवाद मिश्रित अर्थव्यवस्था वाला “लोकतांत्रिक समाजवाद” है, जैसा कि सर्वोच्च न्यायालय ने डी. एस. नकारा जैसे मामलों में समझाया और 2024 में पुनः पुष्टि की।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A सत्य है परंतु R असत्य है","A असत्य है परंतु R सत्य है"],"explanationHi":"भारतीय समाजवाद साम्यवादी समाजवाद नहीं, बल्कि मिश्रित अर्थव्यवस्था के भीतर कल्याणकारी राज्य का लक्ष्य रखने वाला लोकतांत्रिक समाजवाद है; 2024 में न्यायालय ने स्पष्ट कहा कि यह शब्द निजी उद्यम पर रोक नहीं लगाता।"},
  {"id":"polity-preamble-55","question":"The Preamble (as amended in 1976) speaks of “the unity and integrity of the Nation”. Which Fundamental Duty carries the same idea?","options":["Article 51A(a) – abide by the Constitution and respect the National Flag","Article 51A(c) – protect the sovereignty, unity and integrity of India","Article 51A(e) – promote harmony and the spirit of common brotherhood","Article 51A(j) – strive towards excellence in all spheres of activity"],"answer":1,"explanation":"Article 51A(c) asks every citizen to uphold and protect the sovereignty, unity and integrity of India. It carries the idea of the Preamble’s fraternity clause, “assuring the dignity of the individual and the unity and integrity of the Nation”, to which the 42nd Amendment (1976) added the word “integrity”. The Preamble itself does not use the word “sovereignty”; it calls India “Sovereign”.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"उद्देशिका (1976 में संशोधित) “राष्ट्र की एकता और अखंडता” की बात करती है। कौन-सा मौलिक कर्तव्य यही विचार रखता है?","optionsHi":["अनुच्छेद 51A(a) – संविधान का पालन करना और राष्ट्रध्वज का सम्मान करना","अनुच्छेद 51A(c) – भारत की संप्रभुता, एकता और अखंडता की रक्षा करना","अनुच्छेद 51A(e) – सौहार्द और समान भ्रातृत्व की भावना को बढ़ावा देना","अनुच्छेद 51A(j) – सभी क्षेत्रों में उत्कृष्टता की ओर बढ़ने का प्रयास करना"],"explanationHi":"अनुच्छेद 51A(c) प्रत्येक नागरिक से भारत की संप्रभुता, एकता और अखंडता को बनाए रखने और उसकी रक्षा करने को कहता है। यह उद्देशिका के बंधुता खंड, “व्यक्ति की गरिमा और राष्ट्र की एकता और अखंडता सुनिश्चित करने वाली”, के विचार को रखता है, जिसमें 42वें संशोधन (1976) ने “अखंडता” शब्द जोड़ा। उद्देशिका स्वयं “संप्रभुता” शब्द का प्रयोग नहीं करती; वह भारत को “संप्रभु” कहती है।"},
  {"id":"polity-preamble-56","question":"How many of these dates are correctly stated? I. The Constituent Assembly first met on 9 December 1946. II. The Objectives Resolution was moved on 13 December 1946. III. The Objectives Resolution was adopted on 22 January 1947. IV. The Preamble was adopted on 26 January 1950.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. The Preamble was adopted with the Constitution on 26 November 1949; 26 January 1950 is the date of commencement.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims","questionHi":"इनमें से कितनी तिथियाँ सही बताई गई हैं? I. संविधान सभा की पहली बैठक 9 दिसंबर 1946 को हुई। II. उद्देश्य प्रस्ताव 13 दिसंबर 1946 को प्रस्तुत हुआ। III. उद्देश्य प्रस्ताव 22 जनवरी 1947 को अंगीकृत हुआ। IV. उद्देशिका 26 जनवरी 1950 को अंगीकृत हुई।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। उद्देशिका संविधान के साथ 26 नवंबर 1949 को अंगीकृत हुई; 26 जनवरी 1950 प्रारंभ की तिथि है।"},
  {"id":"polity-preamble-57","question":"Arrange in chronological order: 1. Insertion of “Socialist” and “Secular” into the Preamble 2. Kesavananda Bharati judgment 3. Berubari Union opinion 4. Supreme Court upholds the words “socialist” and “secular”","options":["3, 2, 1, 4","2, 3, 1, 4","3, 1, 2, 4","2, 1, 3, 4"],"answer":0,"explanation":"Berubari Union (1960), Kesavananda Bharati (1973), the 42nd Amendment (1976), and the Supreme Court’s 2024 decision rejecting the challenge to the words.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"कालक्रम के अनुसार व्यवस्थित कीजिए: 1. उद्देशिका में “समाजवादी” और “पंथनिरपेक्ष” का समावेश 2. केशवानंद भारती निर्णय 3. बेरुबारी संघ राय 4. सर्वोच्च न्यायालय द्वारा “समाजवादी” और “पंथनिरपेक्ष” शब्दों को बरकरार रखना","optionsHi":["3, 2, 1, 4","2, 3, 1, 4","3, 1, 2, 4","2, 1, 3, 4"],"explanationHi":"बेरुबारी संघ (1960), केशवानंद भारती (1973), 42वाँ संशोधन (1976), और इन शब्दों को दी गई चुनौती को खारिज करने वाला सर्वोच्च न्यायालय का 2024 का निर्णय।"},
  {"id":"polity-preamble-58","question":"According to the Preamble, the Constitution seeks to secure to all citizens equality of:","options":["Income, wealth and property","Status and opportunity","Rights and privileges","Caste and creed"],"answer":1,"explanation":"The Preamble promises “EQUALITY of status and of opportunity”. It does not promise equality of income or wealth; that idea appears only as a directive (Article 38(2)) to minimise inequalities.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"उद्देशिका के अनुसार संविधान अपने सभी नागरिकों को किस प्रकार की समता सुनिश्चित करना चाहता है?","optionsHi":["आय, संपत्ति और संपदा की","प्रतिष्ठा और अवसर की","अधिकारों और विशेषाधिकारों की","जाति और पंथ की"],"explanationHi":"उद्देशिका “प्रतिष्ठा और अवसर की समता” का वचन देती है। यह आय या संपत्ति की समता का वचन नहीं देती; वह विचार केवल निदेशक तत्व (अनुच्छेद 38(2)) में असमानताएँ कम करने के रूप में आता है।"},
  {"id":"polity-preamble-59","question":"How many forms of justice are named in the Preamble?","options":["Two","Four","Three","Five"],"answer":2,"explanation":"The Preamble names three: social, economic and political justice. Legal or judicial justice is not named, a common trap.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"उद्देशिका में कितने प्रकार के न्याय का नाम लिया गया है?","optionsHi":["दो","चार","तीन","पाँच"],"explanationHi":"उद्देशिका तीन का नाम लेती है: सामाजिक, आर्थिक और राजनीतिक न्याय। विधिक या न्यायिक न्याय का नाम नहीं है, यह एक आम जाल है।"},
  {"id":"polity-preamble-60","question":"The 42nd Amendment, which changed the wording of the Preamble, received presidential assent from:","options":["V. V. Giri","Neelam Sanjiva Reddy","Zakir Husain","Fakhruddin Ali Ahmed"],"answer":3,"explanation":"President Fakhruddin Ali Ahmed (1974–77) gave assent on 18 December 1976, during the Emergency. Neelam Sanjiva Reddy became President only in July 1977.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"उद्देशिका के शब्दों में परिवर्तन करने वाले 42वें संशोधन को राष्ट्रपति की अनुमति किसने दी?","optionsHi":["वी. वी. गिरि","नीलम संजीव रेड्डी","ज़ाकिर हुसैन","फखरुद्दीन अली अहमद"],"explanationHi":"राष्ट्रपति फखरुद्दीन अली अहमद (1974–77) ने आपातकाल के दौरान 18 दिसंबर 1976 को अनुमति दी। नीलम संजीव रेड्डी जुलाई 1977 में ही राष्ट्रपति बने।"},
  {"id":"polity-preamble-61","question":"In his final speech to the Constituent Assembly (25 November 1949), Ambedkar warned that political democracy cannot last unless there lies at its base:","options":["Social democracy","A strong central government","A two-party system","Universal literacy"],"answer":0,"explanation":"Ambedkar said political democracy must rest on social democracy, a way of life recognising liberty, equality and fraternity together. This explains why the Preamble pairs political justice with social and economic justice.","difficulty":"moderate","source":"UPSC Prelims · State PSC","questionHi":"संविधान सभा में अपने अंतिम भाषण (25 नवंबर 1949) में अंबेडकर ने चेताया कि राजनीतिक लोकतंत्र तब तक नहीं टिक सकता जब तक उसके आधार में क्या न हो?","optionsHi":["सामाजिक लोकतंत्र","सशक्त केंद्र सरकार","द्विदलीय प्रणाली","सार्वभौमिक साक्षरता"],"explanationHi":"अंबेडकर ने कहा कि राजनीतिक लोकतंत्र सामाजिक लोकतंत्र पर टिका होना चाहिए, जो स्वतंत्रता, समता और बंधुता को साथ मानने वाली जीवन-पद्धति है। इसी कारण उद्देशिका राजनीतिक न्याय को सामाजिक और आर्थिक न्याय के साथ रखती है।"},
  {"id":"polity-preamble-62","question":"The Kesavananda Bharati bench, which held that the Preamble is a part of the Constitution, consisted of how many judges?","options":["Seven","Nine","Eleven","Thirteen"],"answer":3,"explanation":"Kesavananda Bharati (1973) was heard by 13 judges, the largest bench in the Court’s history, and decided by 7 to 6. Nine judges sat in Puttaswamy (privacy), not here.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"केशवानंद भारती मामले की जिस पीठ ने माना कि उद्देशिका संविधान का भाग है, उसमें कितने न्यायाधीश थे?","optionsHi":["सात","नौ","ग्यारह","तेरह"],"explanationHi":"केशवानंद भारती (1973) की सुनवाई 13 न्यायाधीशों ने की, जो न्यायालय के इतिहास की सबसे बड़ी पीठ थी, और निर्णय 7 बनाम 6 से हुआ। पुट्टस्वामी (निजता) मामले में नौ न्यायाधीश बैठे थे, इसमें नहीं।"},
  {"id":"polity-preamble-63","question":"Why was 26 January chosen as the date on which the Constitution, with its Preamble, came into force?","options":["It was the date the Constituent Assembly first met","Congress had marked it as Purna Swaraj Day in 1930","It was the date the Objectives Resolution was adopted","It was the date the Indian Independence Act was passed"],"answer":1,"explanation":"After the Lahore session (1929), Congress celebrated 26 January 1930 as Independence (Purna Swaraj) Day, so the Republic was inaugurated on that date in 1950. The Assembly first met on 9 December 1946.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"उद्देशिका सहित संविधान को लागू करने के लिए 26 जनवरी की तिथि क्यों चुनी गई?","optionsHi":["यह संविधान सभा की पहली बैठक की तिथि थी","कांग्रेस ने 1930 में इसे पूर्ण स्वराज दिवस के रूप में मनाया था","यह उद्देश्य प्रस्ताव के अंगीकरण की तिथि थी","यह भारतीय स्वतंत्रता अधिनियम के पारित होने की तिथि थी"],"explanationHi":"लाहौर अधिवेशन (1929) के बाद कांग्रेस ने 26 जनवरी 1930 को स्वतंत्रता (पूर्ण स्वराज) दिवस के रूप में मनाया, इसलिए 1950 में गणराज्य का शुभारंभ उसी तिथि को किया गया। सभा की पहली बैठक 9 दिसंबर 1946 को हुई थी।"},
  {"id":"polity-preamble-64","question":"The Preamble’s promise of liberty of “belief, faith and worship” is given concrete form chiefly by:","options":["Articles 14 to 18","Articles 19 to 22","Articles 25 to 28","Articles 29 and 30"],"answer":2,"explanation":"Articles 25 to 28 guarantee freedom of conscience and religion. Articles 19–22 deal with liberty of expression and person, and 29–30 with cultural and educational rights.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"उद्देशिका में दिए गए “विश्वास, धर्म और उपासना” की स्वतंत्रता के वचन को मुख्यतः किससे ठोस रूप मिलता है?","optionsHi":["अनुच्छेद 14 से 18","अनुच्छेद 19 से 22","अनुच्छेद 25 से 28","अनुच्छेद 29 और 30"],"explanationHi":"अनुच्छेद 25 से 28 अंतःकरण और धर्म की स्वतंत्रता की गारंटी देते हैं। अनुच्छेद 19–22 अभिव्यक्ति और व्यक्ति की स्वतंत्रता से तथा 29–30 सांस्कृतिक और शैक्षिक अधिकारों से संबंधित हैं।"},
  {"id":"polity-preamble-65","question":"India remained in the Commonwealth after becoming a Republic, accepting the British monarch only as a symbol of free association. This arrangement was settled by the:","options":["Statute of Westminster, 1931","Balfour Declaration, 1926","London Declaration, April 1949","Harare Commonwealth Declaration, 1991"],"answer":2,"explanation":"The London Declaration of April 1949 let republics stay in the Commonwealth with the monarch as Head of the Commonwealth, a symbolic role. This is why Commonwealth membership does not dilute the Preamble’s “Sovereign”.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"गणराज्य बनने के बाद भी भारत राष्ट्रमंडल में बना रहा, और ब्रिटिश सम्राट को केवल स्वतंत्र साहचर्य के प्रतीक के रूप में स्वीकार किया। यह व्यवस्था किसके द्वारा तय हुई?","optionsHi":["वेस्टमिंस्टर संविधि, 1931","बालफोर घोषणा, 1926","लंदन घोषणा, अप्रैल 1949","हरारे राष्ट्रमंडल घोषणा, 1991"],"explanationHi":"अप्रैल 1949 की लंदन घोषणा ने गणराज्यों को सम्राट के साथ राष्ट्रमंडल के प्रतीकात्मक प्रमुख के रूप में राष्ट्रमंडल में बने रहने दिया। इसी कारण राष्ट्रमंडल की सदस्यता उद्देशिका के “संप्रभु” को कमजोर नहीं करती।"},
  {"id":"polity-preamble-66","question":"Abolition of untouchability (Article 17) and of titles (Article 18) give effect most directly to which phrase of the Preamble?","options":["Equality of status","Liberty of thought","Economic justice","Dignity of the individual"],"answer":0,"explanation":"Removing untouchability and hereditary titles removes artificial distinctions of status between citizens, so they realise “equality of status”. Equality of opportunity is secured by Articles 15 and 16.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"अस्पृश्यता का उन्मूलन (अनुच्छेद 17) और उपाधियों का उन्मूलन (अनुच्छेद 18) उद्देशिका के किस वाक्यांश को सबसे प्रत्यक्ष रूप से प्रभावी करते हैं?","optionsHi":["प्रतिष्ठा की समता","विचार की स्वतंत्रता","आर्थिक न्याय","व्यक्ति की गरिमा"],"explanationHi":"अस्पृश्यता और वंशानुगत उपाधियों को हटाने से नागरिकों के बीच प्रतिष्ठा के कृत्रिम भेद मिटते हैं, इसलिए ये “प्रतिष्ठा की समता” को साकार करते हैं। अवसर की समता अनुच्छेद 15 और 16 से सुनिश्चित होती है।"},
  {"id":"polity-preamble-67","question":"The amendment to begin the Preamble with the words “In the name of God”, defeated in the Constituent Assembly in October 1949, was moved by:","options":["K. T. Shah","H. V. Kamath","Hasrat Mohani","Pandit Thakur Das Bhargava"],"answer":1,"explanation":"H. V. Kamath proposed opening with “In the name of God”; it was rejected by 68 votes to 41. K. T. Shah’s failed amendments sought to add “secular” and “socialist”.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"अक्टूबर 1949 में संविधान सभा में गिराए गए उस संशोधन को किसने प्रस्तुत किया था जिसमें उद्देशिका को “ईश्वर के नाम पर” शब्दों से शुरू करने की बात थी?","optionsHi":["के. टी. शाह","एच. वी. कामथ","हसरत मोहानी","पंडित ठाकुर दास भार्गव"],"explanationHi":"एच. वी. कामथ ने “ईश्वर के नाम पर” से शुरू करने का प्रस्ताव रखा; यह 68 के मुकाबले 41 मतों से अस्वीकृत हुआ। के. टी. शाह के असफल संशोधन “पंथनिरपेक्ष” और “समाजवादी” जोड़ने के थे।"},
  {"id":"polity-preamble-68","question":"Although it held the Preamble NOT to be a part of the Constitution, the Supreme Court in the Berubari reference (1960) described the Preamble as:","options":["The supreme law of the land","A key to open the mind of the makers","A source of legislative power","The basic structure of the Constitution"],"answer":1,"explanation":"In Berubari the Court called the Preamble a key to open the minds of the makers, useful in interpretation, yet not part of the Constitution. Kesavananda (1973) later reversed the second part.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"यद्यपि बेरुबारी संदर्भ (1960) में सर्वोच्च न्यायालय ने उद्देशिका को संविधान का भाग नहीं माना, फिर भी उसने उद्देशिका को क्या बताया?","optionsHi":["देश का सर्वोच्च कानून","निर्माताओं के मन को खोलने की कुंजी","विधायी शक्ति का स्रोत","संविधान का मूल ढाँचा"],"explanationHi":"बेरुबारी में न्यायालय ने उद्देशिका को निर्माताओं के मन को खोलने की कुंजी कहा, जो व्याख्या में उपयोगी है, फिर भी संविधान का भाग नहीं। केशवानंद (1973) ने बाद में दूसरा भाग पलट दिया।"},
  {"id":"polity-preamble-69","question":"The word “Fraternity” did not occur in the Objectives Resolution. It was included in the Preamble at the initiative of:","options":["The Union Powers Committee","The Drafting Committee","Jawaharlal Nehru while moving the Objectives Resolution","The States Committee"],"answer":1,"explanation":"The Drafting Committee under Ambedkar added the fraternity clause, noting that it was needed given the country’s diversity. The Objectives Resolution spoke of justice, liberty and equality but not fraternity.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"“बंधुता” शब्द उद्देश्य प्रस्ताव में नहीं था। इसे उद्देशिका में किसकी पहल पर शामिल किया गया?","optionsHi":["संघ शक्ति समिति","प्रारूप समिति","उद्देश्य प्रस्ताव प्रस्तुत करते समय जवाहरलाल नेहरू","राज्य समिति"],"explanationHi":"अंबेडकर की अध्यक्षता वाली प्रारूप समिति ने बंधुता खंड जोड़ा, यह कहते हुए कि देश की विविधता को देखते हुए यह आवश्यक है। उद्देश्य प्रस्ताव में न्याय, स्वतंत्रता और समता थे, बंधुता नहीं।"},
  {"id":"polity-preamble-70","question":"In which case did the Supreme Court hold that free and fair elections and democracy, which the Preamble proclaims, are basic features, striking down a clause of the 39th Amendment?","options":["Minerva Mills Ltd. v. Union of India","Golaknath v. State of Punjab","Indira Nehru Gandhi v. Raj Narain","S. R. Bommai v. Union of India"],"answer":2,"explanation":"In Indira Nehru Gandhi v. Raj Narain (1975) the Court struck down clause 4 of Article 329A (39th Amendment), which had placed the Prime Minister’s election beyond judicial scrutiny, as violating democracy, a basic feature.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"किस मामले में सर्वोच्च न्यायालय ने माना कि स्वतंत्र एवं निष्पक्ष चुनाव और लोकतंत्र, जिनकी घोषणा उद्देशिका करती है, मूल विशेषताएँ हैं, और 39वें संशोधन के एक खंड को रद्द किया?","optionsHi":["मिनर्वा मिल्स लिमिटेड बनाम भारत संघ","गोलकनाथ बनाम पंजाब राज्य","इंदिरा नेहरू गांधी बनाम राज नारायण","एस. आर. बोम्मई बनाम भारत संघ"],"explanationHi":"इंदिरा नेहरू गांधी बनाम राज नारायण (1975) में न्यायालय ने अनुच्छेद 329A (39वाँ संशोधन) के खंड 4 को, जिसने प्रधानमंत्री के निर्वाचन को न्यायिक जाँच से परे रखा था, लोकतंत्र, जो मूल विशेषता है, का उल्लंघन मानकर रद्द कर दिया।"},
  {"id":"polity-preamble-71","question":"Which of these words does NOT appear in the Preamble?","options":["Dignity","Integrity","Prosperity","Opportunity"],"answer":2,"explanation":"Dignity (of the individual), integrity (of the Nation) and opportunity (equality of) all appear. Prosperity is a plausible-sounding word that is absent.","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"इनमें से कौन-सा शब्द उद्देशिका में नहीं आता?","optionsHi":["गरिमा","अखंडता","समृद्धि","अवसर"],"explanationHi":"गरिमा (व्यक्ति की), अखंडता (राष्ट्र की) और अवसर (की समता) तीनों आते हैं। समृद्धि ऐसा शब्द है जो उचित-सा लगता है पर उद्देशिका में नहीं है।"},
  {"id":"polity-preamble-72","question":"Match the ideal of the Preamble with the provision that realises it: A. Liberty of worship B. Equality of opportunity C. Economic justice D. Political justice. 1. Article 326 (adult suffrage) 2. Article 16 3. Article 39 4. Article 25","options":["A-4, B-2, C-3, D-1","A-4, B-3, C-2, D-1","A-2, B-4, C-3, D-1","A-4, B-2, C-1, D-3"],"answer":0,"explanation":"Freedom of religion is Article 25; equal opportunity in public employment is Article 16; Article 39 directs economic justice (resources, equal pay); Article 326 gives every adult an equal vote, which is political justice.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"उद्देशिका के आदर्श को उसे साकार करने वाले प्रावधान से सुमेलित कीजिए: A. उपासना की स्वतंत्रता B. अवसर की समता C. आर्थिक न्याय D. राजनीतिक न्याय। 1. अनुच्छेद 326 (वयस्क मताधिकार) 2. अनुच्छेद 16 3. अनुच्छेद 39 4. अनुच्छेद 25","optionsHi":["A-4, B-2, C-3, D-1","A-4, B-3, C-2, D-1","A-2, B-4, C-3, D-1","A-4, B-2, C-1, D-3"],"explanationHi":"धर्म की स्वतंत्रता अनुच्छेद 25 है; सार्वजनिक नियोजन में समान अवसर अनुच्छेद 16 है; अनुच्छेद 39 आर्थिक न्याय (संसाधन, समान वेतन) का निर्देश देता है; अनुच्छेद 326 प्रत्येक वयस्क को समान मत देता है, जो राजनीतिक न्याय है।"},
  {"id":"polity-preamble-73","question":"How many of these statements about the Objectives Resolution are correct? I. Nehru moved it on 13 December 1946. II. It proposed that India be an “Independent Sovereign Republic”. III. It was adopted unanimously on 22 January 1947. IV. Members of the Muslim League took part in adopting it.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. IV is wrong: the Muslim League boycotted the Constituent Assembly, so its members were not present when the resolution was adopted.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"उद्देश्य प्रस्ताव के बारे में इनमें से कितने कथन सही हैं? I. नेहरू ने इसे 13 दिसंबर 1946 को प्रस्तुत किया। II. इसमें प्रस्ताव था कि भारत “स्वतंत्र संप्रभु गणराज्य” हो। III. यह 22 जनवरी 1947 को सर्वसम्मति से अंगीकृत हुआ। IV. मुस्लिम लीग के सदस्यों ने इसके अंगीकरण में भाग लिया।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। IV गलत है: मुस्लिम लीग ने संविधान सभा का बहिष्कार किया था, इसलिए प्रस्ताव अंगीकृत होते समय उसके सदस्य उपस्थित नहीं थे।"},
  {"id":"polity-preamble-74","question":"Assertion (A): India’s membership of the Commonwealth does not affect the Preamble’s description of India as a sovereign republic. Reason (R): The British monarch is accepted only as a symbol of the free association of member nations and has no function in India’s government.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Membership is voluntary and the Head of the Commonwealth exercises no authority over India, which is exactly why sovereignty and the republican character remain intact.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"अभिकथन (A): भारत की राष्ट्रमंडल सदस्यता उद्देशिका में भारत को संप्रभु गणराज्य बताने को प्रभावित नहीं करती। कारण (R): ब्रिटिश सम्राट को केवल सदस्य राष्ट्रों के स्वतंत्र साहचर्य के प्रतीक के रूप में स्वीकार किया जाता है और भारत की सरकार में उसकी कोई भूमिका नहीं है।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A सत्य है परंतु R असत्य है","A असत्य है परंतु R सत्य है"],"explanationHi":"सदस्यता स्वैच्छिक है और राष्ट्रमंडल का प्रमुख भारत पर कोई अधिकार नहीं रखता, इसीलिए संप्रभुता और गणराज्यीय स्वरूप अक्षुण्ण रहते हैं।"},
  {"id":"polity-preamble-75","question":"Assertion (A): The words “We, the people of India” in the Preamble express popular sovereignty. Reason (R): The Constituent Assembly that adopted the Preamble was directly elected on the basis of universal adult franchise.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":2,"explanation":"A is true: the Constitution draws its authority from the people. R is false: under the Cabinet Mission Plan the members for the provinces were elected indirectly by provincial assemblies, themselves chosen on a limited franchise.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"अभिकथन (A): उद्देशिका में “हम, भारत के लोग” शब्द जन-संप्रभुता को व्यक्त करते हैं। कारण (R): उद्देशिका को अंगीकृत करने वाली संविधान सभा वयस्क मताधिकार के आधार पर प्रत्यक्ष रूप से निर्वाचित थी।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A सत्य है परंतु R असत्य है","A असत्य है परंतु R सत्य है"],"explanationHi":"A सत्य है: संविधान अपनी सत्ता जनता से प्राप्त करता है। R असत्य है: कैबिनेट मिशन योजना के अंतर्गत प्रांतों के सदस्य प्रांतीय विधानसभाओं द्वारा अप्रत्यक्ष रूप से चुने गए थे, जो स्वयं सीमित मताधिकार पर चुनी गई थीं।"},
  {"id":"polity-preamble-76","question":"Arrange in chronological order: 1. London Declaration on the Commonwealth 2. Adoption of the Preamble 3. Adoption of the Objectives Resolution 4. Indira Nehru Gandhi v. Raj Narain judgment","options":["3, 2, 1, 4","1, 3, 2, 4","3, 1, 2, 4","3, 1, 4, 2"],"answer":2,"explanation":"Objectives Resolution adopted 22 January 1947; London Declaration April 1949; Preamble adopted 26 November 1949; Raj Narain judgment November 1975.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"कालक्रम के अनुसार व्यवस्थित कीजिए: 1. राष्ट्रमंडल पर लंदन घोषणा 2. उद्देशिका का अंगीकरण 3. उद्देश्य प्रस्ताव का अंगीकरण 4. इंदिरा नेहरू गांधी बनाम राज नारायण निर्णय","optionsHi":["3, 2, 1, 4","1, 3, 2, 4","3, 1, 2, 4","3, 1, 4, 2"],"explanationHi":"उद्देश्य प्रस्ताव 22 जनवरी 1947 को अंगीकृत; लंदन घोषणा अप्रैल 1949; उद्देशिका 26 नवंबर 1949 को अंगीकृत; राज नारायण निर्णय नवंबर 1975।"},
  {"id":"polity-preamble-77","question":"How many of these statements about the 42nd Amendment are correct? I. It is often called a “mini-Constitution”. II. It received assent while Fakhruddin Ali Ahmed was President. III. It inserted the Fundamental Duties. IV. It changed “unity of the Nation” to “unity and integrity of the Nation”.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. The 1976 amendment made such sweeping changes that it earned the name mini-Constitution; besides the Preamble, it added Part IV-A (Fundamental Duties).","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"42वें संशोधन के बारे में इनमें से कितने कथन सही हैं? I. इसे प्रायः “लघु संविधान” कहा जाता है। II. इसे अनुमति तब मिली जब फखरुद्दीन अली अहमद राष्ट्रपति थे। III. इसने मौलिक कर्तव्य जोड़े। IV. इसने “राष्ट्र की एकता” को “राष्ट्र की एकता और अखंडता” में बदला।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं। 1976 के संशोधन ने इतने व्यापक परिवर्तन किए कि इसे लघु संविधान कहा गया; उद्देशिका के अलावा इसने भाग IV-क (मौलिक कर्तव्य) जोड़ा।"},
  {"id":"polity-preamble-78","question":"How many of these are expressions of ECONOMIC justice in the Constitution? I. Article 39(d) – equal pay for equal work for men and women II. Article 43 – living wage for workers III. Article 326 – adult suffrage IV. Article 17 – abolition of untouchability","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"Only I and II concern economic justice. Article 326 secures political justice and Article 17 secures social justice.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"संविधान में इनमें से कितने आर्थिक न्याय की अभिव्यक्तियाँ हैं? I. अनुच्छेद 39(d) – स्त्री और पुरुष के लिए समान कार्य के लिए समान वेतन II. अनुच्छेद 43 – कामगारों के लिए निर्वाह मजदूरी III. अनुच्छेद 326 – वयस्क मताधिकार IV. अनुच्छेद 17 – अस्पृश्यता का उन्मूलन","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल I और II आर्थिक न्याय से संबंधित हैं। अनुच्छेद 326 राजनीतिक न्याय और अनुच्छेद 17 सामाजिक न्याय सुनिश्चित करता है।"},
  {"id":"polity-preamble-79","question":"How many of these statements about the “Democratic” character in the Preamble are correct? I. It covers social and economic democracy as well as political democracy. II. The Constitution makes no provision for national referendums or popular initiatives. III. Article 326 gives effect to it through universal adult franchise. IV. India follows a representative, parliamentary form of democracy.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. The Preamble's democracy is political, social and economic; Article 326 gives universal adult franchise; and India is a representative, parliamentary democracy whose Constitution has no device of direct democracy such as referendum or initiative.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"उद्देशिका के “लोकतंत्रात्मक” स्वरूप के बारे में इनमें से कितने कथन सही हैं? I. इसमें राजनीतिक लोकतंत्र के साथ सामाजिक और आर्थिक लोकतंत्र भी शामिल है। II. संविधान राष्ट्रीय जनमत संग्रह या लोक-पहल का कोई प्रावधान नहीं करता। III. अनुच्छेद 326 सार्वभौमिक वयस्क मताधिकार द्वारा इसे प्रभावी करता है। IV. भारत प्रतिनिधिक, संसदीय लोकतंत्र अपनाता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं। उद्देशिका का लोकतंत्र राजनीतिक, सामाजिक और आर्थिक है; अनुच्छेद 326 सार्वभौमिक वयस्क मताधिकार देता है; और भारत प्रतिनिधिक, संसदीय लोकतंत्र है जिसके संविधान में जनमत संग्रह या पहल जैसा प्रत्यक्ष लोकतंत्र का कोई साधन नहीं है।"},
  {"id":"polity-preamble-80","question":"Arrange these events of the Constituent Assembly in chronological order: 1. First meeting of the Assembly 2. Appointment of the Drafting Committee 3. Adoption of the Objectives Resolution 4. Members sign the Constitution","options":["1, 3, 2, 4","1, 2, 3, 4","3, 1, 2, 4","1, 3, 4, 2"],"answer":0,"explanation":"First meeting 9 December 1946; Objectives Resolution adopted 22 January 1947; Drafting Committee set up 29 August 1947; members signed the Constitution on 24 January 1950.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"संविधान सभा की इन घटनाओं को कालक्रम में व्यवस्थित कीजिए: 1. सभा की पहली बैठक 2. प्रारूप समिति की नियुक्ति 3. उद्देश्य प्रस्ताव का अंगीकरण 4. सदस्यों द्वारा संविधान पर हस्ताक्षर","optionsHi":["1, 3, 2, 4","1, 2, 3, 4","3, 1, 2, 4","1, 3, 4, 2"],"explanationHi":"पहली बैठक 9 दिसंबर 1946; उद्देश्य प्रस्ताव 22 जनवरी 1947 को अंगीकृत; प्रारूप समिति 29 अगस्त 1947 को गठित; सदस्यों ने 24 जनवरी 1950 को संविधान पर हस्ताक्षर किए।"},
  {"id":"polity-preamble-81","question":"According to the exact wording of the Preamble, justice, liberty and equality are to be secured to:","options":["All persons in India","All the people of India","All its citizens","All residents of the Union"],"answer":2,"explanation":"The Preamble says the people resolve “to secure to all its citizens” justice, liberty and equality. Many Fundamental Rights extend to all persons, which is why “persons” is the tempting wrong choice.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"उद्देशिका के सटीक शब्दों के अनुसार न्याय, स्वतंत्रता और समता किन्हें सुनिश्चित की जानी है?","optionsHi":["भारत के सभी व्यक्तियों को","भारत के सभी लोगों को","इसके सभी नागरिकों को","संघ के सभी निवासियों को"],"explanationHi":"उद्देशिका कहती है कि लोग “इसके समस्त नागरिकों को” न्याय, स्वतंत्रता और समता सुनिश्चित करने का संकल्प लेते हैं। कई मौलिक अधिकार सभी व्यक्तियों को मिलते हैं, इसीलिए “व्यक्ति” आकर्षक गलत विकल्प है।"},
  {"id":"polity-preamble-82","question":"How many of these statements about the Kesavananda Bharati judgment are correct? I. It was decided by a majority of 7 to 6. II. It held that the Preamble can be amended under Article 368. III. It held that the basic structure cannot be destroyed by amendment. IV. It overruled the Golaknath judgment.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. The Court overruled Golaknath (Parliament can amend any part, including Fundamental Rights and the Preamble) but held the basic structure beyond the amending power.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"केशवानंद भारती निर्णय के बारे में इनमें से कितने कथन सही हैं? I. यह 7 बनाम 6 के बहुमत से तय हुआ। II. इसमें माना गया कि उद्देशिका में अनुच्छेद 368 के अंतर्गत संशोधन हो सकता है। III. इसमें माना गया कि मूल ढाँचे को संशोधन द्वारा नष्ट नहीं किया जा सकता। IV. इसने गोलकनाथ निर्णय को पलट दिया।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं। न्यायालय ने गोलकनाथ को पलटा (संसद मौलिक अधिकारों और उद्देशिका सहित किसी भी भाग में संशोधन कर सकती है), परंतु मूल ढाँचे को संशोधन की शक्ति से परे माना।"},
  {"id":"polity-preamble-83","question":"In what order do the four ideals of Justice, Liberty, Equality and Fraternity appear in the Preamble?","options":["Justice, Liberty, Equality, Fraternity","Liberty, Equality, Justice, Fraternity","Justice, Equality, Liberty, Fraternity","Equality, Liberty, Justice, Fraternity"],"answer":0,"explanation":"The Preamble lists Justice (social, economic and political) first, then Liberty, then Equality, and ends with Fraternity. The French slogan order, Liberty–Equality–Fraternity, is the trap: the Indian text puts Justice before all three.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"उद्देशिका में न्याय, स्वतंत्रता, समता और बंधुता, इन चार आदर्शों का क्रम क्या है?","optionsHi":["न्याय, स्वतंत्रता, समता, बंधुता","स्वतंत्रता, समता, न्याय, बंधुता","न्याय, समता, स्वतंत्रता, बंधुता","समता, स्वतंत्रता, न्याय, बंधुता"],"explanationHi":"उद्देशिका में पहले न्याय (सामाजिक, आर्थिक और राजनीतिक), फिर स्वतंत्रता, फिर समता आता है और अंत में बंधुता। फ्रांसीसी नारे का क्रम, स्वतंत्रता–समता–बंधुता, जाल है: भारतीय पाठ में न्याय तीनों से पहले आता है।"},
  {"id":"polity-preamble-84","question":"Where is the Preamble placed in the Constitution of India?","options":["In Part I, as clause (1) of Article 1","At the start of Part III, before Article 12","In the First Schedule, with the States","Before Part I; it is not part of any Part"],"answer":3,"explanation":"The Preamble is the introductory statement that comes before Part I (The Union and its Territory). It belongs to no Part and carries no Article number.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"भारत के संविधान में उद्देशिका कहाँ स्थित है?","optionsHi":["भाग I में, अनुच्छेद 1 के खंड (1) के रूप में","भाग III के आरंभ में, अनुच्छेद 12 से पहले","पहली अनुसूची में, राज्यों के साथ","भाग I से पहले; यह किसी भाग का हिस्सा नहीं है"],"explanationHi":"उद्देशिका भाग I (संघ और उसका राज्यक्षेत्र) से पहले आने वाला परिचयात्मक कथन है। यह किसी भाग में नहीं आती और इसका कोई अनुच्छेद क्रमांक नहीं है।"},
  {"id":"polity-preamble-85","question":"According to the Preamble, the people of India adopted, enacted and gave to themselves the Constitution \"in our ___\".","options":["Constituent Assembly","Parliament","Provisional Parliament","Drafting Committee"],"answer":0,"explanation":"The closing words read: \"In our Constituent Assembly this twenty-sixth day of November, 1949, do hereby adopt, enact and give to ourselves this Constitution.\" The Drafting Committee only prepared the draft; the Assembly adopted it.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"उद्देशिका के अनुसार भारत के लोगों ने संविधान को “अपनी ___ में” अंगीकृत, अधिनियमित और आत्मार्पित किया।","optionsHi":["संविधान सभा","संसद","अंतरिम संसद","प्रारूप समिति"],"explanationHi":"समापन शब्द हैं: “अपनी संविधान सभा में आज तारीख 26 नवंबर, 1949 ई. को एतद्द्वारा इस संविधान को अंगीकृत, अधिनियमित और आत्मार्पित करते हैं।” प्रारूप समिति ने केवल मसौदा तैयार किया; सभा ने इसे अंगीकृत किया।"},
  {"id":"polity-preamble-86","question":"The Preamble is said to reveal four ingredients or components of the Constitution. Which of these is NOT one of them?","options":["The source of authority of the Constitution","The nature of the Indian State","The objectives of the Constitution","The procedure for amending the Constitution"],"answer":3,"explanation":"The Preamble reveals the source of authority (the people of India), the nature of the State (sovereign, socialist, secular, democratic, republic), its objectives (justice, liberty, equality, fraternity) and the date of adoption (26 November 1949). Amendment procedure is in Article 368, not in the Preamble.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"कहा जाता है कि उद्देशिका संविधान के चार घटक प्रकट करती है। इनमें से कौन-सा उनमें से एक नहीं है?","optionsHi":["संविधान की सत्ता का स्रोत","भारतीय राज्य का स्वरूप","संविधान के उद्देश्य","संविधान में संशोधन की प्रक्रिया"],"explanationHi":"उद्देशिका सत्ता का स्रोत (भारत के लोग), राज्य का स्वरूप (संप्रभु, समाजवादी, पंथनिरपेक्ष, लोकतंत्रात्मक, गणराज्य), उसके उद्देश्य (न्याय, स्वतंत्रता, समता, बंधुता) और अंगीकरण की तिथि (26 नवंबर 1949) प्रकट करती है। संशोधन की प्रक्रिया अनुच्छेद 368 में है, उद्देशिका में नहीं।"},
  {"id":"polity-preamble-87","question":"Who said in the Constituent Assembly that the Preamble \"expresses what we had thought or dreamt so long\"?","options":["Alladi Krishnaswamy Iyer","Kanaiyalal M. Munshi","Sir Ernest Barker","Nani Ardeshir Palkhivala"],"answer":0,"explanation":"The remark is Alladi Krishnaswamy Iyer's, a member of the Drafting Committee. Munshi called the Preamble the \"political horoscope\", Barker its \"key-note\" and Palkhivala its \"identity card\".","difficulty":"moderate","source":"UPSC Prelims · State PSCs","questionHi":"संविधान सभा में किसने कहा कि उद्देशिका “वह व्यक्त करती है जो हम इतने समय से सोचते या सपने देखते आए थे”?","optionsHi":["अल्लादि कृष्णास्वामी अय्यर","कन्हैयालाल एम. मुंशी","सर अर्नेस्ट बार्कर","नानी अर्देशिर पालखीवाला"],"explanationHi":"यह टिप्पणी प्रारूप समिति के सदस्य अल्लादि कृष्णास्वामी अय्यर की है। मुंशी ने उद्देशिका को “राजनीतिक जन्मकुंडली”, बार्कर ने “कुंजी-स्वर” और पालखीवाला ने “पहचान पत्र” कहा।"},
  {"id":"polity-preamble-88","question":"Which Chief Justice of India wrote that the Preamble \"resembles the Declaration of Independence of the United States of America, but is more than a declaration\"?","options":["S. M. Sikri","M. Hidayatullah","P. B. Gajendragadkar","Y. V. Chandrachud"],"answer":1,"explanation":"M. Hidayatullah described the Preamble this way and also called it the soul of the Constitution, laying down the pattern of the political society. The \"soul\" description in the Constituent Assembly came from Thakur Das Bhargava.","difficulty":"moderate","source":"UPSC Prelims · State PSCs","questionHi":"भारत के किस मुख्य न्यायाधीश ने लिखा कि उद्देशिका “अमेरिका की स्वतंत्रता की घोषणा से मिलती-जुलती है, परंतु घोषणा से अधिक है”?","optionsHi":["एस. एम. सीकरी","एम. हिदायतुल्ला","पी. बी. गजेंद्रगडकर","वाई. वी. चंद्रचूड़"],"explanationHi":"एम. हिदायतुल्ला ने उद्देशिका का यही वर्णन किया और इसे संविधान की आत्मा भी कहा, जो राजनीतिक समाज का स्वरूप निर्धारित करती है। संविधान सभा में “आत्मा” का वर्णन ठाकुर दास भार्गव ने किया था।"},
  {"id":"polity-preamble-89","question":"The Preamble's promise of \"liberty of thought and expression\" is given concrete form chiefly by which Article?","options":["Article 14","Article 19(1)(a)","Article 19(1)(c)","Article 25(1)"],"answer":1,"explanation":"Article 19(1)(a) guarantees to citizens the freedom of speech and expression. Article 19(1)(c) is the freedom of association, and Article 25 covers the later words of the same clause, \"belief, faith and worship\", not thought and expression.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"उद्देशिका के “विचार और अभिव्यक्ति की स्वतंत्रता” के वचन को मुख्यतः किस अनुच्छेद से ठोस रूप मिलता है?","optionsHi":["अनुच्छेद 14","अनुच्छेद 19(1)(a)","अनुच्छेद 19(1)(c)","अनुच्छेद 25(1)"],"explanationHi":"अनुच्छेद 19(1)(a) नागरिकों को वाक् और अभिव्यक्ति की स्वतंत्रता की गारंटी देता है। अनुच्छेद 19(1)(c) संगम की स्वतंत्रता है, और अनुच्छेद 25 उसी खंड के बाद के शब्दों, “विश्वास, धर्म और उपासना”, को समेटता है, विचार और अभिव्यक्ति को नहीं।"},
  {"id":"polity-preamble-90","question":"The word \"Republic\" in the Preamble is given effect chiefly by which provision?","options":["Article 54 – election of the President by an electoral college","Article 74 – Council of Ministers to aid and advise the President","Article 61 – procedure for impeachment of the President","Article 72 – pardoning power of the President"],"answer":0,"explanation":"A republic has an elected head of state rather than a hereditary one. Article 54 provides for the President's election by an electoral college of elected MPs and MLAs, which makes India a republic.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"उद्देशिका के “गणराज्य” शब्द को मुख्यतः किस प्रावधान से प्रभाव मिलता है?","optionsHi":["अनुच्छेद 54 – निर्वाचक मंडल द्वारा राष्ट्रपति का निर्वाचन","अनुच्छेद 74 – राष्ट्रपति को सहायता और सलाह देने के लिए मंत्रिपरिषद","अनुच्छेद 61 – राष्ट्रपति पर महाभियोग की प्रक्रिया","अनुच्छेद 72 – राष्ट्रपति की क्षमादान शक्ति"],"explanationHi":"गणराज्य में राज्य प्रमुख वंशानुगत नहीं, निर्वाचित होता है। अनुच्छेद 54 निर्वाचित सांसदों और विधायकों के निर्वाचक मंडल द्वारा राष्ट्रपति के निर्वाचन का प्रावधान करता है, जो भारत को गणराज्य बनाता है।"},
  {"id":"polity-preamble-91","question":"The thirteen-judge bench that decided Kesavananda Bharati v. State of Kerala (1973), and held the Preamble to be a part of the Constitution, was headed by Chief Justice:","options":["A. N. Ray","P. N. Bhagwati","Y. V. Chandrachud","S. M. Sikri"],"answer":3,"explanation":"Chief Justice S. M. Sikri headed the bench; judgment was delivered on 24 April 1973, a day before he retired. A. N. Ray, who dissented, was then appointed Chief Justice over three senior judges.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"केशवानंद भारती बनाम केरल राज्य (1973) का निर्णय करने वाली, और उद्देशिका को संविधान का भाग मानने वाली, तेरह न्यायाधीशों की पीठ की अध्यक्षता किस मुख्य न्यायाधीश ने की?","optionsHi":["ए. एन. रे","पी. एन. भगवती","वाई. वी. चंद्रचूड़","एस. एम. सीकरी"],"explanationHi":"मुख्य न्यायाधीश एस. एम. सीकरी ने पीठ की अध्यक्षता की; निर्णय 24 अप्रैल 1973 को, उनकी सेवानिवृत्ति से एक दिन पहले, सुनाया गया। असहमति जताने वाले ए. एन. रे को तब तीन वरिष्ठ न्यायाधीशों को लाँघकर मुख्य न्यायाधीश नियुक्त किया गया।"},
  {"id":"polity-preamble-92","question":"Which Section of the Constitution (Forty-second Amendment) Act, 1976 amended the Preamble?","options":["Section 4","Section 55","Section 2","Section 59"],"answer":2,"explanation":"Section 2 inserted \"Socialist Secular\" and \"and integrity\" into the Preamble. Sections 4 (extending Article 31C) and 55 (barring judicial review of amendments under Article 368) were the ones struck down in Minerva Mills (1980); Section 2 was not challenged there.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"संविधान (बयालीसवाँ संशोधन) अधिनियम, 1976 की किस धारा ने उद्देशिका में संशोधन किया?","optionsHi":["धारा 4","धारा 55","धारा 2","धारा 59"],"explanationHi":"धारा 2 ने उद्देशिका में “समाजवादी पंथनिरपेक्ष” और “और अखंडता” जोड़ा। धारा 4 (अनुच्छेद 31C का विस्तार) और धारा 55 (अनुच्छेद 368 के अंतर्गत संशोधनों की न्यायिक समीक्षा पर रोक) को मिनर्वा मिल्स (1980) में रद्द किया गया था; धारा 2 को वहाँ चुनौती नहीं दी गई थी।"},
  {"id":"polity-preamble-93","question":"Although \"secular\" entered the Preamble only in 1976, the word already appeared in the original Constitution in:","options":["Article 15(1)","Article 25(2)(a)","Article 28(1)","Article 19(1)(g)"],"answer":1,"explanation":"Article 25(2)(a) lets the State regulate \"any economic, financial, political or other secular activity which may be associated with religious practice\". So the word was in the text from 1950, though the Preamble did not use it.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"यद्यपि “पंथनिरपेक्ष” शब्द उद्देशिका में 1976 में ही आया, यह मूल संविधान में पहले से किसमें था?","optionsHi":["अनुच्छेद 15(1)","अनुच्छेद 25(2)(a)","अनुच्छेद 28(1)","अनुच्छेद 19(1)(g)"],"explanationHi":"अनुच्छेद 25(2)(a) राज्य को “धार्मिक आचरण से जुड़े किसी आर्थिक, वित्तीय, राजनीतिक या अन्य लौकिक (पंथनिरपेक्ष) क्रियाकलाप” को विनियमित करने देता है। इसलिए यह शब्द 1950 से पाठ में था, भले उद्देशिका में न रहा हो।"},
  {"id":"polity-preamble-94","question":"A political association seeking registration as a party must declare that it will bear true faith and allegiance to the Constitution and to the principles of socialism, secularism and democracy. This requirement is laid down in:","options":["Section 29A(5) of the Representation of the People Act","Article 324, on the Election Commission's powers","The Tenth Schedule","Section 123 of the Representation of the People Act, 1951"],"answer":0,"explanation":"Section 29A, inserted in 1989, governs registration of parties with the Election Commission; sub-section (5) requires this declaration. Section 123 lists corrupt practices, and the Tenth Schedule deals with defection.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"पार्टी के रूप में पंजीकरण चाहने वाले राजनीतिक संगठन को घोषणा करनी होती है कि वह संविधान और समाजवाद, पंथनिरपेक्षता तथा लोकतंत्र के सिद्धांतों के प्रति सच्ची श्रद्धा और निष्ठा रखेगा। यह अपेक्षा कहाँ निर्धारित है?","optionsHi":["जनप्रतिनिधित्व अधिनियम की धारा 29A(5)","अनुच्छेद 324, निर्वाचन आयोग की शक्तियों पर","दसवीं अनुसूची","धारा 123, जनप्रतिनिधित्व अधिनियम, 1951"],"explanationHi":"1989 में जोड़ी गई धारा 29A निर्वाचन आयोग में दलों के पंजीकरण को नियंत्रित करती है; उप-धारा (5) यह घोषणा आवश्यक बनाती है। धारा 123 भ्रष्ट आचरणों की सूची देती है, और दसवीं अनुसूची दल-बदल से संबंधित है।"},
  {"id":"polity-preamble-95","question":"Before \"integrity\" was added to the Preamble in 1976, the words \"sovereignty and integrity of India\" had already been made a ground for restricting freedoms under Article 19 by the:","options":["1st Amendment, 1951","24th Amendment, 1971","44th Amendment, 1978","16th Amendment, 1963"],"answer":3,"explanation":"The 16th Amendment (1963) added \"sovereignty and integrity of India\" to clauses (2), (3) and (4) of Article 19 and to the oaths in the Third Schedule. The 1st Amendment had added public order, friendly relations with foreign States and incitement to an offence.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"1976 में उद्देशिका में “अखंडता” जोड़े जाने से पहले ही “भारत की संप्रभुता और अखंडता” को अनुच्छेद 19 के अंतर्गत स्वतंत्रताओं पर निर्बंधन का आधार किस संशोधन ने बनाया था?","optionsHi":["पहला संशोधन, 1951","24वाँ संशोधन, 1971","44वाँ संशोधन, 1978","16वाँ संशोधन, 1963"],"explanationHi":"16वें संशोधन (1963) ने “भारत की संप्रभुता और अखंडता” को अनुच्छेद 19 के खंड (2), (3) और (4) तथा तीसरी अनुसूची की शपथों में जोड़ा। पहले संशोधन ने लोक व्यवस्था, विदेशी राज्यों से मैत्रीपूर्ण संबंध और अपराध-उद्दीपन जोड़े थे।"},
  {"id":"polity-preamble-96","question":"The idea that the Constitution has \"basic features\" that an amendment might not be able to change, later linked to the Preamble, was first hinted at by Justice ___ in Sajjan Singh v. State of Rajasthan (1965).","options":["Koka Subba Rao","H. R. Khanna","J. R. Mudholkar","P. B. Gajendragadkar"],"answer":2,"explanation":"Justice J. R. Mudholkar, concurring in Sajjan Singh, asked whether changing a basic feature of the Constitution would be an amendment at all; Chief Justice Gajendragadkar wrote the majority upholding the 17th Amendment. The idea grew into the basic structure doctrine in Kesavananda (1973), and Subba Rao wrote the Golaknath majority (1967).","difficulty":"hard","source":"UPSC Prelims · State PSCs","questionHi":"संविधान की ऐसी “मूल विशेषताएँ” होने का विचार, जिन्हें संशोधन शायद न बदल सके, जो बाद में उद्देशिका से जोड़ा गया, सज्जन सिंह बनाम राजस्थान राज्य (1965) में पहली बार न्यायमूर्ति ___ ने संकेतित किया।","optionsHi":["कोका सुब्बा राव","एच. आर. खन्ना","जे. आर. मुधोलकर","पी. बी. गजेंद्रगडकर"],"explanationHi":"सज्जन सिंह में सहमति देते हुए न्यायमूर्ति जे. आर. मुधोलकर ने पूछा कि संविधान की किसी मूल विशेषता को बदलना क्या संशोधन कहलाएगा; मुख्य न्यायाधीश गजेंद्रगडकर ने 17वें संशोधन को बरकरार रखने वाला बहुमत का निर्णय लिखा। यह विचार केशवानंद (1973) में मूल ढाँचे के सिद्धांत के रूप में विकसित हुआ, और सुब्बा राव ने गोलकनाथ (1967) का बहुमत निर्णय लिखा था।"},
  {"id":"polity-preamble-97","question":"In his speech of 25 November 1949, Ambedkar defined \"fraternity\" as:","options":["A sense of common brotherhood of all Indians","The equal distribution of material resources","Freedom of conscience for all persons","The use of a single national language"],"answer":0,"explanation":"Ambedkar said fraternity means \"a sense of common brotherhood of all Indians\", the principle that gives unity and solidarity to social life. Without it, he warned, liberty and equality would be no deeper than coats of paint.","difficulty":"hard","source":"UPSC Prelims · State PSCs","questionHi":"25 नवंबर 1949 के अपने भाषण में अंबेडकर ने “बंधुता” को क्या परिभाषित किया?","optionsHi":["सभी भारतीयों में साझा भाईचारे की भावना","भौतिक संसाधनों का समान वितरण","सभी व्यक्तियों के लिए अंतःकरण की स्वतंत्रता","एकल राष्ट्रीय भाषा का प्रयोग"],"explanationHi":"अंबेडकर ने कहा कि बंधुता का अर्थ है “सभी भारतीयों में साझा भाईचारे की भावना”, वह सिद्धांत जो सामाजिक जीवन को एकता और एकजुटता देता है। उसके बिना, उन्होंने चेताया, स्वतंत्रता और समता रंग की परतों से अधिक गहरी नहीं होंगी।"},
  {"id":"polity-preamble-98","question":"Which freedom listed in the Objectives Resolution (1946–47) was left out of the liberty clause of the Preamble?","options":["Freedom of thought","Freedom of vocation","Freedom of expression","Freedom of worship"],"answer":1,"explanation":"The Objectives Resolution promised freedom of \"thought, expression, belief, faith, worship, vocation, association and action\". The Preamble kept only thought, expression, belief, faith and worship; vocation and association are protected in Article 19 instead.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"उद्देश्य प्रस्ताव (1946–47) में सूचीबद्ध कौन-सी स्वतंत्रता उद्देशिका के स्वतंत्रता खंड से छोड़ दी गई?","optionsHi":["विचार की स्वतंत्रता","वृत्ति की स्वतंत्रता","अभिव्यक्ति की स्वतंत्रता","उपासना की स्वतंत्रता"],"explanationHi":"उद्देश्य प्रस्ताव ने “विचार, अभिव्यक्ति, विश्वास, धर्म, उपासना, वृत्ति, संगम और कर्म” की स्वतंत्रता का वचन दिया था। उद्देशिका में केवल विचार, अभिव्यक्ति, विश्वास, धर्म और उपासना रखे गए; वृत्ति और संगम अनुच्छेद 19 में संरक्षित हैं।"},
  {"id":"polity-preamble-99","question":"The Objectives Resolution called India an \"Independent Sovereign Republic\" without using the word \"Democratic\". How did Nehru explain this?","options":["Democracy was to be decided later by a referendum","The princely States had objected to the word","The word was left to the Drafting Committee to add","The word \"Republic\" already implied democracy"],"answer":3,"explanation":"Nehru told the Assembly that the word \"democratic\" was left out because \"republic\" obviously contains it. The Preamble adopted in 1949 did use \"Democratic\".","difficulty":"hard","source":"UPSC Prelims · State PSCs","questionHi":"उद्देश्य प्रस्ताव ने भारत को “स्वतंत्र संप्रभु गणराज्य” कहा, “लोकतंत्रात्मक” शब्द का प्रयोग किए बिना। नेहरू ने इसे कैसे समझाया?","optionsHi":["लोकतंत्र का निर्णय बाद में जनमत संग्रह से होना था","देशी रियासतों ने इस शब्द पर आपत्ति की थी","इस शब्द को जोड़ना प्रारूप समिति पर छोड़ा गया था","“गणराज्य” शब्द में पहले से लोकतंत्र निहित है"],"explanationHi":"नेहरू ने सभा से कहा कि “लोकतंत्रात्मक” शब्द इसलिए छोड़ा गया क्योंकि “गणराज्य” में वह स्पष्टतः समाहित है। 1949 में अंगीकृत उद्देशिका में “लोकतंत्रात्मक” शब्द का प्रयोग हुआ।"},
  {"id":"polity-preamble-100","question":"Chief Justice Sikri's list of basic features in Kesavananda Bharati (1973) did NOT include:","options":["Supremacy of the Constitution","Republican and democratic form of government","A Uniform Civil Code","Secular character of the Constitution"],"answer":2,"explanation":"Sikri listed the supremacy of the Constitution, the republican and democratic form of government, its secular character, the separation of powers and its federal character. A Uniform Civil Code is only a Directive Principle (Article 44), not a basic feature.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"केशवानंद भारती (1973) में मुख्य न्यायाधीश सीकरी की मूल विशेषताओं की सूची में क्या शामिल नहीं था?","optionsHi":["संविधान की सर्वोच्चता","गणराज्यात्मक और लोकतंत्रात्मक शासन प्रणाली","समान नागरिक संहिता","संविधान का पंथनिरपेक्ष स्वरूप"],"explanationHi":"सीकरी ने संविधान की सर्वोच्चता, गणराज्यात्मक और लोकतंत्रात्मक शासन प्रणाली, उसका पंथनिरपेक्ष स्वरूप, शक्तियों का पृथक्करण और उसका संघीय स्वरूप गिनाए। समान नागरिक संहिता केवल एक निदेशक तत्व (अनुच्छेद 44) है, मूल विशेषता नहीं।"},
  {"id":"polity-preamble-101","question":"How many of these statements are correct? I. The word \"secular\" appeared in the Preamble of the original Constitution. II. Section 29A(5) of the Representation of the People Act, 1951 requires registered parties to declare allegiance to secularism. III. Chief Justice Subba Rao listed the secular character of the Constitution among its basic features in Golak Nath. IV. Article 366 of the Constitution defines the word \"secular\".","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only II is correct (Section 29A(5) RPA). I is wrong: \"secular\" entered the Preamble only in 1976, though Article 25(2)(a) used it from the start. III is wrong: the basic-features list came from CJ Sikri in Kesavananda (1973), not Golak Nath. IV is wrong: the Constitution never defines \"secular\".","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"इनमें से कितने कथन सही हैं? I. मूल संविधान की उद्देशिका में “पंथनिरपेक्ष” शब्द था। II. जनप्रतिनिधित्व अधिनियम, 1951 की धारा 29A(5) पंजीकृत दलों से पंथनिरपेक्षता के प्रति निष्ठा की घोषणा माँगती है। III. मुख्य न्यायाधीश सुब्बा राव ने गोलकनाथ में संविधान के पंथनिरपेक्ष स्वरूप को उसकी मूल विशेषताओं में गिना। IV. संविधान का अनुच्छेद 366 “पंथनिरपेक्ष” शब्द की परिभाषा देता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल II सही है (धारा 29A(5), जनप्रतिनिधित्व अधिनियम)। I गलत है: “पंथनिरपेक्ष” उद्देशिका में केवल 1976 में आया, यद्यपि अनुच्छेद 25(2)(a) में यह शुरू से था। III गलत है: मूल विशेषताओं की सूची केशवानंद (1973) में मुख्य न्यायाधीश सीकरी की थी, गोलकनाथ में नहीं। IV गलत है: संविधान “पंथनिरपेक्ष” को कभी परिभाषित नहीं करता।"},
  {"id":"polity-preamble-102","question":"In his final speech to the Constituent Assembly on 25 November 1949, Ambedkar gave several warnings. How many of these were among them? I. Give up bloody methods of revolution, including civil disobedience, non-cooperation and satyagraha, where constitutional methods are open. II. Do not lay your liberties at the feet of even a great man (beware of hero-worship in politics). III. Make political democracy a social democracy as well. IV. From 26 January 1950 India would enter a life of contradictions: equality in politics but inequality in social and economic life.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four were in Ambedkar's speech of 25 November 1949: abandon unconstitutional methods, beware of hero-worship, turn political democracy into social democracy, and his warning that India was entering a life of contradictions between political equality and social and economic inequality.","difficulty":"very-hard","source":"UPSC Prelims · State PSCs","questionHi":"25 नवंबर 1949 को संविधान सभा में अपने अंतिम भाषण में अंबेडकर ने कई चेतावनियाँ दीं। इनमें से कितनी उनमें थीं? I. जहाँ संवैधानिक तरीके खुले हों, वहाँ सविनय अवज्ञा, असहयोग और सत्याग्रह सहित रक्तरंजित क्रांति के तरीके छोड़ दें। II. अपनी स्वतंत्रताएँ किसी महान व्यक्ति के चरणों में भी न रखें (राजनीति में व्यक्ति-पूजा से सावधान रहें)। III. राजनीतिक लोकतंत्र को सामाजिक लोकतंत्र भी बनाएँ। IV. 26 जनवरी 1950 से भारत विरोधाभासों के जीवन में प्रवेश करेगा: राजनीति में समानता पर सामाजिक और आर्थिक जीवन में असमानता।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों 25 नवंबर 1949 के अंबेडकर के भाषण में थीं: असंवैधानिक तरीके छोड़ना, व्यक्ति-पूजा से सावधान रहना, राजनीतिक लोकतंत्र को सामाजिक लोकतंत्र में बदलना, और यह चेतावनी कि भारत राजनीतिक समानता तथा सामाजिक और आर्थिक असमानता के विरोधाभासों के जीवन में प्रवेश कर रहा है।"},
  {"id":"polity-preamble-103","question":"Match the description of the Preamble with its author: A. \"Expresses what we had thought or dreamt so long\" B. \"Resembles the Declaration of Independence of the USA, but is more than a declaration\" C. \"Identity card of the Constitution\" D. \"Political horoscope\". 1. M. Hidayatullah 2. K. M. Munshi 3. Alladi Krishnaswamy Iyer 4. N. A. Palkhivala","options":["A-1, B-3, C-4, D-2","A-3, B-1, C-2, D-4","A-4, B-1, C-3, D-2","A-3, B-1, C-4, D-2"],"answer":3,"explanation":"Alladi Krishnaswamy Iyer: what we had thought or dreamt; Hidayatullah: more than a declaration; Palkhivala: identity card; Munshi: political horoscope (horoscope of our sovereign democratic republic).","difficulty":"very-hard","source":"UPSC Prelims · State PSCs","questionHi":"उद्देशिका के वर्णन को उसके लेखक से सुमेलित कीजिए: A. “वह व्यक्त करती है जो हम इतने समय से सोचते या सपने देखते आए थे” B. “अमेरिका की स्वतंत्रता की घोषणा से मिलती-जुलती है, परंतु घोषणा से अधिक है” C. “संविधान का पहचान पत्र” D. “राजनीतिक जन्मकुंडली”। 1. एम. हिदायतुल्ला 2. के. एम. मुंशी 3. अल्लादि कृष्णास्वामी अय्यर 4. एन. ए. पालखीवाला","optionsHi":["A-1, B-3, C-4, D-2","A-3, B-1, C-2, D-4","A-4, B-1, C-3, D-2","A-3, B-1, C-4, D-2"],"explanationHi":"अल्लादि कृष्णास्वामी अय्यर: जो हम सोचते या सपने देखते आए; हिदायतुल्ला: घोषणा से अधिक; पालखीवाला: पहचान पत्र; मुंशी: राजनीतिक जन्मकुंडली (हमारे संप्रभु लोकतंत्रात्मक गणराज्य की जन्मकुंडली)।"},
  {"id":"polity-preamble-104","question":"Arrange in chronological order: 1. S. R. Bommai judgment declaring secularism a basic feature 2. 16th Amendment adding \"sovereignty and integrity\" to Article 19 3. Insertion of Section 29A into the Representation of the People Act 4. 42nd Amendment adding \"Socialist Secular\" to the Preamble","options":["2, 4, 3, 1","4, 2, 3, 1","2, 3, 4, 1","2, 4, 1, 3"],"answer":0,"explanation":"16th Amendment 1963 → 42nd Amendment 1976 → Section 29A of the RPA 1989 → S. R. Bommai 1994. So the order is 2, 4, 3, 1.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"कालक्रम के अनुसार व्यवस्थित कीजिए: 1. पंथनिरपेक्षता को मूल विशेषता घोषित करने वाला एस. आर. बोम्मई निर्णय 2. अनुच्छेद 19 में “संप्रभुता और अखंडता” जोड़ने वाला 16वाँ संशोधन 3. जनप्रतिनिधित्व अधिनियम में धारा 29A का समावेश 4. उद्देशिका में “समाजवादी पंथनिरपेक्ष” जोड़ने वाला 42वाँ संशोधन","optionsHi":["2, 4, 3, 1","4, 2, 3, 1","2, 3, 4, 1","2, 4, 1, 3"],"explanationHi":"16वाँ संशोधन 1963 → 42वाँ संशोधन 1976 → जनप्रतिनिधित्व अधिनियम की धारा 29A 1989 → एस. आर. बोम्मई 1994। अतः क्रम 2, 4, 3, 1 है।"},
  {"id":"polity-preamble-105","question":"Assertion (A): Being \"Sovereign\", India can acquire foreign territory as well as cede its own territory to a foreign state. Reason (R): Article 1(3)(c) provides that the territory of India includes such other territories as may be acquired.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":1,"explanation":"Both are true. But R only covers acquiring territory. The power to cede territory comes from India's sovereignty, and after Berubari (1960) it is exercised by a constitutional amendment under Article 368, as with the 9th (1960) and 100th (2015) Amendments. So R explains only half of A.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"अभिकथन (A): “संप्रभु” होने के कारण भारत विदेशी क्षेत्र प्राप्त कर सकता है और अपना क्षेत्र किसी विदेशी राज्य को सौंप भी सकता है। कारण (R): अनुच्छेद 1(3)(c) उपबंध करता है कि भारत के राज्यक्षेत्र में ऐसे अन्य राज्यक्षेत्र शामिल हैं जो अर्जित किए जाएँ।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A सत्य है परंतु R असत्य है","A असत्य है परंतु R सत्य है"],"explanationHi":"दोनों सत्य हैं। परंतु R केवल क्षेत्र प्राप्त करने को समेटता है। क्षेत्र सौंपने की शक्ति भारत की संप्रभुता से आती है, और बेरुबारी (1960) के बाद इसका प्रयोग अनुच्छेद 368 के अंतर्गत संविधान संशोधन द्वारा होता है, जैसे 9वें (1960) और 100वें (2015) संशोधन में। अतः R, A की केवल आधी व्याख्या करता है।"},
  {"id":"polity-preamble-106","question":"How many of these statements about the Objectives Resolution are correct? I. It promised equality of status, of opportunity and before the law. II. It proposed that the autonomous units keep residuary powers. III. It did not contain the word \"Fraternity\". IV. It described India as an \"Independent Sovereign Republic\".","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. The Objectives Resolution promised equality of status, of opportunity and before the law, left residuary powers with the autonomous units, did not mention fraternity (added later by the Drafting Committee) and called India an \"Independent Sovereign Republic\".","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"उद्देश्य प्रस्ताव के बारे में इनमें से कितने कथन सही हैं? I. इसमें प्रतिष्ठा, अवसर और विधि के समक्ष समता का वचन था। II. इसमें प्रस्ताव था कि स्वायत्त इकाइयाँ अवशिष्ट शक्तियाँ रखें। III. इसमें “बंधुता” शब्द नहीं था। IV. इसने भारत को “स्वतंत्र संप्रभु गणराज्य” बताया।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं। उद्देश्य प्रस्ताव ने प्रतिष्ठा, अवसर और विधि के समक्ष समता का वचन दिया, अवशिष्ट शक्तियाँ स्वायत्त इकाइयों के पास रखीं, बंधुता का उल्लेख नहीं किया (प्रारूप समिति ने बाद में जोड़ा) और भारत को “स्वतंत्र संप्रभु गणराज्य” कहा।"},
  {"id":"polity-preamble-107","question":"How many of these statements about Dr. Balram Singh v. Union of India (November 2024) are correct? I. It was decided by a bench headed by Chief Justice Sanjiv Khanna. II. It rejected the argument that the Preamble's date of adoption, 26 November 1949, barred the 1976 insertions. III. It noted that the petitions came decades after the words had become widely accepted. IV. It said that \"socialist\" does not stop elected governments from pursuing economic policies that include private enterprise.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. The bench of Chief Justice Sanjiv Khanna and Justice Sanjay Kumar dismissed the petitions on 25 November 2024. It held that Article 368 extends to the Preamble and that the date of adoption does not limit it, and it read \"socialist\" as a welfare-state commitment, not a bar on private enterprise.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"डॉ. बलराम सिंह बनाम भारत संघ (नवंबर 2024) के बारे में इनमें से कितने कथन सही हैं? I. इसका निर्णय मुख्य न्यायाधीश संजीव खन्ना की अध्यक्षता वाली पीठ ने किया। II. इसने इस तर्क को अस्वीकार किया कि उद्देशिका की अंगीकरण तिथि, 26 नवंबर 1949, 1976 के समावेशनों को रोकती है। III. इसने नोट किया कि याचिकाएँ इन शब्दों के व्यापक रूप से स्वीकृत हो जाने के दशकों बाद आईं। IV. इसने कहा कि “समाजवादी” निर्वाचित सरकारों को निजी उद्यम वाली आर्थिक नीतियाँ अपनाने से नहीं रोकता।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं। मुख्य न्यायाधीश संजीव खन्ना और न्यायमूर्ति संजय कुमार की पीठ ने 25 नवंबर 2024 को याचिकाएँ खारिज कीं। इसने माना कि अनुच्छेद 368 उद्देशिका तक विस्तृत है और अंगीकरण की तिथि इसे सीमित नहीं करती, तथा “समाजवादी” को कल्याणकारी राज्य की प्रतिबद्धता माना, निजी उद्यम पर रोक नहीं।"},
  {"id":"polity-preamble-108","question":"How many of these statements are correct? I. The 16th Amendment (1963) added \"sovereignty and integrity of India\" as a ground for restrictions under Article 19. II. The same Amendment required legislators and candidates to swear to uphold the sovereignty and integrity of India. III. \"Integrity\" was added to the Preamble in 1976. IV. The 16th Amendment was passed after the India–Pakistan war of 1965.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. IV is wrong in its dates: the 16th Amendment was passed in 1963, after the 1962 war with China and on the advice of the Committee on National Integration and Regionalism, two years before the 1965 war.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"इनमें से कितने कथन सही हैं? I. 16वें संशोधन (1963) ने “भारत की संप्रभुता और अखंडता” को अनुच्छेद 19 के अंतर्गत निर्बंधनों का आधार बनाया। II. उसी संशोधन ने विधायकों और अभ्यर्थियों के लिए भारत की संप्रभुता और अखंडता को बनाए रखने की शपथ आवश्यक की। III. “अखंडता” उद्देशिका में 1976 में जोड़ी गई। IV. 16वाँ संशोधन 1965 के भारत–पाकिस्तान युद्ध के बाद पारित हुआ।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। IV तिथियों में गलत है: 16वाँ संशोधन 1963 में, चीन के साथ 1962 के युद्ध के बाद और राष्ट्रीय एकता एवं क्षेत्रवाद समिति की सलाह पर, 1965 के युद्ध से दो वर्ष पहले पारित हुआ।"},
  {"id":"polity-preamble-109","question":"Which of these phrases does NOT occur in the Preamble?","options":["Equality of status and of opportunity","Equality before the law","Liberty of thought, expression, belief, faith and worship","Assuring the dignity of the individual"],"answer":1,"explanation":"\"Equality before the law\" comes from Article 14 and from the Objectives Resolution, not from the Preamble. The Preamble speaks only of equality of status and of opportunity.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"इनमें से कौन-सा वाक्यांश उद्देशिका में नहीं आता?","optionsHi":["प्रतिष्ठा और अवसर की समता","विधि के समक्ष समता","विचार, अभिव्यक्ति, विश्वास, धर्म और उपासना की स्वतंत्रता","व्यक्ति की गरिमा सुनिश्चित करने वाली"],"explanationHi":"“विधि के समक्ष समता” अनुच्छेद 14 और उद्देश्य प्रस्ताव में है, उद्देशिका में नहीं। उद्देशिका केवल प्रतिष्ठा और अवसर की समता की बात करती है।"},
  {"id":"polity-preamble-110","question":"Arrange these judgments in chronological order: 1. LIC of India v. Consumer Education and Research Centre 2. Sajjan Singh v. State of Rajasthan 3. Dr. Balram Singh v. Union of India 4. Kesavananda Bharati v. State of Kerala","options":["2, 4, 1, 3","2, 4, 3, 1","4, 2, 1, 3","2, 1, 4, 3"],"answer":0,"explanation":"Sajjan Singh 1965 → Kesavananda Bharati 1973 → LIC of India 1995 (which again called the Preamble an integral part of the Constitution) → Balram Singh 2024. So the order is 2, 4, 1, 3.","difficulty":"very-hard","source":"UPSC Prelims · State PSCs","questionHi":"इन निर्णयों को कालक्रम में व्यवस्थित कीजिए: 1. LIC ऑफ इंडिया बनाम कंज्यूमर एजुकेशन एंड रिसर्च सेंटर 2. सज्जन सिंह बनाम राजस्थान राज्य 3. डॉ. बलराम सिंह बनाम भारत संघ 4. केशवानंद भारती बनाम केरल राज्य","optionsHi":["2, 4, 1, 3","2, 4, 3, 1","4, 2, 1, 3","2, 1, 4, 3"],"explanationHi":"सज्जन सिंह 1965 → केशवानंद भारती 1973 → LIC ऑफ इंडिया 1995 (जिसने उद्देशिका को पुनः संविधान का अभिन्न अंग कहा) → बलराम सिंह 2024। अतः क्रम 2, 4, 1, 3 है।"},
  {"id":"polity-preamble-111","question":"How many of these words occur in the text of the Preamble? Nation, Citizens, State, Union","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"Only two. \"Citizens\" occurs (\"to secure to all its citizens\") and so does \"Nation\" (\"unity and integrity of the Nation\"). The Preamble never uses \"State\" or \"Union\"; India is called a \"Republic\".","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"इनमें से कितने शब्द उद्देशिका के पाठ में आते हैं? राष्ट्र, नागरिक, राज्य, संघ","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल दो। “नागरिकों” आता है (“इसके समस्त नागरिकों को”) और “राष्ट्र” भी (“राष्ट्र की एकता और अखंडता”)। उद्देशिका में “राज्य” या “संघ” कभी प्रयुक्त नहीं होता; भारत को “गणराज्य” कहा गया है।"},
  {"id":"polity-preamble-112","question":"Which pair of a Preamble ideal and a provision of the ORIGINAL Constitution (1950) that already reflected it is NOT correct?","options":["Republic – Article 54, indirect election of the President","Fraternity – Article 51A(e), duty to promote common brotherhood","Political justice – Article 326, universal adult suffrage","Liberty of worship – Article 25, freedom of conscience and religion"],"answer":1,"explanation":"Article 51A, with its duty to promote harmony and the spirit of common brotherhood, was inserted only by the 42nd Amendment in 1976. So it was not part of the original Constitution. The other three provisions were there in 1950.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"उद्देशिका के आदर्श और मूल संविधान (1950) के उस प्रावधान का कौन-सा युग्म, जो उसे पहले से प्रतिबिंबित करता था, सही नहीं है?","optionsHi":["गणराज्य – अनुच्छेद 54, राष्ट्रपति का अप्रत्यक्ष निर्वाचन","बंधुता – अनुच्छेद 51A(e), सौहार्द और भ्रातृत्व को बढ़ावा देने का कर्तव्य","राजनीतिक न्याय – अनुच्छेद 326, सार्वभौमिक वयस्क मताधिकार","उपासना की स्वतंत्रता – अनुच्छेद 25, अंतःकरण और धर्म की स्वतंत्रता"],"explanationHi":"अनुच्छेद 51A, जिसमें सौहार्द और समान भ्रातृत्व की भावना को बढ़ावा देने का कर्तव्य है, 1976 में 42वें संशोधन द्वारा ही जोड़ा गया था। अतः यह मूल संविधान का भाग नहीं था। शेष तीन प्रावधान 1950 में मौजूद थे।"},
  {"id":"polity-preamble-113","question":"Who presided over the first meeting of the Constituent Assembly on 9 December 1946 as its temporary President?","options":["Sachchidananda Sinha","Dr Rajendra Prasad","Sir Benegal Narsing Rau","H. C. Mukherjee"],"answer":0,"explanation":"Dr Sachchidananda Sinha, the oldest member, was made temporary President following the French practice. Rajendra Prasad was elected permanent President on 11 December 1946, and H. C. Mukherjee became Vice-President.","difficulty":"easy","source":"SSC CGL · SSC CHSL · State PSCs","questionHi":"9 दिसंबर 1946 को संविधान सभा की पहली बैठक की अस्थायी अध्यक्षता किसने की?","optionsHi":["सच्चिदानंद सिन्हा","डॉ. राजेंद्र प्रसाद","सर बेनेगल नरसिंह राव","एच. सी. मुखर्जी"],"explanationHi":"सबसे वरिष्ठ सदस्य डॉ. सच्चिदानंद सिन्हा को फ्रांसीसी परंपरा के अनुसार अस्थायी अध्यक्ष बनाया गया। राजेंद्र प्रसाद 11 दिसंबर 1946 को स्थायी अध्यक्ष चुने गए और एच. सी. मुखर्जी उपाध्यक्ष बने।"},
  {"id":"polity-preamble-114","question":"Since 2015, 26 November, the day the Constitution and its Preamble were adopted, has been officially observed as:","options":["Republic Day (Gantantra Diwas)","National Unity Day (Rashtriya Ekta Diwas)","National Law Day (Vidhi Diwas)","Constitution Day (Samvidhan Divas)"],"answer":3,"explanation":"The Government notified 26 November as Constitution Day in 2015, the 125th birth anniversary year of Ambedkar; it was earlier marked as Law Day. National Unity Day is 31 October and Republic Day is 26 January.","difficulty":"easy","source":"SSC CGL · RRB NTPC","questionHi":"2015 से 26 नवंबर, जिस दिन संविधान और उसकी उद्देशिका अंगीकृत हुई, को आधिकारिक रूप से किस रूप में मनाया जाता है?","optionsHi":["गणतंत्र दिवस","राष्ट्रीय एकता दिवस","राष्ट्रीय विधि दिवस","संविधान दिवस"],"explanationHi":"सरकार ने 2015 में, अंबेडकर की 125वीं जयंती के वर्ष में, 26 नवंबर को संविधान दिवस अधिसूचित किया; पहले इसे विधि दिवस के रूप में मनाया जाता था। राष्ट्रीय एकता दिवस 31 अक्टूबर और गणतंत्र दिवस 26 जनवरी को है।"},
  {"id":"polity-preamble-115","question":"Who served as the Constitutional Adviser to the Constituent Assembly and prepared its first draft?","options":["K. M. Munshi","Alladi Krishnaswamy Ayyar","B. N. Rau","S. N. Mukherjee"],"answer":2,"explanation":"Sir B. N. Rau was the Constitutional Adviser and prepared the initial draft in October 1947. S. N. Mukherjee was the chief draftsman; Munshi and Alladi were members of the Drafting Committee.","difficulty":"easy","source":"SSC CGL · State PSCs","questionHi":"संविधान सभा के संवैधानिक सलाहकार कौन थे, जिन्होंने उसका पहला प्रारूप तैयार किया?","optionsHi":["के. एम. मुंशी","अल्लादि कृष्णास्वामी अय्यर","बी. एन. राव","एस. एन. मुखर्जी"],"explanationHi":"सर बी. एन. राव संवैधानिक सलाहकार थे और उन्होंने अक्टूबर 1947 में आरंभिक प्रारूप तैयार किया। एस. एन. मुखर्जी मुख्य प्रारूपकार थे; मुंशी और अल्लादि प्रारूप समिति के सदस्य थे।"},
  {"id":"polity-preamble-116","question":"The Constituent Assembly that framed the Constitution and its Preamble was set up under the scheme of the:","options":["Cripps Mission, 1942","August Offer, 1940","Mountbatten Plan, 3 June 1947","Cabinet Mission Plan, 1946"],"answer":3,"explanation":"The Assembly was constituted in November 1946 under the Cabinet Mission Plan of May 1946. The Cripps proposals of 1942 had offered an elected body only after the war and were rejected.","difficulty":"moderate","source":"SSC CGL · State PSCs","questionHi":"संविधान और उसकी उद्देशिका बनाने वाली संविधान सभा का गठन किस योजना के अंतर्गत हुआ?","optionsHi":["क्रिप्स मिशन, 1942","अगस्त प्रस्ताव, 1940","माउंटबेटन योजना, 3 जून 1947","कैबिनेट मिशन योजना, 1946"],"explanationHi":"सभा का गठन नवंबर 1946 में मई 1946 की कैबिनेट मिशन योजना के अंतर्गत हुआ। 1942 के क्रिप्स प्रस्तावों में निर्वाचित निकाय केवल युद्ध के बाद देने की बात थी और उन्हें अस्वीकार कर दिया गया।"},
  {"id":"polity-preamble-117","question":"Under the Cabinet Mission scheme, the representatives of the princely states in the Constituent Assembly were to be:","options":["Elected by the provincial legislative assemblies","Nominated by the heads of the princely states","Directly elected by the people of the states","Nominated by the Viceroy"],"answer":1,"explanation":"The 93 princely-state seats were to be filled by nominees of the rulers. Only the 296 British-India seats were filled by indirect election through the provincial assemblies.","difficulty":"moderate","source":"UPSC Prelims · State PSCs","questionHi":"कैबिनेट मिशन योजना के अंतर्गत संविधान सभा में देशी रियासतों के प्रतिनिधि किस प्रकार आने थे?","optionsHi":["प्रांतीय विधानसभाओं द्वारा निर्वाचित","रियासतों के शासकों द्वारा नामित","रियासतों की जनता द्वारा प्रत्यक्ष रूप से निर्वाचित","वायसराय द्वारा नामित"],"explanationHi":"देशी रियासतों की 93 सीटें शासकों के नामितों से भरी जानी थीं। केवल ब्रिटिश भारत की 296 सीटें प्रांतीय विधानसभाओं के माध्यम से अप्रत्यक्ष निर्वाचन से भरी गईं।"},
  {"id":"polity-preamble-118","question":"What was the total strength of the Constituent Assembly as envisaged by the Cabinet Mission Plan?","options":["299","296","395","389"],"answer":3,"explanation":"The plan provided 389 seats: 296 for British India (292 from provinces and 4 from Chief Commissioners' provinces) and 93 for princely states. After Partition the strength fell to 299.","difficulty":"moderate","source":"SSC CGL · State PSCs","questionHi":"कैबिनेट मिशन योजना में परिकल्पित संविधान सभा की कुल संख्या कितनी थी?","optionsHi":["299","296","395","389"],"explanationHi":"योजना में 389 सीटें थीं: ब्रिटिश भारत की 296 (प्रांतों से 292 और मुख्य आयुक्त प्रांतों से 4) और रियासतों की 93। विभाजन के बाद संख्या घटकर 299 रह गई।"},
  {"id":"polity-preamble-119","question":"The Constituent Assembly adopted the National Flag on:","options":["22 July 1947","15 August 1947","26 November 1949","24 January 1950"],"answer":0,"explanation":"The tricolour was adopted on 22 July 1947. The National Anthem and the National Song were adopted on 24 January 1950, the Assembly's last day.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"संविधान सभा ने राष्ट्रीय ध्वज को किस तिथि को अंगीकृत किया?","optionsHi":["22 जुलाई 1947","15 अगस्त 1947","26 नवंबर 1949","24 जनवरी 1950"],"explanationHi":"तिरंगा 22 जुलाई 1947 को अंगीकृत हुआ। राष्ट्रगान और राष्ट्रगीत 24 जनवरी 1950, सभा के अंतिम दिन, अंगीकृत हुए।"},
  {"id":"polity-preamble-120","question":"Who among the following was NOT a member of the Drafting Committee of the Constituent Assembly?","options":["Jawaharlal Nehru","K. M. Munshi","Syed Mohammad Saadullah","N. Gopalaswamy Ayyangar"],"answer":0,"explanation":"The Drafting Committee (29 August 1947) under Ambedkar included Gopalaswamy Ayyangar, Alladi Krishnaswamy Ayyar, K. M. Munshi, Saadullah, N. Madhava Rau and T. T. Krishnamachari. Nehru chaired other committees, such as the Union Powers Committee.","difficulty":"moderate","source":"SSC CGL · State PSCs","questionHi":"इनमें से कौन संविधान सभा की प्रारूप समिति का सदस्य नहीं था?","optionsHi":["जवाहरलाल नेहरू","के. एम. मुंशी","सैयद मोहम्मद सादुल्ला","एन. गोपालस्वामी अय्यंगार"],"explanationHi":"अंबेडकर की अध्यक्षता वाली प्रारूप समिति (29 अगस्त 1947) में गोपालस्वामी अय्यंगार, अल्लादि कृष्णास्वामी अय्यर, के. एम. मुंशी, सादुल्ला, एन. माधव राव और टी. टी. कृष्णमाचारी शामिल थे। नेहरू ने संघ शक्ति समिति जैसी अन्य समितियों की अध्यक्षता की।"},
  {"id":"polity-preamble-121","question":"Which animal was adopted as the symbol (seal) of the Constituent Assembly?","options":["Lion","Bull","Elephant","Horse"],"answer":2,"explanation":"The elephant was the symbol on the Constituent Assembly's seal. The lion capital of Sarnath was adopted later as the State Emblem.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"संविधान सभा के प्रतीक (मुहर) के रूप में कौन-सा पशु अपनाया गया?","optionsHi":["सिंह","बैल","हाथी","घोड़ा"],"explanationHi":"संविधान सभा की मुहर का प्रतीक हाथी था। सारनाथ का सिंह स्तंभ शीर्ष बाद में राज्य चिह्न के रूप में अपनाया गया।"},
  {"id":"polity-preamble-122","question":"The idea of a Constituent Assembly for India was first put forward in 1934 by:","options":["Jawaharlal Nehru","Mahatma Gandhi","C. Rajagopalachari","M. N. Roy"],"answer":3,"explanation":"M. N. Roy proposed it in 1934. The Congress officially demanded a Constituent Assembly in 1935, and the British accepted the demand in principle in the August Offer of 1940.","difficulty":"moderate","source":"UPSC Prelims · State PSCs","questionHi":"भारत के लिए संविधान सभा का विचार सबसे पहले 1934 में किसने रखा?","optionsHi":["जवाहरलाल नेहरू","महात्मा गांधी","सी. राजगोपालाचारी","एम. एन. रॉय"],"explanationHi":"एम. एन. रॉय ने 1934 में इसका प्रस्ताव रखा। कांग्रेस ने 1935 में आधिकारिक रूप से संविधान सभा की माँग की, और अंग्रेजों ने 1940 के अगस्त प्रस्ताव में इस माँग को सिद्धांत रूप में स्वीकार किया।"},
  {"id":"polity-preamble-123","question":"Match the feature of the Constitution with the country it was borrowed from: A. Concurrent List B. Suspension of Fundamental Rights during an emergency C. Procedure established by law D. Residuary powers with the Centre — 1. Weimar Germany 2. Australia 3. Canada 4. Japan","options":["A-2, B-1, C-4, D-3","A-1, B-2, C-4, D-3","A-2, B-1, C-3, D-4","A-3, B-1, C-4, D-2"],"answer":0,"explanation":"The Concurrent List came from Australia, suspension of rights in emergency from the Weimar Constitution, ‘procedure established by law’ from Japan, and a strong Centre with residuary powers from Canada.","difficulty":"hard","source":"UPSC Prelims · State PSCs","questionHi":"संविधान की विशेषता को उस देश से सुमेलित कीजिए जहाँ से वह ली गई: A. समवर्ती सूची B. आपातकाल के दौरान मौलिक अधिकारों का निलंबन C. विधि द्वारा स्थापित प्रक्रिया D. अवशिष्ट शक्तियाँ केंद्र के पास — 1. वाइमर जर्मनी 2. ऑस्ट्रेलिया 3. कनाडा 4. जापान","optionsHi":["A-2, B-1, C-4, D-3","A-1, B-2, C-4, D-3","A-2, B-1, C-3, D-4","A-3, B-1, C-4, D-2"],"explanationHi":"समवर्ती सूची ऑस्ट्रेलिया से, आपातकाल में अधिकारों का निलंबन वाइमर संविधान से, “विधि द्वारा स्थापित प्रक्रिया” जापान से, और अवशिष्ट शक्तियों वाला सशक्त केंद्र कनाडा से आया।"},
  {"id":"polity-preamble-124","question":"Under Article 394, which of these provisions came into force on 26 November 1949 itself, before the rest of the Constitution?","options":["Citizenship (Articles 5 to 9)","Fundamental Rights (Part III)","Directive Principles (Part IV)","Emergency provisions (Part XVIII)"],"answer":0,"explanation":"Article 394 brought citizenship, elections (Article 324), provisional Parliament, interpretation and some transitional provisions into force on 26 November 1949. Parts III, IV and XVIII began on 26 January 1950.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अनुच्छेद 394 के अंतर्गत इनमें से कौन-से प्रावधान शेष संविधान से पहले, 26 नवंबर 1949 को ही लागू हो गए?","optionsHi":["नागरिकता (अनुच्छेद 5 से 9)","मौलिक अधिकार (भाग III)","निदेशक तत्व (भाग IV)","आपात उपबंध (भाग XVIII)"],"explanationHi":"अनुच्छेद 394 ने नागरिकता, निर्वाचन (अनुच्छेद 324), अंतरिम संसद, निर्वचन और कुछ संक्रमणकालीन प्रावधानों को 26 नवंबर 1949 से लागू किया। भाग III, IV और XVIII 26 जनवरी 1950 से लागू हुए।"},
  {"id":"polity-preamble-125","question":"Consider the following statements: 1. After independence the Constituent Assembly also functioned as the first legislature (Dominion Parliament) of free India. 2. When it met as a legislative body, it was presided over by G. V. Mavalankar. Which of the above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"Both are correct. Under the Indian Independence Act, 1947 the Assembly had a dual role: Rajendra Prasad presided when it sat as a constitution-making body, Mavalankar when it sat as the legislature.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. स्वतंत्रता के बाद संविधान सभा ने स्वतंत्र भारत की पहली विधायिका (डोमिनियन संसद) के रूप में भी कार्य किया। 2. जब वह विधायी निकाय के रूप में बैठती थी, तब उसकी अध्यक्षता जी. वी. मावलंकर करते थे। उपर्युक्त में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"दोनों सही हैं। भारतीय स्वतंत्रता अधिनियम, 1947 के अंतर्गत सभा की दोहरी भूमिका थी: संविधान निर्मात्री निकाय के रूप में राजेंद्र प्रसाद और विधायिका के रूप में मावलंकर अध्यक्षता करते थे।"},
  {"id":"polity-preamble-126","question":"Consider the following statements: 1. The Muslim League boycotted the first meeting of the Constituent Assembly. 2. The Indian Independence Act, 1947 made the Constituent Assembly subordinate to the British Parliament in matters of constitution-making. Which of the above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":0,"explanation":"Statement 1 is correct. Statement 2 is wrong: the 1947 Act made the Assembly fully sovereign, free to frame any constitution and to repeal any British law relating to India.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. मुस्लिम लीग ने संविधान सभा की पहली बैठक का बहिष्कार किया। 2. भारतीय स्वतंत्रता अधिनियम, 1947 ने संविधान निर्माण के मामलों में संविधान सभा को ब्रिटिश संसद के अधीन बना दिया। उपर्युक्त में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"कथन 1 सही है। कथन 2 गलत है: 1947 के अधिनियम ने सभा को पूर्णतः संप्रभु बना दिया, जो कोई भी संविधान बनाने और भारत से संबंधित किसी भी ब्रिटिश कानून को निरस्त करने के लिए स्वतंत्र थी।"},
  {"id":"polity-preamble-127","question":"Which of these committees of the Constituent Assembly was chaired by Sardar Vallabhbhai Patel?","options":["Union Powers Committee","Committee on the Rules of Procedure","Provincial Constitution Committee","Union Constitution Committee"],"answer":2,"explanation":"Patel chaired the Provincial Constitution Committee and the Advisory Committee on Fundamental Rights and Minorities. Nehru chaired the Union Powers and Union Constitution Committees, while Rajendra Prasad chaired the Committee on Rules of Procedure.","difficulty":"hard","source":"UPSC Prelims · State PSCs","questionHi":"संविधान सभा की इनमें से कौन-सी समिति की अध्यक्षता सरदार वल्लभभाई पटेल ने की?","optionsHi":["संघ शक्ति समिति","प्रक्रिया नियम समिति","प्रांतीय संविधान समिति","संघ संविधान समिति"],"explanationHi":"पटेल ने प्रांतीय संविधान समिति और मौलिक अधिकारों एवं अल्पसंख्यकों पर सलाहकार समिति की अध्यक्षता की। नेहरू ने संघ शक्ति और संघ संविधान समितियों की, जबकि राजेंद्र प्रसाद ने प्रक्रिया नियम समिति की अध्यक्षता की।"},
  {"id":"polity-preamble-128","question":"As originally adopted in 1949, the Constitution of India contained:","options":["395 Articles, 22 Parts and 12 Schedules","448 Articles, 25 Parts and 12 Schedules","397 Articles, 24 Parts and 8 Schedules","395 Articles, 22 Parts and 8 Schedules"],"answer":3,"explanation":"The original text had a Preamble, 395 Articles in 22 Parts and 8 Schedules. The Schedules have since grown to 12, and Articles are still numbered up to 395 despite many insertions.","difficulty":"hard","source":"SSC CGL · State PSCs","questionHi":"1949 में अंगीकृत मूल रूप में भारत के संविधान में क्या था?","optionsHi":["395 अनुच्छेद, 22 भाग और 12 अनुसूचियाँ","448 अनुच्छेद, 25 भाग और 12 अनुसूचियाँ","397 अनुच्छेद, 24 भाग और 8 अनुसूचियाँ","395 अनुच्छेद, 22 भाग और 8 अनुसूचियाँ"],"explanationHi":"मूल पाठ में एक उद्देशिका, 22 भागों में 395 अनुच्छेद और 8 अनुसूचियाँ थीं। अनुसूचियाँ अब बढ़कर 12 हो गई हैं, और अनेक समावेशनों के बावजूद अनुच्छेद अब भी 395 तक ही क्रमांकित हैं।"},
  {"id":"polity-preamble-129","question":"The original English text of the Constitution, including the Preamble, was handwritten in calligraphy by:","options":["Nandalal Bose of Santiniketan","Prem Behari Narain Raizada","Beohar Rammanohar Sinha","Abanindranath Tagore"],"answer":1,"explanation":"Prem Behari Narain Raizada wrote the English text by hand. Nandalal Bose and his Santiniketan students, including Beohar Rammanohar Sinha who decorated the Preamble page, did the illustrations.","difficulty":"hard","source":"SSC CGL · State PSCs","questionHi":"उद्देशिका सहित संविधान का मूल अंग्रेजी पाठ सुलेख में हाथ से किसने लिखा?","optionsHi":["शांतिनिकेतन के नंदलाल बोस","प्रेम बिहारी नारायण रायज़ादा","बेओहर राममनोहर सिन्हा","अबनींद्रनाथ टैगोर"],"explanationHi":"प्रेम बिहारी नारायण रायज़ादा ने अंग्रेजी पाठ हाथ से लिखा। नंदलाल बोस और शांतिनिकेतन के उनके छात्रों, जिनमें उद्देशिका पृष्ठ सजाने वाले बेओहर राममनोहर सिन्हा भी थे, ने चित्र बनाए।"},
  {"id":"polity-preamble-130","question":"In the Preamble the people resolve to “secure” three ideals to all citizens and to “promote” one ideal among them all. Which ideal is to be promoted?","options":["Justice","Liberty","Equality","Fraternity"],"answer":3,"explanation":"The text resolves “to secure to all its citizens” Justice, Liberty and Equality, “and to promote among them all” Fraternity, assuring the dignity of the individual and the unity and integrity of the Nation.","difficulty":"hard","source":"UPSC Prelims","questionHi":"उद्देशिका में लोग सभी नागरिकों को तीन आदर्श “सुनिश्चित” करने और सबमें एक आदर्श “बढ़ाने” का संकल्प लेते हैं। कौन-सा आदर्श बढ़ाया जाना है?","optionsHi":["न्याय","स्वतंत्रता","समता","बंधुता"],"explanationHi":"पाठ में “इसके समस्त नागरिकों को” न्याय, स्वतंत्रता और समता “सुनिश्चित” करने तथा “उन सबमें” बंधुता “बढ़ाने” का संकल्प है, जो व्यक्ति की गरिमा और राष्ट्र की एकता और अखंडता सुनिश्चित करे।"},
  {"id":"polity-preamble-131","question":"Which of these features of the Indian Constitution was borrowed from the Constitution of Ireland?","options":["Concurrent List of legislative subjects","Nominating members to the Rajya Sabha","Fundamental Duties of every citizen","Judicial review of laws by the courts"],"answer":1,"explanation":"Ireland gave the Directive Principles, the nomination of members to the Rajya Sabha and the method of electing the President. The Concurrent List is Australian, Fundamental Duties Soviet and judicial review American.","difficulty":"hard","source":"SSC CGL · State PSCs","questionHi":"भारतीय संविधान की इनमें से कौन-सी विशेषता आयरलैंड के संविधान से ली गई?","optionsHi":["विधायी विषयों की समवर्ती सूची","राज्यसभा में सदस्यों का मनोनयन","प्रत्येक नागरिक के मौलिक कर्तव्य","न्यायालयों द्वारा कानूनों की न्यायिक समीक्षा"],"explanationHi":"आयरलैंड ने नीति निदेशक तत्व, राज्यसभा में सदस्यों का मनोनयन और राष्ट्रपति के निर्वाचन की पद्धति दी। समवर्ती सूची ऑस्ट्रेलियाई है, मौलिक कर्तव्य सोवियत और न्यायिक समीक्षा अमेरिकी।"},
  {"id":"polity-preamble-132","question":"Consider the following statements: 1. The idea of Fundamental Duties was taken from the Constitution of the former USSR. 2. The procedure for amending the Constitution was borrowed from Canada. Which of the above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":0,"explanation":"Only 1 is correct. The amendment procedure and the election of Rajya Sabha members came from South Africa; Canada gave the quasi-federal form and residuary powers with the Centre.","difficulty":"hard","source":"UPSC Prelims · State PSCs","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. मौलिक कर्तव्यों का विचार पूर्व सोवियत संघ (USSR) के संविधान से लिया गया। 2. संविधान संशोधन की प्रक्रिया कनाडा से ली गई। उपर्युक्त में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"केवल 1 सही है। संशोधन की प्रक्रिया और राज्यसभा सदस्यों का निर्वाचन दक्षिण अफ्रीका से आए; कनाडा ने अर्ध-संघीय स्वरूप और केंद्र के पास अवशिष्ट शक्तियाँ दीं।"},
  {"id":"polity-preamble-133","question":"Match the committee of the Constituent Assembly with its chairman: A. Union Constitution Committee B. Rules of Procedure Committee C. Fundamental Rights Sub-Committee D. Minorities Sub-Committee — 1. J. B. Kripalani 2. H. C. Mukherjee 3. Jawaharlal Nehru 4. Rajendra Prasad","options":["A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2","A-3, B-4, C-1, D-2","A-3, B-1, C-4, D-2"],"answer":2,"explanation":"Nehru chaired the Union Constitution Committee, Rajendra Prasad the Rules of Procedure Committee, Kripalani the Fundamental Rights Sub-Committee and H. C. Mukherjee the Minorities Sub-Committee (both sub-committees of Patel's Advisory Committee).","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"संविधान सभा की समिति को उसके अध्यक्ष से सुमेलित कीजिए: A. संघ संविधान समिति B. प्रक्रिया नियम समिति C. मौलिक अधिकार उप-समिति D. अल्पसंख्यक उप-समिति — 1. जे. बी. कृपलानी 2. एच. सी. मुखर्जी 3. जवाहरलाल नेहरू 4. राजेंद्र प्रसाद","optionsHi":["A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2","A-3, B-4, C-1, D-2","A-3, B-1, C-4, D-2"],"explanationHi":"नेहरू ने संघ संविधान समिति, राजेंद्र प्रसाद ने प्रक्रिया नियम समिति, कृपलानी ने मौलिक अधिकार उप-समिति और एच. सी. मुखर्जी ने अल्पसंख्यक उप-समिति की अध्यक्षता की (दोनों उप-समितियाँ पटेल की सलाहकार समिति की थीं)।"},
  {"id":"polity-preamble-134","question":"Arrange these events in chronological order: 1. Rajendra Prasad elected permanent President of the Constituent Assembly 2. Drafting Committee set up 3. National Flag adopted 4. Objectives Resolution adopted","options":["4, 1, 3, 2","1, 4, 3, 2","1, 4, 2, 3","1, 3, 4, 2"],"answer":1,"explanation":"Prasad was elected on 11 December 1946, the Objectives Resolution was adopted on 22 January 1947, the flag on 22 July 1947, and the Drafting Committee was set up on 29 August 1947.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"इन घटनाओं को कालक्रम में व्यवस्थित कीजिए: 1. राजेंद्र प्रसाद का संविधान सभा के स्थायी अध्यक्ष के रूप में निर्वाचन 2. प्रारूप समिति का गठन 3. राष्ट्रीय ध्वज का अंगीकरण 4. उद्देश्य प्रस्ताव का अंगीकरण","optionsHi":["4, 1, 3, 2","1, 4, 3, 2","1, 4, 2, 3","1, 3, 4, 2"],"explanationHi":"प्रसाद 11 दिसंबर 1946 को चुने गए, उद्देश्य प्रस्ताव 22 जनवरी 1947 को अंगीकृत हुआ, ध्वज 22 जुलाई 1947 को, और प्रारूप समिति 29 अगस्त 1947 को गठित हुई।"},
  {"id":"polity-preamble-135","question":"Match the description of Indian federalism with the scholar who gave it: A. “Quasi-federal” B. “Co-operative federalism” C. “Bargaining federalism” D. “A federation with a strong centralising tendency” — 1. Ivor Jennings 2. Morris-Jones 3. Granville Austin 4. K. C. Wheare","options":["A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1","A-4, B-3, C-2, D-1"],"answer":3,"explanation":"K. C. Wheare called the Constitution quasi-federal, Granville Austin spoke of co-operative federalism, Morris-Jones of bargaining federalism, and Ivor Jennings of a federation with a strong centralising tendency.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"भारतीय संघवाद के वर्णन को उसे देने वाले विद्वान से सुमेलित कीजिए: A. “अर्ध-संघीय” B. “सहकारी संघवाद” C. “सौदेबाजी वाला संघवाद” D. “प्रबल केंद्रीकरण प्रवृत्ति वाला संघ” — 1. आइवर जेनिंग्स 2. मॉरिस-जोन्स 3. ग्रेनविल ऑस्टिन 4. के. सी. व्हीयर","optionsHi":["A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1","A-4, B-3, C-2, D-1"],"explanationHi":"के. सी. व्हीयर ने संविधान को अर्ध-संघीय कहा, ग्रेनविल ऑस्टिन ने सहकारी संघवाद की बात की, मॉरिस-जोन्स ने सौदेबाजी वाले संघवाद की, और आइवर जेनिंग्स ने प्रबल केंद्रीकरण प्रवृत्ति वाले संघ की।"},
  {"id":"polity-preamble-136","question":"Ambedkar explained why Article 1 calls India a “Union of States” rather than a federation. Consider: 1. The Indian federation is not the result of an agreement among the States. 2. No State has the right to secede from it. Which of these were among his reasons?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"Both. Unlike the American federation, India's was not formed by an agreement of units, and the units cannot break away; the Union is indestructible though the States can be reorganised by Parliament.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अंबेडकर ने समझाया कि अनुच्छेद 1 भारत को संघ (फेडरेशन) के बजाय “राज्यों का संघ” क्यों कहता है। विचार कीजिए: 1. भारतीय संघ राज्यों के बीच किसी समझौते का परिणाम नहीं है। 2. किसी राज्य को इससे अलग होने का अधिकार नहीं है। इनमें से कौन-से उनके कारणों में थे?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"दोनों। अमेरिकी संघ के विपरीत, भारत का संघ इकाइयों के समझौते से नहीं बना और इकाइयाँ अलग नहीं हो सकतीं; संघ अविनाशी है, यद्यपि संसद राज्यों का पुनर्गठन कर सकती है।"},
  {"id":"polity-preamble-137","question":"Assertion (A): The Constituent Assembly could repeal Acts of the British Parliament relating to India. Reason (R): The Indian Independence Act, 1947 made the Constituent Assembly a fully sovereign body.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both are true and R explains A. Using that sovereignty, Article 395 of the Constitution repealed the Indian Independence Act, 1947 and the Government of India Act, 1935.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): संविधान सभा भारत से संबंधित ब्रिटिश संसद के अधिनियमों को निरस्त कर सकती थी। कारण (R): भारतीय स्वतंत्रता अधिनियम, 1947 ने संविधान सभा को पूर्णतः संप्रभु निकाय बना दिया।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A सत्य है परंतु R असत्य है","A असत्य है परंतु R सत्य है"],"explanationHi":"दोनों सत्य हैं और R, A की व्याख्या करता है। उसी संप्रभुता का उपयोग करते हुए संविधान के अनुच्छेद 395 ने भारतीय स्वतंत्रता अधिनियम, 1947 और भारत शासन अधिनियम, 1935 को निरस्त कर दिया।"},
  {"id":"polity-preamble-138","question":"The closing words of the Preamble record that the people of India, in their Constituent Assembly, “do hereby” do three things to the Constitution. In what order do these appear?","options":["Enact, adopt and give to ourselves","Adopt, enact and give to ourselves","Give to ourselves, adopt and enact","Adopt, give to ourselves and enact"],"answer":1,"explanation":"The text reads “do hereby adopt, enact and give to ourselves this Constitution”. The phrasing stresses that the Constitution flows from the people themselves.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"उद्देशिका के समापन शब्द दर्ज करते हैं कि भारत के लोग, अपनी संविधान सभा में, संविधान को लेकर “एतद्द्वारा” तीन काम करते हैं। ये किस क्रम में आते हैं?","optionsHi":["अधिनियमित, अंगीकृत और आत्मार्पित","अंगीकृत, अधिनियमित और आत्मार्पित","आत्मार्पित, अंगीकृत और अधिनियमित","अंगीकृत, आत्मार्पित और अधिनियमित"],"explanationHi":"पाठ है “एतद्द्वारा इस संविधान को अंगीकृत, अधिनियमित और आत्मार्पित करते हैं”। यह शब्दावली बल देती है कि संविधान स्वयं जनता से प्रवाहित होता है।"},
  {"id":"polity-preamble-139","question":"How many of these statements are correct? I. The Constituent Assembly took about 2 years, 11 months and 18 days to frame the Constitution. II. Members signed the Constitution on 24 January 1950, the Assembly's last day. III. On the same day the Assembly elected Rajendra Prasad as the first President of India. IV. All 299 members signed the Constitution.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. IV is wrong: 284 members signed the Constitution, not all 299.","difficulty":"very-hard","source":"UPSC Prelims · State PSCs","questionHi":"इनमें से कितने कथन सही हैं? I. संविधान सभा ने संविधान बनाने में लगभग 2 वर्ष, 11 महीने और 18 दिन लिए। II. सदस्यों ने सभा के अंतिम दिन, 24 जनवरी 1950, को संविधान पर हस्ताक्षर किए। III. उसी दिन सभा ने राजेंद्र प्रसाद को भारत का प्रथम राष्ट्रपति चुना। IV. सभी 299 सदस्यों ने संविधान पर हस्ताक्षर किए।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। IV गलत है: संविधान पर 284 सदस्यों ने हस्ताक्षर किए, सभी 299 ने नहीं।"},
  {"id":"polity-preamble-140","question":"Consider the following statements: 1. The 44th Amendment (1978) deleted the word “Socialist” from the Preamble. 2. The 42nd Amendment's change to the Preamble was enacted while the National Emergency of 1975 was in force. Which of the above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":1,"explanation":"Only 2 is correct: the 42nd Amendment received assent in December 1976, during the Emergency (June 1975 to March 1977). The 44th Amendment undid many 1976 changes but left the Preamble untouched.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. 44वें संशोधन (1978) ने उद्देशिका से “समाजवादी” शब्द हटा दिया। 2. उद्देशिका में 42वें संशोधन का परिवर्तन 1975 के राष्ट्रीय आपातकाल के लागू रहते हुए अधिनियमित हुआ। उपर्युक्त में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"केवल 2 सही है: 42वें संशोधन को अनुमति दिसंबर 1976 में, आपातकाल (जून 1975 से मार्च 1977) के दौरान मिली। 44वें संशोधन ने 1976 के कई परिवर्तन पलटे पर उद्देशिका को अछूता छोड़ा।"},
  {"id":"polity-preamble-141","question":"Assertion (A): Courts may refer to the Preamble to interpret an ambiguous provision of the Constitution. Reason (R): The Preamble is a source of legislative power.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":2,"explanation":"A is true: the Preamble is an aid to interpretation where the text is unclear. R is false: as held in the Berubari reference (1960), the Preamble neither grants power nor limits it.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): न्यायालय संविधान के किसी अस्पष्ट प्रावधान की व्याख्या के लिए उद्देशिका का सहारा ले सकते हैं। कारण (R): उद्देशिका विधायी शक्ति का स्रोत है।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A सत्य है परंतु R असत्य है","A असत्य है परंतु R सत्य है"],"explanationHi":"A सत्य है: पाठ अस्पष्ट होने पर उद्देशिका व्याख्या में सहायक है। R असत्य है: बेरुबारी संदर्भ (1960) में कहा गया कि उद्देशिका न शक्ति देती है और न उसे सीमित करती है।"},
  {"id":"polity-preamble-142","question":"Match the Article with its subject: A. Article 393 B. Article 394 C. Article 394A D. Article 395 — 1. Repeal of the Indian Independence Act, 1947 and the Government of India Act, 1935 2. Authoritative text in Hindi 3. Short title 4. Commencement","options":["A-3, B-4, C-1, D-2","A-4, B-3, C-2, D-1","A-3, B-2, C-4, D-1","A-3, B-4, C-2, D-1"],"answer":3,"explanation":"Article 393 gives the short title “the Constitution of India”, 394 deals with commencement, 394A (added by the 58th Amendment, 1987) with the authoritative Hindi text, and 395 with repeals.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अनुच्छेद को उसके विषय से सुमेलित कीजिए: A. अनुच्छेद 393 B. अनुच्छेद 394 C. अनुच्छेद 394A D. अनुच्छेद 395 — 1. भारतीय स्वतंत्रता अधिनियम, 1947 और भारत शासन अधिनियम, 1935 का निरसन 2. हिंदी में प्राधिकृत पाठ 3. संक्षिप्त नाम 4. प्रारंभ","optionsHi":["A-3, B-4, C-1, D-2","A-4, B-3, C-2, D-1","A-3, B-2, C-4, D-1","A-3, B-4, C-2, D-1"],"explanationHi":"अनुच्छेद 393 संक्षिप्त नाम “भारत का संविधान” देता है, 394 प्रारंभ से, 394A (58वें संशोधन, 1987 द्वारा जोड़ा गया) हिंदी में प्राधिकृत पाठ से और 395 निरसनों से संबंधित है।"},
  {"id":"polity-preamble-143","question":"A Supreme Court judge described the secular State as one that is “neither anti-God nor pro-God” and that treats alike the devout, the agnostic and the atheist. In which case was this said?","options":["S. R. Bommai v. Union of India (1994)","St. Xavier’s College v. Gujarat (1974)","Kesavananda Bharati v. State of Kerala (1973)","M. Ismail Faruqui v. Union of India (1994)"],"answer":1,"explanation":"Justice K. K. Mathew said this in St. Xavier’s College (1974), two years before “secular” entered the Preamble. Bommai (1994) is the usual trap: it later declared secularism a basic feature.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"सर्वोच्च न्यायालय के एक न्यायाधीश ने पंथनिरपेक्ष राज्य को ऐसा राज्य बताया जो “न ईश्वर-विरोधी है, न ईश्वर-समर्थक” और श्रद्धालु, अज्ञेयवादी तथा नास्तिक के साथ समान व्यवहार करता है। यह किस मामले में कहा गया?","optionsHi":["एस. आर. बोम्मई बनाम भारत संघ (1994)","सेंट जेवियर्स कॉलेज बनाम गुजरात (1974)","केशवानंद भारती बनाम केरल राज्य (1973)","एम. इस्माइल फारुकी बनाम भारत संघ (1994)"],"explanationHi":"न्यायमूर्ति के. के. मैथ्यू ने यह सेंट जेवियर्स कॉलेज (1974) में कहा, “पंथनिरपेक्ष” के उद्देशिका में आने से दो वर्ष पहले। बोम्मई (1994) सामान्य जाल है: उसने बाद में पंथनिरपेक्षता को मूल विशेषता घोषित किया।"},
  {"id":"polity-preamble-144","question":"In which case did the Supreme Court remark that, after the word “Socialist” was added to the Preamble, courts might lean more in favour of nationalisation and State ownership of industry?","options":["Excel Wear v. Union of India (1979)","D. S. Nakara v. Union of India (1983)","Minerva Mills v. Union of India (1980)","Sanjeev Coke Manufacturing Co. v. Bharat Coking Coal Ltd. (1983)"],"answer":0,"explanation":"Excel Wear (1979), a case on the right to close a business under Article 19(1)(g), made this remark. Nakara linked socialism to a decent standard of life for pensioners, and Sanjeev Coke dealt with Article 39(b).","difficulty":"hard","source":"UPSC Prelims","questionHi":"किस मामले में सर्वोच्च न्यायालय ने टिप्पणी की कि उद्देशिका में “समाजवादी” शब्द जुड़ने के बाद न्यायालय राष्ट्रीयकरण और उद्योग के राज्य स्वामित्व के पक्ष में अधिक झुक सकते हैं?","optionsHi":["एक्सेल वियर बनाम भारत संघ (1979)","डी. एस. नकारा बनाम भारत संघ (1983)","मिनर्वा मिल्स बनाम भारत संघ (1980)","संजीव कोक मैन्युफैक्चरिंग कंपनी बनाम भारत कोकिंग कोल लिमिटेड (1983)"],"explanationHi":"एक्सेल वियर (1979), जो अनुच्छेद 19(1)(g) के अंतर्गत व्यवसाय बंद करने के अधिकार का मामला था, ने यह टिप्पणी की। नकारा ने समाजवाद को पेंशनभोगियों के सम्मानजनक जीवन स्तर से जोड़ा, और संजीव कोक अनुच्छेद 39(b) से संबंधित था।"},
  {"id":"polity-preamble-145","question":"Consider the following statements about the dates in the Preamble: 1. The Preamble records the date on which the Constituent Assembly adopted the Constitution. 2. The Preamble records the date on which the Constitution came into force. 3. When the 42nd Amendment changed the Preamble’s wording in 1976, the date written in it was left as it was. Which of the statements given above is/are correct?","options":["1 only","1 and 3 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"The Preamble ends “this twenty-sixth day of November, 1949”, the date of adoption; the commencement date (26 January 1950) is fixed by Article 394, not the Preamble. The 1976 amendment altered words but kept the 1949 date.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"उद्देशिका में दी गई तिथियों के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. उद्देशिका वह तिथि दर्ज करती है जिस दिन संविधान सभा ने संविधान अंगीकृत किया। 2. उद्देशिका वह तिथि दर्ज करती है जिस दिन संविधान लागू हुआ। 3. जब 42वें संशोधन ने 1976 में उद्देशिका के शब्द बदले, तो उसमें लिखी तिथि जस की तस रखी गई। ऊपर दिए गए कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 1 और 3","केवल 2 और 3","1, 2 और 3"],"explanationHi":"उद्देशिका का अंत “आज तारीख 26 नवंबर, 1949 ई.” से होता है, जो अंगीकरण की तिथि है; प्रारंभ की तिथि (26 जनवरी 1950) अनुच्छेद 394 से तय है, उद्देशिका से नहीं। 1976 के संशोधन ने शब्द बदले पर 1949 की तिथि रखी।"},
  {"id":"polity-preamble-146","question":"Between 15 August 1947 and 26 January 1950, what was the constitutional status of India?","options":["A sovereign republic headed by the President of the Constituent Assembly","A province of the British Empire governed by the Secretary of State under the 1935 Act","A republic within the Commonwealth headed by an elected Governor-General","A dominion under the Indian Independence Act, with the King as formal head"],"answer":3,"explanation":"The Indian Independence Act made India a dominion, with the adapted Government of India Act, 1935 as its interim constitution and a Governor-General representing the King. India became a republic only on 26 January 1950.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"15 अगस्त 1947 से 26 जनवरी 1950 के बीच भारत की संवैधानिक स्थिति क्या थी?","optionsHi":["संविधान सभा के अध्यक्ष की अध्यक्षता वाला संप्रभु गणराज्य","ब्रिटिश साम्राज्य का एक प्रांत, जो 1935 के अधिनियम के अंतर्गत भारत सचिव द्वारा शासित था","राष्ट्रमंडल के भीतर एक गणराज्य जिसका प्रमुख निर्वाचित गवर्नर-जनरल था","भारतीय स्वतंत्रता अधिनियम के अंतर्गत एक डोमिनियन, जिसका औपचारिक प्रमुख सम्राट था"],"explanationHi":"भारतीय स्वतंत्रता अधिनियम ने भारत को डोमिनियन बनाया, जिसमें अनुकूलित भारत शासन अधिनियम, 1935 अंतरिम संविधान था और सम्राट का प्रतिनिधि गवर्नर-जनरल था। भारत 26 जनवरी 1950 को ही गणराज्य बना।"},
  {"id":"polity-preamble-147","question":"Who held office as the last Governor-General of India before it became a republic on 26 January 1950?","options":["Lord Mountbatten","Dr Rajendra Prasad","C. Rajagopalachari","Lord Wavell"],"answer":2,"explanation":"Mountbatten was the first Governor-General of independent India and left in June 1948; C. Rajagopalachari succeeded him and held the post until it ended with the Republic.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"26 जनवरी 1950 को गणराज्य बनने से पहले भारत के अंतिम गवर्नर-जनरल के रूप में किसने पद संभाला?","optionsHi":["लॉर्ड माउंटबेटन","डॉ. राजेंद्र प्रसाद","सी. राजगोपालाचारी","लॉर्ड वेवेल"],"explanationHi":"माउंटबेटन स्वतंत्र भारत के प्रथम गवर्नर-जनरल थे और जून 1948 में गए; सी. राजगोपालाचारी उनके उत्तराधिकारी बने और गणराज्य के साथ पद समाप्त होने तक रहे।"},
  {"id":"polity-preamble-148","question":"How many of the following took place at the final sitting of the Constituent Assembly on 24 January 1950? I. Members signed the Constitution. II. Rajendra Prasad was elected the first President of India. III. “Jana Gana Mana” was adopted as the National Anthem. IV. The Constitution came into force.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"On 24 January 1950 the members signed the Constitution, elected Rajendra Prasad President and adopted the National Anthem (with equal honour for Vande Mataram). The Constitution came into force two days later, on 26 January.","difficulty":"hard","source":"UPSC Prelims","questionHi":"24 जनवरी 1950 को संविधान सभा की अंतिम बैठक में इनमें से कितने कार्य हुए? I. सदस्यों ने संविधान पर हस्ताक्षर किए। II. राजेंद्र प्रसाद भारत के प्रथम राष्ट्रपति चुने गए। III. “जन गण मन” को राष्ट्रगान के रूप में अंगीकृत किया गया। IV. संविधान लागू हुआ।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"24 जनवरी 1950 को सदस्यों ने संविधान पर हस्ताक्षर किए, राजेंद्र प्रसाद को राष्ट्रपति चुना और राष्ट्रगान अंगीकृत किया (वंदे मातरम् को समान सम्मान के साथ)। संविधान दो दिन बाद, 26 जनवरी को लागू हुआ।"},
  {"id":"polity-preamble-149","question":"Consider the following statements about secularism in the Indian Constitution: 1. The State may regulate or restrict economic, financial, political or other secular activity associated with religious practice. 2. The State may provide for throwing open Hindu religious institutions of a public character to all classes and sections of Hindus. 3. The word “secular” is defined in Article 366, the interpretation clause. Which of the statements given above is/are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Articles 25(2)(a) and 25(2)(b) let the State regulate and reform religion, so Indian secularism is not a strict US-style wall of separation. Neither “secular” nor “socialist” is defined anywhere in the Constitution.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"भारतीय संविधान में पंथनिरपेक्षता के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. राज्य धार्मिक आचरण से जुड़े आर्थिक, वित्तीय, राजनीतिक या अन्य लौकिक क्रियाकलाप को विनियमित या सीमित कर सकता है। 2. राज्य सार्वजनिक स्वरूप की हिंदू धार्मिक संस्थाओं को हिंदुओं के सभी वर्गों और अनुभागों के लिए खोलने का उपबंध कर सकता है। 3. “पंथनिरपेक्ष” शब्द की परिभाषा निर्वचन खंड, अनुच्छेद 366, में दी गई है। ऊपर दिए गए कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"अनुच्छेद 25(2)(a) और 25(2)(b) राज्य को धर्म को विनियमित और सुधारने देते हैं, इसलिए भारतीय पंथनिरपेक्षता अमेरिकी शैली की पृथक्करण की कठोर दीवार नहीं है। संविधान में कहीं भी न “पंथनिरपेक्ष” की परिभाषा है, न “समाजवादी” की।"},
  {"id":"polity-preamble-150","question":"In which case did the Supreme Court hold that teaching about the philosophy of different religions in schools, as part of value education, does not offend secularism or Article 28?","options":["Bijoe Emmanuel v. State of Kerala (1986)","S. R. Bommai v. Union of India (1994)","Ahmedabad St. Xavier’s College Society v. State of Gujarat (1974)","Aruna Roy v. Union of India (2002)"],"answer":3,"explanation":"Aruna Roy (2002) upheld the national school curriculum framework, separating education about religions from the religious instruction barred by Article 28(1). Bijoe Emmanuel was about the National Anthem and Article 25.","difficulty":"hard","source":"UPSC Prelims","questionHi":"किस मामले में सर्वोच्च न्यायालय ने माना कि मूल्य शिक्षा के भाग के रूप में स्कूलों में विभिन्न धर्मों के दर्शन की शिक्षा पंथनिरपेक्षता या अनुच्छेद 28 का उल्लंघन नहीं करती?","optionsHi":["बिजोय इमैनुएल बनाम केरल राज्य (1986)","एस. आर. बोम्मई बनाम भारत संघ (1994)","अहमदाबाद सेंट जेवियर्स कॉलेज सोसाइटी बनाम गुजरात राज्य (1974)","अरुणा रॉय बनाम भारत संघ (2002)"],"explanationHi":"अरुणा रॉय (2002) ने राष्ट्रीय विद्यालयी पाठ्यचर्या ढाँचे को बरकरार रखा, और धर्मों के बारे में शिक्षा को अनुच्छेद 28(1) द्वारा वर्जित धार्मिक शिक्षा से अलग किया। बिजोय इमैनुएल राष्ट्रगान और अनुच्छेद 25 से संबंधित था।"},
  {"id":"polity-preamble-151","question":"Consider the following statements: 1. In the Berubari Union reference (1960), the Supreme Court held that ceding Indian territory to a foreign State needs a constitutional amendment under Article 368, not merely a law under Article 3. 2. In Maganbhai Ishwarbhai Patel v. Union of India (1969), the Court held that settling a boundary dispute (the Rann of Kutch award) was not a cession and needed no amendment. 3. The 100th Amendment (2015), giving effect to the Land Boundary Agreement with Bangladesh, amended the First Schedule. Which of the statements given above is/are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":3,"explanation":"All three are correct. Article 3 covers changes among States, so cession needs Article 368 (Berubari); fixing an undefined boundary is not cession (Maganbhai); the 100th Amendment altered the territories of Assam, West Bengal, Meghalaya and Tripura in the First Schedule.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. बेरुबारी संघ संदर्भ (1960) में सर्वोच्च न्यायालय ने माना कि किसी विदेशी राज्य को भारतीय क्षेत्र सौंपने के लिए अनुच्छेद 368 के अंतर्गत संविधान संशोधन चाहिए, केवल अनुच्छेद 3 के अंतर्गत कानून पर्याप्त नहीं। 2. मगनभाई ईश्वरभाई पटेल बनाम भारत संघ (1969) में न्यायालय ने माना कि सीमा विवाद का निपटारा (कच्छ के रण का पंचाट) क्षेत्र सौंपना नहीं था और इसके लिए संशोधन आवश्यक नहीं था। 3. बांग्लादेश के साथ भूमि सीमा समझौते को प्रभावी करने वाले 100वें संशोधन (2015) ने पहली अनुसूची में संशोधन किया। ऊपर दिए गए कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"तीनों सही हैं। अनुच्छेद 3 राज्यों के बीच परिवर्तनों को समेटता है, इसलिए क्षेत्र सौंपने के लिए अनुच्छेद 368 चाहिए (बेरुबारी); अपरिभाषित सीमा तय करना क्षेत्र सौंपना नहीं है (मगनभाई); 100वें संशोधन ने पहली अनुसूची में असम, पश्चिम बंगाल, मेघालय और त्रिपुरा के राज्यक्षेत्र बदले।"},
  {"id":"polity-preamble-152","question":"The word “Republic” in the Preamble carries several implications. Which of these is NOT one of them?","options":["The head of the State is elected for a fixed period instead of holding office by inheritance","Political sovereignty vests in the people and not in a single individual such as a king","The head of the State must be elected directly by the people","There is no privileged class, and every public office is open to every citizen without discrimination"],"answer":2,"explanation":"A republic needs an elected head of State, not a directly elected one; India’s President is chosen indirectly by an electoral college under Article 54.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"उद्देशिका के “गणराज्य” शब्द के कई निहितार्थ हैं। इनमें से कौन-सा उनमें से एक नहीं है?","optionsHi":["राज्य प्रमुख वंशानुगत रूप से पद धारण करने के बजाय निश्चित अवधि के लिए निर्वाचित होता है","राजनीतिक संप्रभुता जनता में निहित है, राजा जैसे किसी एक व्यक्ति में नहीं","राज्य प्रमुख का जनता द्वारा प्रत्यक्ष निर्वाचन आवश्यक है","कोई विशेषाधिकार प्राप्त वर्ग नहीं है, और प्रत्येक सार्वजनिक पद बिना भेदभाव के हर नागरिक के लिए खुला है"],"explanationHi":"गणराज्य के लिए निर्वाचित राज्य प्रमुख चाहिए, प्रत्यक्ष निर्वाचित नहीं; भारत का राष्ट्रपति अनुच्छेद 54 के अंतर्गत निर्वाचक मंडल द्वारा अप्रत्यक्ष रूप से चुना जाता है।"},
  {"id":"polity-preamble-153","question":"Consider the following statements about the Constituent Assembly: 1. The representatives of the British provinces were elected by the members of the provincial legislative assemblies. 2. They were elected by proportional representation by means of the single transferable vote. 3. The Constitution framed by the Assembly was ratified by a nationwide referendum before it came into force. Which of the statements given above is/are correct?","options":["1 and 2 only","2 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Under the Cabinet Mission scheme provincial members were elected indirectly by the provincial assemblies through the single transferable vote. The Constitution was never put to a referendum, a point critics raise against the words “We, the people”.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"संविधान सभा के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. ब्रिटिश प्रांतों के प्रतिनिधि प्रांतीय विधानसभाओं के सदस्यों द्वारा निर्वाचित हुए। 2. वे एकल संक्रमणीय मत द्वारा समानुपातिक प्रतिनिधित्व से निर्वाचित हुए। 3. सभा द्वारा बनाए गए संविधान को लागू होने से पहले राष्ट्रव्यापी जनमत संग्रह द्वारा अनुमोदित किया गया। ऊपर दिए गए कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1 और 2","केवल 2","केवल 1 और 3","1, 2 और 3"],"explanationHi":"कैबिनेट मिशन योजना के अंतर्गत प्रांतीय सदस्य प्रांतीय विधानसभाओं द्वारा एकल संक्रमणीय मत से अप्रत्यक्ष रूप से चुने गए। संविधान पर कभी जनमत संग्रह नहीं हुआ, जिसे आलोचक “हम, भारत के लोग” शब्दों के विरुद्ध उठाते हैं।"},
  {"id":"polity-preamble-154","question":"Consider the following statements: 1. Article 325 provides one general electoral roll for every territorial constituency and bars leaving anyone out of it on grounds only of religion, race, caste or sex. 2. As originally adopted, Article 326 fixed the voting age at 21 years. 3. Article 326 allows a law to disqualify a person from voting on grounds such as non-residence, unsoundness of mind, crime or corrupt practice. Which of the statements given above is/are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":3,"explanation":"All three are correct: Article 325 ended separate electorates, and Article 326 gave universal adult suffrage at 21 (lowered to 18 by the 61st Amendment, 1988), subject to disqualifications laid down by law.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. अनुच्छेद 325 प्रत्येक प्रादेशिक निर्वाचन क्षेत्र के लिए एक साधारण निर्वाचक नामावली का उपबंध करता है और केवल धर्म, मूलवंश, जाति या लिंग के आधार पर किसी को उसमें शामिल होने से वंचित करने पर रोक लगाता है। 2. मूल रूप से अंगीकृत अनुच्छेद 326 ने मतदान की आयु 21 वर्ष निर्धारित की थी। 3. अनुच्छेद 326 अनिवास, चित्त-विकृति, अपराध या भ्रष्ट आचरण जैसे आधारों पर किसी व्यक्ति को मतदान के अयोग्य ठहराने वाले कानून की अनुमति देता है। ऊपर दिए गए कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1 और 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"explanationHi":"तीनों सही हैं: अनुच्छेद 325 ने पृथक निर्वाचन समाप्त किए, और अनुच्छेद 326 ने 21 वर्ष की आयु पर सार्वभौमिक वयस्क मताधिकार दिया (61वें संशोधन, 1988 से घटाकर 18 वर्ष), जो विधि द्वारा निर्धारित अयोग्यताओं के अधीन है।"},
  {"id":"polity-preamble-155","question":"In what order does the Preamble list the liberties it secures to all citizens?","options":["Thought, expression, belief, faith and worship","Thought, belief, expression, faith and worship","Expression, thought, faith, belief and worship","Belief, faith, thought, expression and worship"],"answer":0,"explanation":"The text reads “LIBERTY of thought, expression, belief, faith and worship”: the two intellectual liberties first, then the three religious ones.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"उद्देशिका सभी नागरिकों को जिन स्वतंत्रताओं का आश्वासन देती है, वे किस क्रम में सूचीबद्ध हैं?","optionsHi":["विचार, अभिव्यक्ति, विश्वास, धर्म और उपासना","विचार, विश्वास, अभिव्यक्ति, धर्म और उपासना","अभिव्यक्ति, विचार, धर्म, विश्वास और उपासना","विश्वास, धर्म, विचार, अभिव्यक्ति और उपासना"],"explanationHi":"पाठ है “विचार, अभिव्यक्ति, विश्वास, धर्म और उपासना की स्वतंत्रता”: पहले दो बौद्धिक स्वतंत्रताएँ, फिर तीन धार्मिक।"},
  {"id":"polity-preamble-156","question":"Which of these was NOT adopted by the Constituent Assembly?","options":["The National Flag","The National Anthem","The State Emblem taken from the Lion Capital of Sarnath","The equal status of the National Song with the National Anthem"],"answer":2,"explanation":"The Assembly adopted the Flag on 22 July 1947 and the Anthem, with equal honour for Vande Mataram, on 24 January 1950. The State Emblem was adopted by the Government of India on 26 January 1950.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"इनमें से कौन-सा संविधान सभा द्वारा अंगीकृत नहीं किया गया?","optionsHi":["राष्ट्रीय ध्वज","राष्ट्रगान","सारनाथ के सिंह स्तंभ शीर्ष से लिया गया राज्य चिह्न","राष्ट्रगीत को राष्ट्रगान के समान दर्जा"],"explanationHi":"सभा ने ध्वज 22 जुलाई 1947 को और राष्ट्रगान, वंदे मातरम् को समान सम्मान के साथ, 24 जनवरी 1950 को अंगीकृत किया। राज्य चिह्न भारत सरकार ने 26 जनवरी 1950 को अपनाया।"},
  {"id":"polity-preamble-157","question":"Consider the following statements: 1. A country can be a democracy without being a republic. 2. A country can be a republic without being a democracy. 3. India and the United Kingdom are both parliamentary democracies, but only India is a republic. Which of the statements given above is/are correct?","options":["1 only","1 and 3 only","2 and 3 only","1, 2 and 3"],"answer":3,"explanation":"Democracy is about who holds power (the people); republic only means a non-hereditary head of State. The UK is a democracy with a hereditary monarch, and some elected-head States are not democratic.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. कोई देश गणराज्य हुए बिना भी लोकतंत्र हो सकता है। 2. कोई देश लोकतंत्र हुए बिना भी गणराज्य हो सकता है। 3. भारत और यूनाइटेड किंगडम दोनों संसदीय लोकतंत्र हैं, परंतु केवल भारत गणराज्य है। ऊपर दिए गए कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 1 और 3","केवल 2 और 3","1, 2 और 3"],"explanationHi":"लोकतंत्र इस बारे में है कि सत्ता किसके पास है (जनता); गणराज्य का अर्थ केवल गैर-वंशानुगत राज्य प्रमुख है। यूके वंशानुगत राजा वाला लोकतंत्र है, और निर्वाचित प्रमुख वाले कुछ राज्य लोकतांत्रिक नहीं हैं।"},
  {"id":"polity-preamble-158","question":"Being sovereign, India can enter into treaties with other countries. Which Article empowers Parliament to make a law for the whole or any part of India, even on a State List subject, to implement a treaty or international agreement?","options":["Article 249","Article 252","Article 253","Article 51"],"answer":2,"explanation":"Article 253 lets Parliament legislate to give effect to international agreements. Article 249 needs a Rajya Sabha resolution, Article 252 needs the consent of two or more States, and Article 51 is only a directive.","difficulty":"hard","source":"UPSC Prelims","questionHi":"संप्रभु होने के नाते भारत अन्य देशों के साथ संधियाँ कर सकता है। कौन-सा अनुच्छेद संसद को किसी संधि या अंतरराष्ट्रीय समझौते को लागू करने के लिए, राज्य सूची के विषय पर भी, संपूर्ण या भारत के किसी भाग के लिए कानून बनाने का अधिकार देता है?","optionsHi":["अनुच्छेद 249","अनुच्छेद 252","अनुच्छेद 253","अनुच्छेद 51"],"explanationHi":"अनुच्छेद 253 संसद को अंतरराष्ट्रीय समझौतों को प्रभावी करने के लिए कानून बनाने देता है। अनुच्छेद 249 के लिए राज्यसभा का संकल्प, अनुच्छेद 252 के लिए दो या अधिक राज्यों की सहमति चाहिए, और अनुच्छेद 51 केवल निदेशक तत्व है।"},
  {"id":"polity-preamble-159","question":"Who was the only Dalit woman member of the Constituent Assembly?","options":["Hansa Jivraj Mehta","Dakshayani Velayudhan","Ammu Swaminathan","Vijaya Lakshmi Pandit"],"answer":1,"explanation":"Dakshayani Velayudhan, elected from Madras, was the only Dalit woman among the Assembly’s fifteen women members; the others named were also members but not Dalit.","difficulty":"hard","source":"UPSC Prelims","questionHi":"संविधान सभा की एकमात्र दलित महिला सदस्य कौन थीं?","optionsHi":["हंसा जीवराज मेहता","दक्षायणी वेलायुधन","अम्मू स्वामीनाथन","विजयलक्ष्मी पंडित"],"explanationHi":"मद्रास से निर्वाचित दक्षायणी वेलायुधन सभा की पंद्रह महिला सदस्यों में एकमात्र दलित महिला थीं; अन्य नामित महिलाएँ भी सदस्य थीं पर दलित नहीं थीं।"},
  {"id":"polity-preamble-160","question":"Assertion (A): Parliament cannot, by a constitutional amendment, remove the words “Democratic Republic” from the Preamble. Reason (R): In Kesavananda Bharati (1973), the Supreme Court held that the amending power under Article 368 cannot be used to destroy the basic structure of the Constitution.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"The Preamble can be amended, but its basic elements such as the democratic and republican form of government are part of the basic structure, which Kesavananda placed beyond the amending power.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): संसद संविधान संशोधन द्वारा उद्देशिका से “लोकतंत्रात्मक गणराज्य” शब्द नहीं हटा सकती। कारण (R): केशवानंद भारती (1973) में सर्वोच्च न्यायालय ने माना कि अनुच्छेद 368 के अंतर्गत संशोधन की शक्ति का प्रयोग संविधान के मूल ढाँचे को नष्ट करने के लिए नहीं किया जा सकता।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"उद्देशिका में संशोधन हो सकता है, परंतु इसके मूल तत्व, जैसे शासन का लोकतांत्रिक और गणराज्यीय स्वरूप, मूल ढाँचे का भाग हैं, जिन्हें केशवानंद ने संशोधन की शक्ति से परे रखा।"},
  {"id":"polity-preamble-161","question":"Consider the following statements about Abhiram Singh v. C. D. Commachen (2017): 1. It was decided by a seven-judge bench. 2. The majority held that an appeal for votes in the name of the religion of the voters, and not only of the candidate, is a corrupt practice under Section 123(3) of the Representation of the People Act. 3. The decision was unanimous. Which of the statements given above is/are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"By a 4:3 majority the seven-judge bench read “his religion” in Section 123(3) to cover the religion of the candidate, the voters and the agents, relying on the secular character of elections.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिराम सिंह बनाम सी. डी. कोमाचेन (2017) के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. इसका निर्णय सात न्यायाधीशों की पीठ ने किया। 2. बहुमत ने माना कि केवल उम्मीदवार के नहीं, मतदाताओं के धर्म के नाम पर भी वोट माँगना जनप्रतिनिधित्व अधिनियम की धारा 123(3) के अंतर्गत भ्रष्ट आचरण है। 3. निर्णय सर्वसम्मत था। ऊपर दिए गए कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"4:3 के बहुमत से सात न्यायाधीशों की पीठ ने चुनावों के पंथनिरपेक्ष स्वरूप के आधार पर धारा 123(3) के “उसके धर्म” को उम्मीदवार, मतदाताओं और अभिकर्ताओं के धर्म तक विस्तृत पढ़ा।"},
  {"id":"polity-preamble-162","question":"Apart from the Preamble, the words “justice, social, economic and political” occur in which provision?","options":["Article 39(b)","Article 39A","Article 46","Article 38(1)"],"answer":3,"explanation":"Article 38(1) directs the State to secure a social order in which justice, social, economic and political, shall inform all institutions of national life. Article 39A, the common trap, is about equal justice and free legal aid.","difficulty":"hard","source":"UPSC Prelims","questionHi":"उद्देशिका के अलावा “न्याय, सामाजिक, आर्थिक और राजनीतिक” शब्द किस प्रावधान में आते हैं?","optionsHi":["अनुच्छेद 39(b)","अनुच्छेद 39A","अनुच्छेद 46","अनुच्छेद 38(1)"],"explanationHi":"अनुच्छेद 38(1) राज्य को ऐसी सामाजिक व्यवस्था सुनिश्चित करने का निर्देश देता है जिसमें राष्ट्रीय जीवन की सभी संस्थाओं को सामाजिक, आर्थिक और राजनीतिक न्याय अनुप्राणित करे। अनुच्छेद 39A, सामान्य जाल, समान न्याय और निःशुल्क विधिक सहायता के बारे में है।"},
  {"id":"polity-preamble-163","question":"Consider the following statements about Sikkim: 1. The 35th Amendment (1974) made Sikkim an “associate State” of the Indian Union. 2. The 36th Amendment (1975) made Sikkim a full State and inserted Article 371F. 3. Sikkim was brought in under Article 3, which deals with forming new States out of existing Indian territory. Which of the statements given above is/are correct?","options":["1 and 2 only","2 only","1 and 3 only","2 and 3 only"],"answer":0,"explanation":"The 35th Amendment added Article 2A and a Tenth Schedule for associate status; the 36th made Sikkim the 22nd State with Article 371F. A territory from outside India is admitted under Article 2, not Article 3.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"सिक्किम के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. 35वें संशोधन (1974) ने सिक्किम को भारतीय संघ का “सह-राज्य” (associate State) बनाया। 2. 36वें संशोधन (1975) ने सिक्किम को पूर्ण राज्य बनाया और अनुच्छेद 371F जोड़ा। 3. सिक्किम को अनुच्छेद 3 के अंतर्गत लाया गया, जो मौजूदा भारतीय क्षेत्र से नए राज्य बनाने से संबंधित है। ऊपर दिए गए कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1 और 2","केवल 2","केवल 1 और 3","केवल 2 और 3"],"explanationHi":"35वें संशोधन ने सह-राज्य के दर्जे के लिए अनुच्छेद 2A और दसवीं अनुसूची जोड़ी; 36वें ने अनुच्छेद 371F के साथ सिक्किम को 22वाँ राज्य बनाया। भारत के बाहर के क्षेत्र को अनुच्छेद 2 के अंतर्गत शामिल किया जाता है, अनुच्छेद 3 के नहीं।"},
  {"id":"polity-preamble-164","question":"Consider the following statements based on Article 1: 1. The “Union of India” includes only the States. 2. The “territory of India” includes the States, the Union Territories and any territories that may be acquired. 3. Any territory acquired by India automatically becomes a State of the Union. Which of the statements given above is/are correct?","options":["1 only","2 only","1 and 2 only","2 and 3 only"],"answer":2,"explanation":"“Territory of India” is the wider term, covering States, Union Territories and acquired territories; the Union consists only of the States. An acquired territory becomes a State only if Parliament so provides.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अनुच्छेद 1 पर आधारित निम्नलिखित कथनों पर विचार कीजिए: 1. “भारत संघ” में केवल राज्य शामिल हैं। 2. “भारत के राज्यक्षेत्र” में राज्य, संघ राज्यक्षेत्र और अर्जित किए जा सकने वाले राज्यक्षेत्र शामिल हैं। 3. भारत द्वारा अर्जित कोई भी राज्यक्षेत्र स्वतः संघ का राज्य बन जाता है। ऊपर दिए गए कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","केवल 1 और 2","केवल 2 और 3"],"explanationHi":"“भारत का राज्यक्षेत्र” व्यापक शब्द है, जिसमें राज्य, संघ राज्यक्षेत्र और अर्जित राज्यक्षेत्र शामिल हैं; संघ में केवल राज्य होते हैं। अर्जित राज्यक्षेत्र राज्य तभी बनता है जब संसद ऐसा उपबंध करे।"},
  {"id":"polity-preamble-165","question":"Dr. B. R. Ambedkar first entered the Constituent Assembly in 1946 as a member elected from which province?","options":["Bombay","Bengal","Central Provinces and Berar","United Provinces"],"answer":1,"explanation":"He was elected from Bengal with Jogendra Nath Mandal’s support; when his area went to East Pakistan at Partition he lost the seat and was re-elected from Bombay, which is the usual trap.","difficulty":"hard","source":"UPSC Prelims","questionHi":"डॉ. बी. आर. अंबेडकर 1946 में पहली बार संविधान सभा में किस प्रांत से निर्वाचित सदस्य के रूप में आए?","optionsHi":["बंबई","बंगाल","मध्य प्रांत और बरार","संयुक्त प्रांत"],"explanationHi":"वे जोगेंद्र नाथ मंडल के समर्थन से बंगाल से चुने गए; विभाजन में उनका क्षेत्र पूर्वी पाकिस्तान में चले जाने पर उनकी सीट चली गई और वे बंबई से पुनः चुने गए, जो सामान्य जाल है।"},
  {"id":"polity-preamble-166","question":"Who was elected Vice-President of the Constituent Assembly?","options":["H. C. Mukherjee","Sachchidananda Sinha","K. M. Munshi","B. N. Rau"],"answer":0,"explanation":"H. C. Mukherjee was the Vice-President. Sachchidananda Sinha was only the temporary President at the first meeting, and B. N. Rau was the Constitutional Adviser, not a presiding officer.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"संविधान सभा का उपाध्यक्ष कौन चुना गया?","optionsHi":["एच. सी. मुखर्जी","सच्चिदानंद सिन्हा","के. एम. मुंशी","बी. एन. राव"],"explanationHi":"एच. सी. मुखर्जी उपाध्यक्ष थे। सच्चिदानंद सिन्हा पहली बैठक में केवल अस्थायी अध्यक्ष थे, और बी. एन. राव संवैधानिक सलाहकार थे, पीठासीन अधिकारी नहीं।"},
  {"id":"polity-preamble-167","question":"Consider the following statements: 1. In Maganbhai Ishwarbhai Patel v. Union of India (1969), the Supreme Court held that giving effect to the Kutch award, which settled a boundary dispute, needed no constitutional amendment. 2. In the Berubari reference (1960), the Supreme Court held that ceding Indian territory to a foreign State can be done by a law under Article 3. 3. The 101st Amendment (2015), which gave effect to the India–Bangladesh land boundary agreement, amended the First Schedule. How many of the above statements are correct?","options":["Only one","Only two","All three","None of them"],"answer":0,"explanation":"Only statement 1 is correct (settling a boundary is not cession). Statement 2 is wrong: Berubari held that cession needs an Article 368 amendment, not an Article 3 law. Statement 3 is wrong: the land boundary agreement was given effect by the 100th Amendment; the 101st (2016) introduced GST.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. मगनभाई ईश्वरभाई पटेल बनाम भारत संघ (1969) में सर्वोच्च न्यायालय ने माना कि कच्छ पंचाट को, जिसने सीमा विवाद सुलझाया, प्रभावी करने के लिए संविधान संशोधन आवश्यक नहीं था। 2. बेरुबारी संदर्भ (1960) में सर्वोच्च न्यायालय ने माना कि किसी विदेशी राज्य को भारतीय क्षेत्र सौंपना अनुच्छेद 3 के अंतर्गत कानून से किया जा सकता है। 3. भारत–बांग्लादेश भूमि सीमा समझौते को प्रभावी करने वाले 101वें संशोधन (2015) ने पहली अनुसूची में संशोधन किया। उपर्युक्त में से कितने कथन सही हैं?","optionsHi":["केवल एक","केवल दो","तीनों","इनमें से कोई नहीं"],"explanationHi":"केवल कथन 1 सही है (सीमा निपटाना क्षेत्र सौंपना नहीं है)। कथन 2 गलत है: बेरुबारी ने माना कि क्षेत्र सौंपने के लिए अनुच्छेद 368 का संशोधन चाहिए, अनुच्छेद 3 का कानून नहीं। कथन 3 गलत है: भूमि सीमा समझौते को 100वें संशोधन ने प्रभावी किया; 101वें (2016) ने GST लागू किया।"},
  {"id":"polity-preamble-168","question":"Consider the following statements about Articles 2 to 4: 1. Article 2 lets Parliament admit into the Union, or establish, new States that were not part of India. 2. A Bill under Article 3 can be introduced in either House only on the recommendation of the President. 3. Where an Article 3 Bill affects a State, the President must refer it to that State's legislature for its views within a specified period. 4. A law under Article 3 that alters the First and Fourth Schedules is not deemed an amendment of the Constitution for the purposes of Article 368. How many of the above statements are correct?","options":["Only one","Only two","Only three","All four of them"],"answer":3,"explanation":"All four are correct. Articles 2 and 3 allow new States and reorganisation; the proviso to Article 3 requires the President's recommendation and a reference to the affected State legislature (whose views are not binding), and Article 4(2) saves such laws from Article 368.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अनुच्छेद 2 से 4 के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. अनुच्छेद 2 संसद को ऐसे नए राज्यों को संघ में प्रवेश देने या स्थापित करने देता है जो भारत का भाग नहीं थे। 2. अनुच्छेद 3 के अंतर्गत विधेयक किसी भी सदन में केवल राष्ट्रपति की सिफारिश पर पेश हो सकता है। 3. जहाँ अनुच्छेद 3 का विधेयक किसी राज्य को प्रभावित करता है, वहाँ राष्ट्रपति को उसे उस राज्य के विधानमंडल को निर्धारित अवधि में उसके विचार जानने के लिए भेजना होता है। 4. अनुच्छेद 3 के अंतर्गत पहली और चौथी अनुसूची को बदलने वाला कानून अनुच्छेद 368 के प्रयोजन के लिए संविधान का संशोधन नहीं माना जाता। उपर्युक्त में से कितने कथन सही हैं?","optionsHi":["केवल एक","केवल दो","केवल तीन","चारों"],"explanationHi":"चारों सही हैं। अनुच्छेद 2 और 3 नए राज्यों और पुनर्गठन की अनुमति देते हैं; अनुच्छेद 3 का परंतुक राष्ट्रपति की सिफारिश और प्रभावित राज्य विधानमंडल को संदर्भित करने की अपेक्षा करता है (जिसके विचार बाध्यकारी नहीं हैं), और अनुच्छेद 4(2) ऐसे कानूनों को अनुच्छेद 368 से बाहर रखता है।"},
  {"id":"polity-preamble-169","question":"Consider the following statements: 1. No religious instruction may be given in any educational institution wholly maintained out of State funds. 2. That bar does not apply to an institution administered by the State but established under an endowment or trust that requires religious instruction to be given. 3. A student of a State-aided minority institution may be required to attend its religious instruction without his or his guardian's consent. 4. No person can be compelled to pay a tax whose proceeds are specifically appropriated to promote a particular religion. Which of the above are correct?","options":["1 and 4 only","1, 2 and 4 only","2, 3 and 4 only","1, 2, 3 and 4"],"answer":1,"explanation":"Article 28(1) and 28(2) give statements 1 and 2, and Article 27 gives statement 4. Article 28(3) requires consent (a guardian's for a minor) before anyone in a State-recognised or aided institution attends religious instruction, so 3 is wrong.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. पूर्णतः राज्य निधि से पोषित किसी शिक्षा संस्था में कोई धार्मिक शिक्षा नहीं दी जा सकती। 2. यह रोक उस संस्था पर लागू नहीं होती जो राज्य द्वारा प्रशासित है पर किसी ऐसे बंदोबस्त या न्यास के अधीन स्थापित है जिसमें धार्मिक शिक्षा देना आवश्यक है। 3. राज्य से सहायता पाने वाली अल्पसंख्यक संस्था के विद्यार्थी से उसकी या उसके संरक्षक की सहमति के बिना उसकी धार्मिक शिक्षा में उपस्थित होने की अपेक्षा की जा सकती है। 4. किसी व्यक्ति को ऐसा कर देने के लिए बाध्य नहीं किया जा सकता जिसकी आय किसी विशिष्ट धर्म की अभिवृद्धि में व्यय के लिए विनिर्दिष्ट रूप से विनियोजित हो। उपर्युक्त में से कौन-से सही हैं?","optionsHi":["केवल 1 और 4","केवल 1, 2 और 4","केवल 2, 3 और 4","1, 2, 3 और 4"],"explanationHi":"अनुच्छेद 28(1) और 28(2) से कथन 1 और 2 तथा अनुच्छेद 27 से कथन 4 आते हैं। अनुच्छेद 28(3) राज्य-मान्यताप्राप्त या सहायता प्राप्त संस्था में किसी के धार्मिक शिक्षा में उपस्थित होने से पहले सहमति (नाबालिग के लिए संरक्षक की) आवश्यक करता है, इसलिए 3 गलत है।"},
  {"id":"polity-preamble-170","question":"How many of the following devices of direct democracy does the Constitution of India provide for in Union-level decision-making? Referendum, Initiative, Recall, Plebiscite","options":["Only one","Only two","Only three","None"],"answer":3,"explanation":"India is a representative (indirect) democracy: the Constitution provides for none of these four devices at the Union level. The Gram Sabha is the closest thing to direct democracy, and it works at village level.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"भारत का संविधान संघ स्तर पर निर्णय-निर्माण में प्रत्यक्ष लोकतंत्र के निम्नलिखित साधनों में से कितनों का प्रावधान करता है? जनमत संग्रह, पहल (इनिशिएटिव), प्रत्यावर्तन (रिकॉल), जनमतसंग्रह (प्लेबिसाइट)","optionsHi":["केवल एक","केवल दो","केवल तीन","कोई नहीं"],"explanationHi":"भारत प्रतिनिधिक (अप्रत्यक्ष) लोकतंत्र है: संविधान संघ स्तर पर इन चारों साधनों में से किसी का प्रावधान नहीं करता। ग्राम सभा प्रत्यक्ष लोकतंत्र के सबसे निकट है, और वह गाँव स्तर पर कार्य करती है।"},
  {"id":"polity-preamble-171","question":"Match the committee of the Constituent Assembly with its chairman: A. Steering Committee B. Provincial Constitution Committee C. States Committee (for negotiating with the princely States) D. Fundamental Rights Sub-Committee — 1. Rajendra Prasad 2. Vallabhbhai Patel 3. Jawaharlal Nehru 4. J. B. Kripalani","options":["A-1, B-2, C-3, D-4","A-1, B-3, C-2, D-4","A-3, B-2, C-1, D-4","A-1, B-2, C-4, D-3"],"answer":0,"explanation":"Prasad chaired the Steering Committee, Patel the Provincial Constitution Committee, Nehru the States Committee and Kripalani the Fundamental Rights Sub-Committee. The trap is to give Patel the States Committee because he integrated the princely States.","difficulty":"hard","source":"UPSC Prelims","questionHi":"संविधान सभा की समिति को उसके अध्यक्ष से सुमेलित कीजिए: A. संचालन समिति B. प्रांतीय संविधान समिति C. राज्य समिति (देशी रियासतों से वार्ता के लिए) D. मौलिक अधिकार उप-समिति — 1. राजेंद्र प्रसाद 2. वल्लभभाई पटेल 3. जवाहरलाल नेहरू 4. जे. बी. कृपलानी","optionsHi":["A-1, B-2, C-3, D-4","A-1, B-3, C-2, D-4","A-3, B-2, C-1, D-4","A-1, B-2, C-4, D-3"],"explanationHi":"प्रसाद ने संचालन समिति, पटेल ने प्रांतीय संविधान समिति, नेहरू ने राज्य समिति और कृपलानी ने मौलिक अधिकार उप-समिति की अध्यक्षता की। जाल यह है कि पटेल को राज्य समिति दे दी जाए क्योंकि उन्होंने रियासतों का एकीकरण किया।"},
  {"id":"polity-preamble-172","question":"How many of the following pairs of a body of the Constituent Assembly and its chairman are correctly matched? 1. Minorities Sub-Committee – H. C. Mukherjee 2. North-East Frontier (Assam) Tribal and Excluded Areas Sub-Committee – Gopinath Bardoloi 3. Order of Business Committee – K. M. Munshi 4. House Committee – B. Pattabhi Sitaramayya","options":["Only one","Only two","Only three","All four of them"],"answer":3,"explanation":"All four pairs are correct: H. C. Mukherjee chaired the Minorities Sub-Committee, Gopinath Bardoloi the North-East Frontier Tribal Sub-Committee, K. M. Munshi the Order of Business Committee and B. Pattabhi Sitaramayya the House Committee.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"संविधान सभा के निकाय और उसके अध्यक्ष के निम्नलिखित युग्मों में से कितने सही सुमेलित हैं? 1. अल्पसंख्यक उप-समिति – एच. सी. मुखर्जी 2. पूर्वोत्तर सीमांत (असम) जनजातीय और अपवर्जित क्षेत्र उप-समिति – गोपीनाथ बारदोलोई 3. कार्य-सूची समिति – के. एम. मुंशी 4. सदन समिति – बी. पट्टाभि सीतारमैया","optionsHi":["केवल एक","केवल दो","केवल तीन","चारों"],"explanationHi":"चारों युग्म सही हैं: एच. सी. मुखर्जी ने अल्पसंख्यक उप-समिति, गोपीनाथ बारदोलोई ने पूर्वोत्तर सीमांत जनजातीय उप-समिति, के. एम. मुंशी ने कार्य-सूची समिति और बी. पट्टाभि सीतारमैया ने सदन समिति की अध्यक्षता की।"},
  {"id":"polity-preamble-173","question":"D. P. Khaitan, a member of the Drafting Committee, died in 1948. Who replaced him on the Committee?","options":["Syed Mohammad Saadullah","N. Gopalaswamy Ayyangar","N. Madhava Rau","T. T. Krishnamachari"],"answer":3,"explanation":"T. T. Krishnamachari replaced Khaitan. N. Madhava Rau replaced B. L. Mitter, who resigned; Saadullah and Gopalaswamy Ayyangar were original members.","difficulty":"hard","source":"UPSC Prelims","questionHi":"प्रारूप समिति के सदस्य डी. पी. खेतान का 1948 में निधन हो गया। समिति में उनकी जगह किसने ली?","optionsHi":["सैयद मोहम्मद सादुल्ला","एन. गोपालस्वामी अय्यंगार","एन. माधव राव","टी. टी. कृष्णमाचारी"],"explanationHi":"टी. टी. कृष्णमाचारी ने खेतान की जगह ली। एन. माधव राव ने त्यागपत्र देने वाले बी. एल. मित्तर की जगह ली; सादुल्ला और गोपालस्वामी अय्यंगार मूल सदस्य थे।"},
  {"id":"polity-preamble-174","question":"How many of the following expressions occur in the text of the Preamble? 1. Dignity of the individual 2. Rule of law 3. Equality before law 4. Liberty of belief","options":["Only one","Only two","Only three","All four of them"],"answer":1,"explanation":"‘Dignity of the individual’ and liberty of ‘thought, expression, belief, faith and worship’ appear. ‘Equality before law’ is Article 14’s phrase (the Preamble says equality ‘of status and of opportunity’), and ‘rule of law’ appears nowhere in the Constitution’s text.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित में से कितने अभिव्यक्तियाँ उद्देशिका के पाठ में आती हैं? 1. व्यक्ति की गरिमा 2. विधि का शासन 3. विधि के समक्ष समता 4. विश्वास की स्वतंत्रता","optionsHi":["केवल एक","केवल दो","केवल तीन","चारों"],"explanationHi":"“व्यक्ति की गरिमा” और “विचार, अभिव्यक्ति, विश्वास, धर्म और उपासना” की स्वतंत्रता आती हैं। “विधि के समक्ष समता” अनुच्छेद 14 का वाक्यांश है (उद्देशिका “प्रतिष्ठा और अवसर की समता” कहती है), और “विधि का शासन” संविधान के पाठ में कहीं नहीं आता।"},
  {"id":"polity-preamble-175","question":"The Preamble secures liberty of belief, faith and worship to ‘all its citizens’, but Article 25 gives freedom of religion to ‘all persons’. A foreign national in India claims Article 25. Which statement is correct?","options":["The Preamble controls Part III, so only citizens can claim Article 25","Foreigners may claim Article 25 only while no Emergency is in force","Article 25 was extended to foreigners only by the 42nd Amendment","Part III prevails, so the foreigner can claim Article 25"],"answer":3,"explanation":"The Preamble states objectives and cannot cut down the express words of an Article; Article 25 says ‘all persons’, so foreigners are covered. The 42nd Amendment did not touch Article 25’s scope.","difficulty":"hard","source":"UPSC Prelims","questionHi":"उद्देशिका ‘इसके समस्त नागरिकों’ को विश्वास, धर्म और उपासना की स्वतंत्रता देती है, परंतु अनुच्छेद 25 ‘सभी व्यक्तियों’ को धर्म की स्वतंत्रता देता है। भारत में एक विदेशी नागरिक अनुच्छेद 25 का दावा करता है। कौन-सा कथन सही है?","optionsHi":["उद्देशिका भाग III को नियंत्रित करती है, इसलिए केवल नागरिक अनुच्छेद 25 का दावा कर सकते हैं","विदेशी अनुच्छेद 25 का दावा केवल तब कर सकते हैं जब आपातकाल लागू न हो","अनुच्छेद 25 विदेशियों तक केवल 42वें संशोधन द्वारा बढ़ाया गया","भाग III प्रभावी होता है, इसलिए विदेशी अनुच्छेद 25 का दावा कर सकता है"],"explanationHi":"उद्देशिका उद्देश्य बताती है और किसी अनुच्छेद के स्पष्ट शब्दों को कम नहीं कर सकती; अनुच्छेद 25 “सभी व्यक्तियों” कहता है, इसलिए विदेशी भी आते हैं। 42वें संशोधन ने अनुच्छेद 25 के विस्तार को नहीं छुआ।"},
  {"id":"polity-preamble-176","question":"Assertion (A): Critics argued that the claim ‘We, the people of India … give to ourselves this Constitution’ rested on a weak popular mandate. Reason (R): Members of the Constituent Assembly were chosen indirectly by provincial assemblies that had themselves been elected on a limited franchise.","options":["Both A and R are true, and R explains A","Both A and R are true, but R does not explain A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"The 1946 provincial assemblies were elected on the restricted franchise of the Government of India Act, 1935, and they elected the Assembly; this is exactly why its representative character was questioned.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): आलोचकों ने तर्क दिया कि ‘हम, भारत के लोग … इस संविधान को आत्मार्पित करते हैं’ का दावा कमजोर जनादेश पर टिका था। कारण (R): संविधान सभा के सदस्य प्रांतीय विधानसभाओं द्वारा अप्रत्यक्ष रूप से चुने गए थे, जो स्वयं सीमित मताधिकार पर चुनी गई थीं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की व्याख्या करता है","A और R दोनों सत्य हैं, परंतु R, A की व्याख्या नहीं करता","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"1946 की प्रांतीय विधानसभाएँ भारत शासन अधिनियम, 1935 के सीमित मताधिकार पर चुनी गई थीं, और उन्होंने सभा को चुना; इसीलिए इसके प्रतिनिधिक स्वरूप पर प्रश्न उठा।"},
  {"id":"polity-preamble-177","question":"Assertion (A): The Constituent Assembly declined to describe India as ‘socialist’ in the Constitution it adopted in 1949. Reason (R): Ambedkar argued that the economic organisation of society should be left to the people to decide according to time and circumstances, not fixed in the Constitution.","options":["Both A and R are true, and R explains A","Both A and R are true, but R does not explain A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"When K. T. Shah moved to describe India as a secular, federal, socialist Union, Ambedkar opposed it on this ground and the amendment failed; ‘Socialist’ came only with the 42nd Amendment in 1976.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): संविधान सभा ने 1949 में अंगीकृत संविधान में भारत को ‘समाजवादी’ बताने से इनकार कर दिया। कारण (R): अंबेडकर ने तर्क दिया कि समाज का आर्थिक संगठन समय और परिस्थितियों के अनुसार जनता को तय करने के लिए छोड़ा जाना चाहिए, संविधान में तय नहीं किया जाना चाहिए।","optionsHi":["A और R दोनों सत्य हैं, और R, A की व्याख्या करता है","A और R दोनों सत्य हैं, परंतु R, A की व्याख्या नहीं करता","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"जब के. टी. शाह ने भारत को पंथनिरपेक्ष, संघीय, समाजवादी संघ बताने का प्रस्ताव रखा, तो अंबेडकर ने इसी आधार पर विरोध किया और संशोधन विफल रहा; ‘समाजवादी’ केवल 1976 में 42वें संशोधन से आया।"},
  {"id":"polity-preamble-178","question":"How many of the following pairs of a feature of the Constitution and the source it was borrowed from are correctly matched? 1. Joint sitting of the two Houses – Australia 2. Advisory jurisdiction of the Supreme Court – USA 3. Procedure established by law – Japan 4. Nomination of members to the Rajya Sabha – Ireland","options":["Only one","Only two","Only three","All four of them"],"answer":2,"explanation":"Pairs 1, 3 and 4 are correct. The advisory jurisdiction (Article 143) was taken from Canada; the US Supreme Court gives no advisory opinions.","difficulty":"hard","source":"UPSC Prelims","questionHi":"संविधान की विशेषता और उसके स्रोत के निम्नलिखित युग्मों में से कितने सही सुमेलित हैं? 1. दोनों सदनों की संयुक्त बैठक – ऑस्ट्रेलिया 2. सर्वोच्च न्यायालय का परामर्शी क्षेत्राधिकार – अमेरिका 3. विधि द्वारा स्थापित प्रक्रिया – जापान 4. राज्यसभा में सदस्यों का मनोनयन – आयरलैंड","optionsHi":["केवल एक","केवल दो","केवल तीन","चारों"],"explanationHi":"युग्म 1, 3 और 4 सही हैं। परामर्शी क्षेत्राधिकार (अनुच्छेद 143) कनाडा से लिया गया; अमेरिकी सर्वोच्च न्यायालय परामर्शी राय नहीं देता।"},
  {"id":"polity-preamble-179","question":"Consider the following statements about Article 3: 1. The power to form a new State includes uniting a part of a State or Union territory to another State or Union territory. 2. A Bill under Article 3 affecting a Union territory with a legislature must first be referred to that legislature for its views. 3. If the affected State consents, the Bill may be introduced without the President's recommendation. Which of the above is/are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Explanation II to Article 3 (18th Amendment, 1966) supports 1. Explanation I says ‘State’ in the proviso does not include a Union territory, so no reference to a UT legislature is needed; and the President's recommendation is always required.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अनुच्छेद 3 के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. नया राज्य बनाने की शक्ति में किसी राज्य या संघ राज्यक्षेत्र के भाग को किसी अन्य राज्य या संघ राज्यक्षेत्र से मिलाना शामिल है। 2. विधानमंडल वाले संघ राज्यक्षेत्र को प्रभावित करने वाला अनुच्छेद 3 का विधेयक पहले उस विधानमंडल को उसके विचार के लिए भेजा जाना चाहिए। 3. यदि प्रभावित राज्य सहमत हो, तो विधेयक राष्ट्रपति की सिफारिश के बिना पेश किया जा सकता है। उपर्युक्त में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"अनुच्छेद 3 का स्पष्टीकरण II (18वाँ संशोधन, 1966) कथन 1 का समर्थन करता है। स्पष्टीकरण I कहता है कि परंतुक में ‘राज्य’ में संघ राज्यक्षेत्र शामिल नहीं है, इसलिए संघ राज्यक्षेत्र के विधानमंडल को संदर्भ आवश्यक नहीं; और राष्ट्रपति की सिफारिश सदा आवश्यक है।"},
  {"id":"polity-preamble-180","question":"In Babulal Parate v. State of Bombay (1960), the Supreme Court held, about a Bill under Article 3, that:","options":["Parliament must refer the Bill to the State again each time it is amended in either House","No fresh reference is needed if Parliament amends the Bill after the State's views","A Bill reducing a State's area needs the consent of a majority of that State's legislature","Article 3 cannot be used to form a new State out of a single existing State"],"answer":1,"explanation":"The Court held that the proviso is satisfied by one reference; Parliament may then amend the Bill freely, and the State's views do not bind it.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"बाबूलाल पाराटे बनाम बंबई राज्य (1960) में सर्वोच्च न्यायालय ने अनुच्छेद 3 के विधेयक के बारे में क्या माना?","optionsHi":["किसी भी सदन में विधेयक में संशोधन होने पर संसद को उसे हर बार राज्य को फिर से भेजना होगा","राज्य के विचार आने के बाद संसद द्वारा विधेयक में संशोधन करने पर नया संदर्भ आवश्यक नहीं है","किसी राज्य का क्षेत्रफल घटाने वाले विधेयक के लिए उस राज्य के विधानमंडल के बहुमत की सहमति चाहिए","अनुच्छेद 3 का प्रयोग किसी एक मौजूदा राज्य से नया राज्य बनाने के लिए नहीं किया जा सकता"],"explanationHi":"न्यायालय ने माना कि परंतुक एक संदर्भ से पूरा हो जाता है; संसद फिर विधेयक में स्वतंत्र रूप से संशोधन कर सकती है, और राज्य के विचार उस पर बाध्यकारी नहीं हैं।"},
  {"id":"polity-preamble-181","question":"Arrange in chronological order: 1. Report of the JVP Committee (Nehru, Patel, Pattabhi Sitaramayya) 2. Formation of Andhra State 3. Report of the Dhar Commission 4. Passing of the States Reorganisation Act","options":["3, 1, 2, 4","1, 3, 2, 4","3, 2, 1, 4","1, 2, 3, 4"],"answer":0,"explanation":"The Dhar Commission reported in December 1948, the JVP Committee in April 1949, Andhra State was formed on 1 October 1953 and the States Reorganisation Act was passed in 1956.","difficulty":"hard","source":"UPSC Prelims","questionHi":"कालक्रम के अनुसार व्यवस्थित कीजिए: 1. JVP समिति (नेहरू, पटेल, पट्टाभि सीतारमैया) की रिपोर्ट 2. आंध्र राज्य का गठन 3. धर आयोग की रिपोर्ट 4. राज्य पुनर्गठन अधिनियम का पारित होना","optionsHi":["3, 1, 2, 4","1, 3, 2, 4","3, 2, 1, 4","1, 2, 3, 4"],"explanationHi":"धर आयोग की रिपोर्ट दिसंबर 1948 में, JVP समिति की अप्रैल 1949 में आई, आंध्र राज्य 1 अक्टूबर 1953 को बना और राज्य पुनर्गठन अधिनियम 1956 में पारित हुआ।"},
  {"id":"polity-preamble-182","question":"Arrange these States in the order in which they attained full statehood: 1. Sikkim 2. Goa 3. Nagaland 4. Meghalaya","options":["3, 4, 1, 2","4, 3, 1, 2","3, 1, 4, 2","3, 4, 2, 1"],"answer":0,"explanation":"Nagaland 1963, Meghalaya 1972, Sikkim 1975 and Goa 1987 (Goa had been a Union territory with Daman and Diu until then).","difficulty":"moderate","source":"UPSC Prelims","questionHi":"इन राज्यों को पूर्ण राज्य का दर्जा पाने के क्रम में व्यवस्थित कीजिए: 1. सिक्किम 2. गोवा 3. नागालैंड 4. मेघालय","optionsHi":["3, 4, 1, 2","4, 3, 1, 2","3, 1, 4, 2","3, 4, 2, 1"],"explanationHi":"नागालैंड 1963, मेघालय 1972, सिक्किम 1975 और गोवा 1987 (तब तक गोवा दमन और दीव के साथ संघ राज्यक्षेत्र था)।"},
  {"id":"polity-preamble-183","question":"How many of the following were stated in the Objectives Resolution? 1. The territories would retain the status of autonomous units together with residuary powers. 2. Adequate safeguards would be provided for minorities, backward and tribal areas, and depressed and other backward classes. 3. All power and authority of independent India would be derived from the people. 4. India would be a Sovereign Socialist Republic.","options":["Only one","Only two","Only three","All four of them"],"answer":2,"explanation":"Statements 1–3 are in the Resolution. It called India an ‘Independent Sovereign Republic’; the word ‘socialist’ did not appear in it. Note the irony that residuary powers finally went to the Centre (Article 248).","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"उद्देश्य प्रस्ताव में निम्नलिखित में से कितनी बातें कही गई थीं? 1. राज्यक्षेत्र अवशिष्ट शक्तियों सहित स्वायत्त इकाइयों का दर्जा रखेंगे। 2. अल्पसंख्यकों, पिछड़े और जनजातीय क्षेत्रों तथा दलित और अन्य पिछड़े वर्गों के लिए पर्याप्त रक्षोपाय किए जाएँगे। 3. स्वतंत्र भारत की समस्त शक्ति और सत्ता जनता से व्युत्पन्न होगी। 4. भारत संप्रभु समाजवादी गणराज्य होगा।","optionsHi":["केवल एक","केवल दो","केवल तीन","चारों"],"explanationHi":"कथन 1–3 प्रस्ताव में हैं। इसमें भारत को ‘स्वतंत्र संप्रभु गणराज्य’ कहा गया था; ‘समाजवादी’ शब्द उसमें नहीं था। विडंबना यह है कि अवशिष्ट शक्तियाँ अंततः केंद्र को मिलीं (अनुच्छेद 248)।"},
  {"id":"polity-preamble-184","question":"Under the Cabinet Mission scheme, consider the following statements about the Constituent Assembly: 1. Seats were allotted to each province roughly in proportion of one seat to a million people. 2. Each province's seats were divided among the General, Muslim and Sikh communities in proportion to their population. 3. Each community's members in a provincial assembly elected that community's representatives by proportional representation with the single transferable vote. 4. The representatives of the princely States were to be nominated by their heads. How many of the above statements are correct?","options":["Only one","Only two","Only three","All four of them"],"answer":3,"explanation":"All four are correct. The Cabinet Mission plan gave roughly one seat per million people, split each province's seats among General, Muslim and Sikh communities by population, had each community's MLAs elect its own members by STV, and left princely State representatives to be nominated by their rulers.","difficulty":"hard","source":"UPSC Prelims","questionHi":"कैबिनेट मिशन योजना के अंतर्गत संविधान सभा के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. प्रत्येक प्रांत को लगभग दस लाख की जनसंख्या पर एक सीट के अनुपात में सीटें आवंटित हुईं। 2. प्रत्येक प्रांत की सीटें सामान्य, मुस्लिम और सिख समुदायों में उनकी जनसंख्या के अनुपात में बाँटी गईं। 3. प्रांतीय विधानसभा में प्रत्येक समुदाय के सदस्यों ने एकल संक्रमणीय मत से समानुपातिक प्रतिनिधित्व द्वारा उस समुदाय के प्रतिनिधि चुने। 4. देशी रियासतों के प्रतिनिधि उनके प्रमुखों द्वारा नामित किए जाने थे। उपर्युक्त में से कितने कथन सही हैं?","optionsHi":["केवल एक","केवल दो","केवल तीन","चारों"],"explanationHi":"चारों सही हैं। कैबिनेट मिशन योजना में लगभग दस लाख लोगों पर एक सीट दी गई, प्रत्येक प्रांत की सीटें जनसंख्या के अनुसार सामान्य, मुस्लिम और सिख समुदायों में बाँटी गईं, प्रत्येक समुदाय के विधायकों ने STV से अपने सदस्य चुने, और रियासती प्रतिनिधियों को उनके शासकों द्वारा नामित किया जाना था।"},
  {"id":"polity-preamble-185","question":"In the 1946 elections to the 296 seats allotted to British India in the Constituent Assembly, the Indian National Congress won about:","options":["208 seats","73 seats","189 seats","229 seats"],"answer":0,"explanation":"The Congress won 208 seats, the Muslim League 73 and smaller groups and independents 15, making up the 296 seats of the provinces.","difficulty":"hard","source":"UPSC Prelims","questionHi":"संविधान सभा में ब्रिटिश भारत को आवंटित 296 सीटों के 1946 के चुनावों में भारतीय राष्ट्रीय कांग्रेस ने लगभग कितनी सीटें जीतीं?","optionsHi":["208 सीटें","73 सीटें","189 सीटें","229 सीटें"],"explanationHi":"कांग्रेस ने 208 सीटें जीतीं, मुस्लिम लीग ने 73 और छोटे समूहों तथा निर्दलीयों ने 15, जो प्रांतों की 296 सीटें पूरी करती हैं।"},
  {"id":"polity-preamble-186","question":"Which statement best describes how the Constitution of India treats the British doctrine of parliamentary sovereignty and the American doctrine of judicial supremacy?","options":["It adopts parliamentary sovereignty, so courts can review executive acts but never Acts of Parliament","It adopts judicial supremacy, so Parliament cannot amend any provision the courts have once interpreted","It adopts neither and leaves conflicts between Parliament and courts to be settled by the President","It blends them: courts can strike down laws, and Parliament can amend most of the Constitution"],"answer":3,"explanation":"Indian Parliament is not sovereign (its laws face judicial review), and courts are not supreme in the American sense (Parliament can amend the Constitution widely); the basic structure doctrine marks the line between them.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"भारत का संविधान संसदीय संप्रभुता के ब्रिटिश सिद्धांत और न्यायिक सर्वोच्चता के अमेरिकी सिद्धांत के साथ कैसा व्यवहार करता है, इसे कौन-सा कथन सबसे अच्छा बताता है?","optionsHi":["यह संसदीय संप्रभुता अपनाता है, इसलिए न्यायालय कार्यपालिका के कृत्यों की समीक्षा कर सकते हैं पर संसद के अधिनियमों की कभी नहीं","यह न्यायिक सर्वोच्चता अपनाता है, इसलिए संसद किसी ऐसे प्रावधान में संशोधन नहीं कर सकती जिसकी न्यायालय ने एक बार व्याख्या कर दी","यह दोनों में से कोई नहीं अपनाता और संसद तथा न्यायालयों के बीच टकराव का समाधान राष्ट्रपति पर छोड़ता है","यह दोनों को मिलाता है: न्यायालय कानूनों को रद्द कर सकते हैं, और संसद संविधान के अधिकांश भाग में संशोधन कर सकती है"],"explanationHi":"भारतीय संसद संप्रभु नहीं है (उसके कानून न्यायिक समीक्षा के अधीन हैं), और न्यायालय अमेरिकी अर्थ में सर्वोच्च नहीं हैं (संसद संविधान में व्यापक संशोधन कर सकती है); मूल ढाँचे का सिद्धांत दोनों के बीच की रेखा तय करता है।"},
  {"id":"polity-preamble-187","question":"Which of the following is NOT a feature that makes the Indian federation lean towards the Centre?","options":["Parliament can alter the boundaries of any State without the consent of that State","Each State has its own separate Public Service Commission under Article 315","Governors are appointed by the President and hold office at his pleasure","Residuary powers of legislation rest with Parliament under Article 248"],"answer":1,"explanation":"State Public Service Commissions are a federal feature: each State recruits its own services. The other three are classic unitary features of the Constitution.","difficulty":"hard","source":"UPSC Prelims","questionHi":"इनमें से कौन-सी विशेषता भारतीय संघ को केंद्र की ओर झुकाने वाली नहीं है?","optionsHi":["संसद किसी भी राज्य की सीमाएँ उस राज्य की सहमति के बिना बदल सकती है","अनुच्छेद 315 के अंतर्गत प्रत्येक राज्य का अपना अलग लोक सेवा आयोग है","राज्यपाल राष्ट्रपति द्वारा नियुक्त होते हैं और उनके प्रसादपर्यंत पद धारण करते हैं","अनुच्छेद 248 के अंतर्गत विधायन की अवशिष्ट शक्तियाँ संसद के पास हैं"],"explanationHi":"राज्य लोक सेवा आयोग संघीय विशेषता हैं: प्रत्येक राज्य अपनी सेवाओं की भर्ती स्वयं करता है। अन्य तीन संविधान की विशिष्ट एकात्मक विशेषताएँ हैं।"},
  {"id":"polity-preamble-188","question":"Consider the following statements: 1. The Preamble mentions ‘social justice’ but not ‘economic justice’. 2. The Preamble mentions ‘equality of status’ but not ‘equality of income’. 3. The Preamble mentions ‘unity and integrity of the Nation’ but not ‘sovereignty of India’ as an object of fraternity. Which of the above is/are correct?","options":["2 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":2,"explanation":"Justice is ‘social, economic and political’, so 1 is wrong. Equality is ‘of status and of opportunity’ (no income), and fraternity assures ‘the dignity of the individual and the unity and integrity of the Nation’; ‘sovereignty’ appears only as ‘Sovereign’ in the description of India.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. उद्देशिका ‘सामाजिक न्याय’ का उल्लेख करती है पर ‘आर्थिक न्याय’ का नहीं। 2. उद्देशिका ‘प्रतिष्ठा की समता’ का उल्लेख करती है पर ‘आय की समता’ का नहीं। 3. उद्देशिका बंधुता के उद्देश्य के रूप में ‘राष्ट्र की एकता और अखंडता’ का उल्लेख करती है पर ‘भारत की संप्रभुता’ का नहीं। उपर्युक्त में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 2","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"न्याय ‘सामाजिक, आर्थिक और राजनीतिक’ है, इसलिए 1 गलत है। समता ‘प्रतिष्ठा और अवसर की’ है (आय की नहीं), और बंधुता ‘व्यक्ति की गरिमा और राष्ट्र की एकता और अखंडता’ सुनिश्चित करती है; ‘संप्रभुता’ केवल भारत के वर्णन में ‘संप्रभु’ के रूप में आती है।"},
  {"id":"polity-preamble-189","question":"Consider the following statements: 1. The Constituent Assembly elected Rajendra Prasad as the first President of India on 24 January 1950. 2. The Assembly adopted the National Flag and the National Anthem on the same day. 3. Members signed the Constitution on the same day. How many of the above statements are correct?","options":["Only one","Only two","All three","None of them"],"answer":1,"explanation":"Statements 1 and 3 are correct: Rajendra Prasad was elected and members signed the Constitution on 24 January 1950. Statement 2 is wrong: the National Anthem was adopted on 24 January 1950, but the National Flag had been adopted on 22 July 1947.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. संविधान सभा ने 24 जनवरी 1950 को राजेंद्र प्रसाद को भारत का प्रथम राष्ट्रपति चुना। 2. सभा ने राष्ट्रीय ध्वज और राष्ट्रगान उसी दिन अंगीकृत किए। 3. सदस्यों ने उसी दिन संविधान पर हस्ताक्षर किए। उपर्युक्त में से कितने कथन सही हैं?","optionsHi":["केवल एक","केवल दो","तीनों","इनमें से कोई नहीं"],"explanationHi":"कथन 1 और 3 सही हैं: राजेंद्र प्रसाद का निर्वाचन और संविधान पर सदस्यों के हस्ताक्षर 24 जनवरी 1950 को हुए। कथन 2 गलत है: राष्ट्रगान 24 जनवरी 1950 को अंगीकृत हुआ, पर राष्ट्रीय ध्वज 22 जुलाई 1947 को अंगीकृत हो चुका था।"},
  {"id":"polity-preamble-190","question":"Which of the following best explains why Article 395 expressly repealed the Indian Independence Act, 1947 and the Government of India Act, 1935, but not the Abolition of Privy Council Jurisdiction Act, 1949?","options":["The Government of India Act, 1935 had already lapsed in full on 15 August 1947 with independence","The Privy Council had already ceased to exist as a court of appeal for any country by 1949","Only the British Parliament could lawfully repeal the Acts that it had itself passed for India","The Constitution sought to rest on its own authority, ending the legal link with British Acts"],"answer":3,"explanation":"Repealing the two Acts of the British Parliament gave the Constitution ‘autochthony’, a home-grown legal source; the 1949 Act was an Indian law and needed no such break. The Privy Council still exists, and only Indian authority could repeal the Acts for India.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित में से कौन-सा कथन सबसे अच्छी तरह बताता है कि अनुच्छेद 395 ने भारतीय स्वतंत्रता अधिनियम, 1947 और भारत शासन अधिनियम, 1935 को तो स्पष्ट रूप से निरस्त किया, पर प्रिवी काउंसिल क्षेत्राधिकार उन्मूलन अधिनियम, 1949 को नहीं?","optionsHi":["भारत शासन अधिनियम, 1935 स्वतंत्रता के साथ 15 अगस्त 1947 को ही पूर्णतः समाप्त हो चुका था","प्रिवी काउंसिल 1949 तक किसी भी देश के लिए अपील न्यायालय के रूप में समाप्त हो चुकी थी","केवल ब्रिटिश संसद ही उन अधिनियमों को वैध रूप से निरस्त कर सकती थी जो उसने स्वयं भारत के लिए बनाए थे","संविधान अपनी ही सत्ता पर टिकना चाहता था, ब्रिटिश अधिनियमों से कानूनी संबंध समाप्त करते हुए"],"explanationHi":"ब्रिटिश संसद के दो अधिनियमों को निरस्त करने से संविधान को ‘स्वायत्तता’ (देशज वैधानिक स्रोत) मिली; 1949 का अधिनियम भारतीय कानून था और उसे ऐसे विच्छेद की आवश्यकता नहीं थी। प्रिवी काउंसिल अब भी अस्तित्व में है, और भारत के लिए अधिनियमों को निरस्त केवल भारतीय सत्ता ही कर सकती थी।"},
  {"id":"polity-preamble-191","question":"Consider the following statements about single citizenship: 1. India has a dual polity but only one citizenship. 2. A citizen of India may be a citizen of a State as well. 3. Article 16(3) lets Parliament prescribe residence within a State as a requirement for certain jobs in that State. Which of the above is/are correct?","options":["1 only","1 and 3 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"There is no State citizenship, so 2 is wrong. Article 16(3) is an exception that only Parliament (not a State legislature) can use to require residence for State jobs.","difficulty":"hard","source":"UPSC Prelims","questionHi":"एकल नागरिकता के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. भारत में दोहरी राजव्यवस्था है पर नागरिकता एक ही है। 2. भारत का नागरिक किसी राज्य का नागरिक भी हो सकता है। 3. अनुच्छेद 16(3) संसद को किसी राज्य में कुछ नौकरियों के लिए उस राज्य में निवास को अपेक्षा के रूप में निर्धारित करने देता है। उपर्युक्त में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 1 और 3","केवल 2 और 3","1, 2 और 3"],"explanationHi":"राज्य की कोई नागरिकता नहीं है, इसलिए 2 गलत है। अनुच्छेद 16(3) एक अपवाद है जिसका प्रयोग राज्य की नौकरियों के लिए निवास की अपेक्षा हेतु केवल संसद (राज्य विधानमंडल नहीं) कर सकती है।"},
  {"id":"polity-preamble-192","question":"The Preamble seeks to secure ‘equality of opportunity’. Which provision of the original Constitution gives this ideal its most direct effect in public employment?","options":["Article 15(1)","Article 16(1)","Article 14","Article 39(a)"],"answer":1,"explanation":"Article 16(1) guarantees equality of opportunity in matters of public employment. Article 14 is general equality before law, Article 15(1) bars discrimination, and Article 39(a) is a Directive Principle on livelihood.","difficulty":"hard","source":"UPSC Prelims","questionHi":"उद्देशिका ‘अवसर की समता’ सुनिश्चित करना चाहती है। मूल संविधान का कौन-सा प्रावधान सार्वजनिक नियोजन में इस आदर्श को सबसे प्रत्यक्ष प्रभाव देता है?","optionsHi":["अनुच्छेद 15(1)","अनुच्छेद 16(1)","अनुच्छेद 14","अनुच्छेद 39(a)"],"explanationHi":"अनुच्छेद 16(1) सार्वजनिक नियोजन के मामलों में अवसर की समता की गारंटी देता है। अनुच्छेद 14 विधि के समक्ष सामान्य समता है, अनुच्छेद 15(1) विभेद पर रोक लगाता है, और अनुच्छेद 39(a) आजीविका संबंधी निदेशक तत्व है।"},
  {"id":"polity-preamble-193","question":"Assertion (A): The Constitution of India is neither as rigid as the American nor as flexible as the British Constitution. Reason (R): Some provisions can be amended by a simple majority of Parliament, others need a special majority, and a few also need ratification by half the States.","options":["Both A and R are true, and R explains A","Both A and R are true, but R does not explain A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"The graded amendment procedures are exactly what make the Constitution a synthesis of rigidity and flexibility.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): भारत का संविधान न तो अमेरिकी संविधान जितना कठोर है, न ब्रिटिश संविधान जितना लचीला। कारण (R): कुछ प्रावधानों में संसद के साधारण बहुमत से संशोधन हो सकता है, अन्य के लिए विशेष बहुमत चाहिए, और कुछ के लिए आधे राज्यों का अनुसमर्थन भी चाहिए।","optionsHi":["A और R दोनों सत्य हैं, और R, A की व्याख्या करता है","A और R दोनों सत्य हैं, परंतु R, A की व्याख्या नहीं करता","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"संशोधन की श्रेणीबद्ध प्रक्रियाएँ ही संविधान को कठोरता और लचीलेपन का समन्वय बनाती हैं।"},
  {"id":"polity-preamble-194","question":"Consider the following statements: 1. India adopted parliamentary government from Britain but, unlike Britain, has an elected head of State. 2. Unlike the British Prime Minister, an Indian Prime Minister may be a member of the upper House. 3. Like the British Parliament, the Indian Parliament is a sovereign body. How many of the above statements are correct?","options":["Only one","Only two","All three","None of them"],"answer":1,"explanation":"Statements 1 and 2 are correct: India's President is elected, and Prime Ministers such as Manmohan Singh sat in the Rajya Sabha. Statement 3 is wrong: Indian Parliament is not sovereign like Westminster, since its laws are subject to judicial review and the basic structure.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. भारत ने संसदीय सरकार ब्रिटेन से अपनाई पर, ब्रिटेन के विपरीत, यहाँ राज्य प्रमुख निर्वाचित होता है। 2. ब्रिटिश प्रधानमंत्री के विपरीत, भारतीय प्रधानमंत्री उच्च सदन का सदस्य हो सकता है। 3. ब्रिटिश संसद की तरह भारतीय संसद भी संप्रभु निकाय है। उपर्युक्त में से कितने कथन सही हैं?","optionsHi":["केवल एक","केवल दो","तीनों","इनमें से कोई नहीं"],"explanationHi":"कथन 1 और 2 सही हैं: भारत का राष्ट्रपति निर्वाचित होता है, और मनमोहन सिंह जैसे प्रधानमंत्री राज्यसभा में रहे। कथन 3 गलत है: भारतीय संसद वेस्टमिंस्टर की तरह संप्रभु नहीं है, क्योंकि उसके कानून न्यायिक समीक्षा और मूल ढाँचे के अधीन हैं।"},
  {"id":"polity-preamble-195","question":"The Constitution borrowed the scheme of a federation with a strong Centre, residuary powers with the Centre and appointment of State Governors by the Centre largely from:","options":["The United States","Ireland","Australia","Canada"],"answer":3,"explanation":"These three features come from the Canadian model. Australia gave the Concurrent List and joint sittings; the US vests residuary powers in the States.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"सशक्त केंद्र वाले संघ की योजना, केंद्र के पास अवशिष्ट शक्तियाँ और राज्यपालों की केंद्र द्वारा नियुक्ति, संविधान ने मुख्यतः किससे ली?","optionsHi":["संयुक्त राज्य अमेरिका","आयरलैंड","ऑस्ट्रेलिया","कनाडा"],"explanationHi":"ये तीनों विशेषताएँ कनाडाई मॉडल से आई हैं। ऑस्ट्रेलिया ने समवर्ती सूची और संयुक्त बैठक दी; अमेरिका में अवशिष्ट शक्तियाँ राज्यों में निहित हैं।"},
  {"id":"polity-preamble-196","question":"Consider the following statements about the Indian model of secularism: 1. In granting aid, the State shall not discriminate against an educational institution because it is managed by a religious or linguistic minority. 2. The State may make laws for social welfare and reform even if they touch religious practice. 3. The State may levy a fee, as distinct from a tax, for services it renders to religious institutions. How many of the above statements are correct?","options":["Only one","Only two","All three","None of them"],"answer":2,"explanation":"Article 30(2) gives 1 and Article 25(2)(b) gives 2. In the Shirur Mutt case (1954) the Supreme Court held that a fee for services rendered is not barred by Article 27, which bars only taxes for promoting a religion.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"भारतीय पंथनिरपेक्षता के मॉडल के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. सहायता देते समय राज्य किसी शिक्षा संस्था से इस आधार पर विभेद नहीं करेगा कि वह धार्मिक या भाषायी अल्पसंख्यक द्वारा प्रबंधित है। 2. राज्य सामाजिक कल्याण और सुधार के कानून बना सकता है, भले वे धार्मिक आचरण को छूते हों। 3. राज्य धार्मिक संस्थाओं को दी जाने वाली सेवाओं के लिए शुल्क, जो कर से भिन्न है, ले सकता है। उपर्युक्त में से कितने कथन सही हैं?","optionsHi":["केवल एक","केवल दो","तीनों","इनमें से कोई नहीं"],"explanationHi":"अनुच्छेद 30(2) से कथन 1 और अनुच्छेद 25(2)(b) से कथन 2 आता है। शिरूर मठ मामले (1954) में सर्वोच्च न्यायालय ने माना कि दी गई सेवाओं के लिए शुल्क अनुच्छेद 27 से वर्जित नहीं है, जो केवल किसी धर्म की अभिवृद्धि के लिए करों को वर्जित करता है।"},
  {"id":"polity-preamble-197","question":"Which provision of the Constitution requires a State to pay a fixed sum every year out of its Consolidated Fund to a fund for the maintenance of Hindu temples and shrines?","options":["Article 26(d)","Article 27","Article 28","Article 290A"],"answer":3,"explanation":"Article 290A (7th Amendment, 1956) charges annual payments by Kerala to the Travancore Devaswom Fund and by Tamil Nadu to the Devasthanam Fund, honouring commitments made when the princely States merged. Article 27 bars taxes for promoting a religion.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"संविधान का कौन-सा प्रावधान किसी राज्य से अपनी संचित निधि से प्रतिवर्ष एक निश्चित राशि हिंदू मंदिरों और देवस्थानों के रखरखाव की निधि में देने की अपेक्षा करता है?","optionsHi":["अनुच्छेद 26(d)","अनुच्छेद 27","अनुच्छेद 28","अनुच्छेद 290A"],"explanationHi":"अनुच्छेद 290A (7वाँ संशोधन, 1956) केरल द्वारा त्रावणकोर देवस्वम निधि और तमिलनाडु द्वारा देवस्थानम निधि को वार्षिक भुगतान का भार डालता है, जो रियासतों के विलय के समय की प्रतिबद्धताओं का सम्मान करता है। अनुच्छेद 27 किसी धर्म की अभिवृद्धि के लिए करों को वर्जित करता है।"},
  {"id":"polity-preamble-198","question":"In Balaji Raghavan v. Union of India (1996), the Supreme Court held that national awards such as the Bharat Ratna and the Padma awards:","options":["Are titles barred by Article 18 and so must be discontinued by the Union Government","Are not titles under Article 18, but must not be used as prefixes or suffixes","Are titles that a citizen may accept only with the consent of the President","Are valid only if conferred with the prior approval of both Houses of Parliament"],"answer":1,"explanation":"The Court upheld the awards as recognition of merit, not titles of nobility, but said that using them as a prefix or suffix would breach the spirit of Article 18 and the Preamble's equality of status.","difficulty":"hard","source":"UPSC Prelims","questionHi":"बालाजी राघवन बनाम भारत संघ (1996) में सर्वोच्च न्यायालय ने माना कि भारत रत्न और पद्म पुरस्कार जैसे राष्ट्रीय सम्मान:","optionsHi":["अनुच्छेद 18 द्वारा वर्जित उपाधियाँ हैं और संघ सरकार को इन्हें बंद कर देना चाहिए","अनुच्छेद 18 के अंतर्गत उपाधियाँ नहीं हैं, परंतु इन्हें उपसर्ग या प्रत्यय के रूप में प्रयोग नहीं किया जाना चाहिए","ऐसी उपाधियाँ हैं जिन्हें नागरिक केवल राष्ट्रपति की सहमति से स्वीकार कर सकता है","तभी वैध हैं जब संसद के दोनों सदनों की पूर्व स्वीकृति से प्रदान किए जाएँ"],"explanationHi":"न्यायालय ने इन पुरस्कारों को योग्यता की मान्यता के रूप में, कुलीनता की उपाधि नहीं, बरकरार रखा, पर कहा कि इन्हें उपसर्ग या प्रत्यय के रूप में प्रयोग करना अनुच्छेद 18 की भावना और उद्देशिका की प्रतिष्ठा की समता का उल्लंघन होगा।"},
  {"id":"polity-preamble-199","question":"How many of the following expressions occur anywhere in the text of the Constitution of India? Secular, Cabinet, Deputy Prime Minister, Leader of the Opposition","options":["Only one","Only two","Only three","All four of them"],"answer":1,"explanation":"‘Secular’ occurs in the Preamble and Article 25(2)(a), and ‘Cabinet’ in Article 352(3). The Deputy Prime Minister is a political convention and the Leader of the Opposition is recognised by statute (1977 Act), not the Constitution.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"भारत के संविधान के पाठ में निम्नलिखित में से कितनी अभिव्यक्तियाँ कहीं भी आती हैं? पंथनिरपेक्ष, मंत्रिमंडल, उप-प्रधानमंत्री, विपक्ष का नेता","optionsHi":["केवल एक","केवल दो","केवल तीन","चारों"],"explanationHi":"‘पंथनिरपेक्ष’ उद्देशिका और अनुच्छेद 25(2)(a) में आता है, और ‘मंत्रिमंडल’ अनुच्छेद 352(3) में। उप-प्रधानमंत्री राजनीतिक परंपरा है और विपक्ष के नेता को संविधि (1977 का अधिनियम) मान्यता देती है, संविधान नहीं।"},
  {"id":"polity-preamble-200","question":"Match the Constitution Amendment with the territory it incorporated into the First Schedule: A. 10th Amendment B. 12th Amendment C. 14th Amendment D. 36th Amendment — 1. Dadra and Nagar Haveli 2. Goa, Daman and Diu 3. Puducherry 4. Sikkim","options":["A-1, B-2, C-3, D-4","A-2, B-1, C-3, D-4","A-1, B-3, C-2, D-4","A-3, B-2, C-1, D-4"],"answer":0,"explanation":"The 10th (1961) added Dadra and Nagar Haveli, the 12th (1962) Goa, Daman and Diu, the 14th (1962) Puducherry, and the 36th (1975) made Sikkim a full State. The 35th had made Sikkim only an associate State.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"संविधान संशोधन को उस राज्यक्षेत्र से सुमेलित कीजिए जिसे उसने पहली अनुसूची में शामिल किया: A. 10वाँ संशोधन B. 12वाँ संशोधन C. 14वाँ संशोधन D. 36वाँ संशोधन — 1. दादरा और नागर हवेली 2. गोवा, दमन और दीव 3. पुदुच्चेरी 4. सिक्किम","optionsHi":["A-1, B-2, C-3, D-4","A-2, B-1, C-3, D-4","A-1, B-3, C-2, D-4","A-3, B-2, C-1, D-4"],"explanationHi":"10वें (1961) ने दादरा और नागर हवेली, 12वें (1962) ने गोवा, दमन और दीव, 14वें (1962) ने पुदुच्चेरी जोड़ा, और 36वें (1975) ने सिक्किम को पूर्ण राज्य बनाया। 35वें ने सिक्किम को केवल सहयोगी राज्य बनाया था।"},
  {"id":"polity-preamble-201","question":"Arrange in chronological order: 1. Merger of Dadra and Nagar Haveli with Daman and Diu into one Union territory 2. Reorganisation of Jammu and Kashmir into two Union territories 3. De jure transfer of Puducherry from France to India 4. Liberation of Goa, Daman and Diu","options":["4, 3, 2, 1","3, 4, 2, 1","4, 3, 1, 2","3, 4, 1, 2"],"answer":0,"explanation":"Goa was liberated in December 1961, Puducherry's de jure transfer came in August 1962, J&K was reorganised on 31 October 2019 and the two western UTs merged on 26 January 2020.","difficulty":"hard","source":"UPSC Prelims","questionHi":"कालक्रम के अनुसार व्यवस्थित कीजिए: 1. दादरा और नागर हवेली का दमन और दीव के साथ एक संघ राज्यक्षेत्र में विलय 2. जम्मू और कश्मीर का दो संघ राज्यक्षेत्रों में पुनर्गठन 3. पुदुच्चेरी का फ्रांस से भारत को विधिसम्मत (डि ज्यूर) हस्तांतरण 4. गोवा, दमन और दीव की मुक्ति","optionsHi":["4, 3, 2, 1","3, 4, 2, 1","4, 3, 1, 2","3, 4, 1, 2"],"explanationHi":"गोवा दिसंबर 1961 में मुक्त हुआ, पुदुच्चेरी का डि ज्यूर हस्तांतरण अगस्त 1962 में हुआ, जम्मू-कश्मीर का पुनर्गठन 31 अक्टूबर 2019 को हुआ और दोनों पश्चिमी संघ राज्यक्षेत्र 26 जनवरी 2020 को मिल गए।"},
  {"id":"polity-preamble-202","question":"Assertion (A): Telangana was created in 2014 even though the Andhra Pradesh Legislative Assembly had rejected the reorganisation Bill. Reason (R): A Bill under Article 3 can be introduced only on the recommendation of the President.","options":["Both A and R are true, and R explains A","Both A and R are true, but R does not explain A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"Both are true, but A is explained by a different rule: the views of the State legislature on an Article 3 Bill are only advisory and do not bind Parliament.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): आंध्र प्रदेश विधानसभा द्वारा पुनर्गठन विधेयक को अस्वीकार करने के बावजूद 2014 में तेलंगाना बनाया गया। कारण (R): अनुच्छेद 3 का विधेयक केवल राष्ट्रपति की सिफारिश पर पेश किया जा सकता है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की व्याख्या करता है","A और R दोनों सत्य हैं, परंतु R, A की व्याख्या नहीं करता","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"दोनों सत्य हैं, पर A की व्याख्या एक अलग नियम से होती है: अनुच्छेद 3 के विधेयक पर राज्य विधानमंडल के विचार केवल परामर्शी हैं और संसद पर बाध्यकारी नहीं।"},
  {"id":"polity-preamble-203","question":"Which of the following States was never a Union territory before attaining statehood?","options":["Mizoram","Arunachal Pradesh","Tripura","Meghalaya"],"answer":3,"explanation":"Meghalaya was carved out of Assam, first as an autonomous State within Assam (1970) and then as a full State (1972). Mizoram and Arunachal Pradesh were UTs from 1972 and Tripura from 1956 before becoming States.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित में से कौन-सा राज्य पूर्ण राज्य बनने से पहले कभी संघ राज्यक्षेत्र नहीं था?","optionsHi":["मिजोरम","अरुणाचल प्रदेश","त्रिपुरा","मेघालय"],"explanationHi":"मेघालय असम से अलग किया गया, पहले असम के भीतर स्वायत्त राज्य (1970) के रूप में और फिर पूर्ण राज्य (1972) के रूप में। मिजोरम और अरुणाचल प्रदेश राज्य बनने से पहले 1972 से और त्रिपुरा 1956 से संघ राज्यक्षेत्र थे।"},
  {"id":"polity-preamble-204","question":"The Constitutional Adviser to the Constituent Assembly later served as a judge of which body?","options":["The Supreme Court of India","The International Court of Justice","The Federal Court of India","The Permanent Court of Arbitration"],"answer":1,"explanation":"Sir B. N. Rau, who prepared the first draft of the Constitution, was elected a judge of the International Court of Justice at The Hague in 1952.","difficulty":"hard","source":"UPSC Prelims","questionHi":"संविधान सभा के संवैधानिक सलाहकार ने बाद में किस निकाय के न्यायाधीश के रूप में सेवा की?","optionsHi":["भारत का सर्वोच्च न्यायालय","अंतरराष्ट्रीय न्यायालय","भारत का संघीय न्यायालय","स्थायी मध्यस्थता न्यायालय"],"explanationHi":"संविधान का पहला प्रारूप तैयार करने वाले सर बी. एन. राव 1952 में हेग स्थित अंतरराष्ट्रीय न्यायालय के न्यायाधीश चुने गए।"},
  {"id":"polity-preamble-205","question":"Who served as the Chief Draftsman of the Constitution in the Constituent Assembly?","options":["K. M. Munshi","H. V. R. Iengar","S. N. Mukherjee","B. N. Rau"],"answer":2,"explanation":"S. N. Mukherjee was the Chief Draftsman, praised by Ambedkar for putting complicated proposals into clear legal language. B. N. Rau was the Constitutional Adviser and H. V. R. Iengar the Secretary of the Assembly.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"संविधान सभा में संविधान के मुख्य प्रारूपकार के रूप में किसने सेवा की?","optionsHi":["के. एम. मुंशी","एच. वी. आर. आयंगर","एस. एन. मुखर्जी","बी. एन. राव"],"explanationHi":"एस. एन. मुखर्जी मुख्य प्रारूपकार थे, जिनकी अंबेडकर ने जटिल प्रस्तावों को स्पष्ट विधिक भाषा में ढालने के लिए प्रशंसा की। बी. एन. राव संवैधानिक सलाहकार थे और एच. वी. आर. आयंगर सभा के सचिव।"},
  {"id":"polity-preamble-206","question":"Who was the only Muslim woman member of the Constituent Assembly?","options":["Durgabai Deshmukh","Renuka Ray","Ammu Swaminathan","Begum Aizaz Rasul"],"answer":3,"explanation":"Begum Qudsia Aizaz Rasul, elected from the United Provinces, was the only Muslim woman in the Assembly; she later opposed separate electorates. The other three were non-Muslim women members.","difficulty":"hard","source":"UPSC Prelims","questionHi":"संविधान सभा की एकमात्र मुस्लिम महिला सदस्य कौन थीं?","optionsHi":["दुर्गाबाई देशमुख","रेणुका रे","अम्मू स्वामीनाथन","बेगम एजाज़ रसूल"],"explanationHi":"संयुक्त प्रांत से निर्वाचित बेगम कुदसिया एजाज़ रसूल सभा की एकमात्र मुस्लिम महिला थीं; उन्होंने बाद में पृथक निर्वाचन का विरोध किया। अन्य तीन गैर-मुस्लिम महिला सदस्य थीं।"},
  {"id":"polity-preamble-207","question":"Consider the following statements about the Constituent Assembly: 1. It held twelve sessions in all. 2. Of its 165 sitting days, about 114 were spent considering the Draft Constitution. 3. It completed its work in a little under three years. How many of the above statements are correct?","options":["Only one","Only two","All three","None of them"],"answer":1,"explanation":"Statements 2 and 3 are correct: 114 of its 165 sitting days went to the Draft Constitution, and it worked for 2 years, 11 months and 18 days. Statement 1 is wrong: the Assembly held eleven sessions, not twelve.","difficulty":"hard","source":"UPSC Prelims","questionHi":"संविधान सभा के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. इसके कुल बारह सत्र हुए। 2. इसके 165 बैठक-दिवसों में से लगभग 114 प्रारूप संविधान पर विचार में लगे। 3. इसने अपना कार्य तीन वर्ष से कुछ कम में पूरा किया। उपर्युक्त में से कितने कथन सही हैं?","optionsHi":["केवल एक","केवल दो","तीनों","इनमें से कोई नहीं"],"explanationHi":"कथन 2 और 3 सही हैं: 165 बैठक-दिवसों में से 114 प्रारूप संविधान पर लगे, और उसने 2 वर्ष, 11 महीने और 18 दिन कार्य किया। कथन 1 गलत है: सभा के ग्यारह सत्र हुए, बारह नहीं।"},
  {"id":"polity-preamble-208","question":"Consider the following statements: 1. The Draft Constitution was published in February 1948. 2. The people of India were given about eight months to discuss it and suggest changes. 3. Ambedkar introduced the Draft in the Assembly on 4 November 1948 for its first reading. Which of the above is/are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":3,"explanation":"All three are correct. The first reading began on 4 November 1948, the second (clause-by-clause) reading followed, and the third ended with adoption on 26 November 1949.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. प्रारूप संविधान फरवरी 1948 में प्रकाशित हुआ। 2. भारत के लोगों को इस पर चर्चा करने और परिवर्तन सुझाने के लिए लगभग आठ महीने दिए गए। 3. अंबेडकर ने 4 नवंबर 1948 को प्रथम वाचन के लिए सभा में प्रारूप प्रस्तुत किया। उपर्युक्त में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"तीनों सही हैं। प्रथम वाचन 4 नवंबर 1948 को शुरू हुआ, द्वितीय (खंडवार) वाचन उसके बाद हुआ, और तृतीय वाचन 26 नवंबर 1949 को अंगीकरण के साथ समाप्त हुआ।"},
  {"id":"polity-preamble-209","question":"The idea of a ‘welfare State’, though not named in the Preamble, is embodied chiefly in which Part of the Constitution?","options":["Part IVA","Part IV","Part III","Part XVI"],"answer":1,"explanation":"The Directive Principles in Part IV aim at a welfare State, giving concrete content to social and economic justice. Part III holds Fundamental Rights, Part IVA Fundamental Duties and Part XVI special provisions for certain classes.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"‘कल्याणकारी राज्य’ का विचार, यद्यपि उद्देशिका में नामित नहीं है, मुख्यतः संविधान के किस भाग में निहित है?","optionsHi":["भाग IVक","भाग IV","भाग III","भाग XVI"],"explanationHi":"भाग IV के निदेशक तत्व कल्याणकारी राज्य का लक्ष्य रखते हैं और सामाजिक तथा आर्थिक न्याय को ठोस विषयवस्तु देते हैं। भाग III में मौलिक अधिकार, भाग IVक में मौलिक कर्तव्य और भाग XVI में कुछ वर्गों के लिए विशेष उपबंध हैं।"},
  {"id":"polity-preamble-210","question":"Assertion (A): No State has the right to secede from the Indian Union. Reason (R): The Indian federation is not the result of an agreement among the States.","options":["Both A and R are true, and R explains A","Both A and R are true, but R does not explain A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Ambedkar explained that because the federation was not formed by an agreement of the States, no State can secede; hence India is called a ‘Union of States’.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"अभिकथन (A): किसी राज्य को भारतीय संघ से अलग होने का अधिकार नहीं है। कारण (R): भारतीय संघ राज्यों के बीच किसी समझौते का परिणाम नहीं है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की व्याख्या करता है","A और R दोनों सत्य हैं, परंतु R, A की व्याख्या नहीं करता","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"अंबेडकर ने समझाया कि क्योंकि संघ राज्यों के समझौते से नहीं बना, कोई राज्य अलग नहीं हो सकता; इसीलिए भारत को ‘राज्यों का संघ’ कहा जाता है।"},
  {"id":"polity-preamble-211","question":"Arrange in chronological order: 1. Setting up of the Drafting Committee 2. Announcement of the Mountbatten Plan 3. Adoption of the Objectives Resolution 4. Publication of the Draft Constitution","options":["3, 2, 1, 4","2, 3, 1, 4","3, 1, 2, 4","2, 1, 3, 4"],"answer":0,"explanation":"The Objectives Resolution was adopted on 22 January 1947, the Mountbatten Plan came on 3 June 1947, the Drafting Committee was set up on 29 August 1947 and the Draft was published in February 1948.","difficulty":"hard","source":"UPSC Prelims","questionHi":"कालक्रम के अनुसार व्यवस्थित कीजिए: 1. प्रारूप समिति का गठन 2. माउंटबेटन योजना की घोषणा 3. उद्देश्य प्रस्ताव का अंगीकरण 4. प्रारूप संविधान का प्रकाशन","optionsHi":["3, 2, 1, 4","2, 3, 1, 4","3, 1, 2, 4","2, 1, 3, 4"],"explanationHi":"उद्देश्य प्रस्ताव 22 जनवरी 1947 को अंगीकृत हुआ, माउंटबेटन योजना 3 जून 1947 को आई, प्रारूप समिति 29 अगस्त 1947 को गठित हुई और प्रारूप फरवरी 1948 में प्रकाशित हुआ।"},
  {"id":"polity-preamble-212","question":"How many of the following are federal features of the Constitution of India? Written Constitution, Integrated judiciary, Appointment of Governors by the Centre, Single citizenship","options":["Only one","Only two","Only three","All four of them"],"answer":0,"explanation":"Only a written Constitution is a federal feature. An integrated judiciary, the Centre's appointment of State Governors and single citizenship are all unitary features of the Indian Constitution.","difficulty":"hard","source":"UPSC Prelims","questionHi":"भारत के संविधान की निम्नलिखित में से कितनी संघीय विशेषताएँ हैं? लिखित संविधान, एकीकृत न्यायपालिका, केंद्र द्वारा राज्यपालों की नियुक्ति, एकल नागरिकता","optionsHi":["केवल एक","केवल दो","केवल तीन","चारों"],"explanationHi":"केवल लिखित संविधान संघीय विशेषता है। एकीकृत न्यायपालिका, केंद्र द्वारा राज्यपालों की नियुक्ति और एकल नागरिकता, तीनों भारतीय संविधान की एकात्मक विशेषताएँ हैं।"},
  {"id":"polity-preamble-213","question":"Which of the following is permitted by the Indian model of secularism but would be inconsistent with a strict wall of separation between State and religion?","options":["Compelling citizens to pay a tax that is set apart to promote one particular religion","Declaring one religion as the official religion of the Union and of every State","A law throwing open Hindu religious institutions of a public character to all Hindus","Requiring a religious test of candidates for appointment to any public office"],"answer":2,"explanation":"Article 25(2)(b) lets the State intervene in religion for social reform, which a strict separation model would not allow. The other three are forbidden in India as well (no State religion, Article 16, Article 27).","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित में से क्या भारतीय पंथनिरपेक्षता के मॉडल में अनुमत है, पर राज्य और धर्म के बीच पृथक्करण की कठोर दीवार से असंगत होता?","optionsHi":["नागरिकों को किसी एक विशेष धर्म की अभिवृद्धि के लिए अलग रखे गए कर का भुगतान करने को बाध्य करना","एक धर्म को संघ और प्रत्येक राज्य का आधिकारिक धर्म घोषित करना","सार्वजनिक स्वरूप की हिंदू धार्मिक संस्थाओं को सभी हिंदुओं के लिए खोलने वाला कानून","किसी भी सार्वजनिक पद पर नियुक्ति के लिए अभ्यर्थियों पर धार्मिक परीक्षा लागू करना"],"explanationHi":"अनुच्छेद 25(2)(b) राज्य को सामाजिक सुधार के लिए धर्म में हस्तक्षेप करने देता है, जिसकी कठोर पृथक्करण मॉडल अनुमति नहीं देता। शेष तीन भारत में भी वर्जित हैं (कोई राज्य धर्म नहीं, अनुच्छेद 16, अनुच्छेद 27)।"},
  {"id":"polity-preamble-214","question":"Assertion (A): Parliament can change the name of a State by an ordinary law. Reason (R): Article 3(e) empowers Parliament by law to alter the name of any State.","options":["Both A and R are true, and R explains A","Both A and R are true, but R does not explain A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Renaming, as of Orissa to Odisha in 2011, is done by a simple law under Article 3(e), which Article 4 says is not an amendment under Article 368.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): संसद साधारण कानून द्वारा किसी राज्य का नाम बदल सकती है। कारण (R): अनुच्छेद 3(e) संसद को विधि द्वारा किसी राज्य का नाम बदलने का अधिकार देता है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की व्याख्या करता है","A और R दोनों सत्य हैं, परंतु R, A की व्याख्या नहीं करता","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"नाम परिवर्तन, जैसे 2011 में उड़ीसा से ओडिशा, अनुच्छेद 3(e) के अंतर्गत साधारण कानून से होता है, जिसे अनुच्छेद 4 के अनुसार अनुच्छेद 368 के अंतर्गत संशोधन नहीं माना जाता।"},
  {"id":"polity-preamble-215","question":"Assertion (A): Puducherry legally became part of the territory of India only in 1962. Reason (R): France handed over the administration of Puducherry to India only in 1962.","options":["Both A and R are true, and R explains A","Both A and R are true, but R does not explain A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"The de facto transfer of administration took place in 1954; the de jure transfer, after the treaty was ratified, came on 16 August 1962, followed by the 14th Amendment.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): पुदुच्चेरी विधिक रूप से 1962 में ही भारत के राज्यक्षेत्र का भाग बना। कारण (R): फ्रांस ने पुदुच्चेरी का प्रशासन भारत को केवल 1962 में सौंपा।","optionsHi":["A और R दोनों सत्य हैं, और R, A की व्याख्या करता है","A और R दोनों सत्य हैं, परंतु R, A की व्याख्या नहीं करता","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"प्रशासन का वास्तविक (डि फैक्टो) हस्तांतरण 1954 में हुआ; संधि के अनुसमर्थन के बाद विधिसम्मत (डि ज्यूर) हस्तांतरण 16 अगस्त 1962 को हुआ, जिसके बाद 14वाँ संशोधन आया।"},
  {"id":"polity-preamble-216","question":"Consider the following statements about the Preamble and judicial interpretation: 1. Courts use the Preamble to resolve ambiguity in a provision, not to override its clear words. 2. The Preamble by itself is a source of legislative power for Parliament. 3. The Preamble's basic elements cannot be destroyed even by a constitutional amendment. Which of the above is/are correct?","options":["1 and 3 only","1 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"The Preamble is an aid to interpretation and, after Kesavananda Bharati, its basic features are beyond the amending power. It is neither a source of power nor a limitation on power by itself, so 2 is wrong.","difficulty":"hard","source":"UPSC Prelims","questionHi":"उद्देशिका और न्यायिक व्याख्या के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. न्यायालय उद्देशिका का उपयोग किसी प्रावधान की अस्पष्टता दूर करने के लिए करते हैं, उसके स्पष्ट शब्दों को निरस्त करने के लिए नहीं। 2. उद्देशिका स्वयं संसद के लिए विधायी शक्ति का स्रोत है। 3. उद्देशिका के मूल तत्वों को संविधान संशोधन द्वारा भी नष्ट नहीं किया जा सकता। उपर्युक्त में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1 और 3","केवल 1","केवल 2 और 3","1, 2 और 3"],"explanationHi":"उद्देशिका व्याख्या में सहायक है और केशवानंद भारती के बाद इसकी मूल विशेषताएँ संशोधन की शक्ति से परे हैं। यह स्वयं न शक्ति का स्रोत है, न शक्ति पर सीमा, इसलिए 2 गलत है।"},
  {"id":"polity-preamble-217","question":"On 24 January 1950, how many members of the Constituent Assembly put their signatures to the Constitution?","options":["284","299","389","211"],"answer":0,"explanation":"284 members signed. 389 was the strength planned by the Cabinet Mission, 299 the strength after partition, and about 211 attended the first meeting in December 1946.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"24 जनवरी 1950 को संविधान सभा के कितने सदस्यों ने संविधान पर हस्ताक्षर किए?","optionsHi":["284","299","389","211"],"explanationHi":"284 सदस्यों ने हस्ताक्षर किए। 389 कैबिनेट मिशन की नियोजित संख्या थी, 299 विभाजन के बाद की संख्या, और दिसंबर 1946 की पहली बैठक में लगभग 211 उपस्थित थे।"},
  {"id":"polity-preamble-218","question":"How many of the following pairs of an ideal in the Preamble and a provision that gives it effect are correctly matched? 1. Liberty of expression – Article 19(1)(a) 2. Equality of status – Article 18 3. Economic justice – Article 39(b) 4. Fraternity – Article 51A(e)","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct: Article 19(1)(a) secures expression, abolishing titles (Article 18) supports equal status, Article 39(b) seeks distribution of material resources for the common good, and Article 51A(e) asks citizens to promote common brotherhood.","difficulty":"hard","source":"UPSC Prelims","questionHi":"उद्देशिका के आदर्श और उसे प्रभावी करने वाले प्रावधान के निम्नलिखित युग्मों में से कितने सही सुमेलित हैं? 1. अभिव्यक्ति की स्वतंत्रता – अनुच्छेद 19(1)(a) 2. प्रतिष्ठा की समता – अनुच्छेद 18 3. आर्थिक न्याय – अनुच्छेद 39(b) 4. बंधुता – अनुच्छेद 51A(e)","optionsHi":["केवल एक","केवल दो","केवल तीन","चारों"],"explanationHi":"चारों सही हैं: अनुच्छेद 19(1)(a) अभिव्यक्ति सुनिश्चित करता है, उपाधियों का उन्मूलन (अनुच्छेद 18) समान प्रतिष्ठा का समर्थन करता है, अनुच्छेद 39(b) सामूहिक हित के लिए भौतिक संसाधनों के वितरण का लक्ष्य रखता है, और अनुच्छेद 51A(e) नागरिकों से समान भ्रातृत्व को बढ़ावा देने को कहता है।"},
  {"id":"polity-preamble-219","question":"Consider the following statements: 1. The Constituent Assembly first met with 211 members present, as the Muslim League stayed away. 2. After partition, the Assembly's strength fell to 299. 3. The members from the princely States had all joined by the first session. How many of the above statements are correct?","options":["Only one","Only two","All three","None of them"],"answer":1,"explanation":"About 211 members attended the first meeting and the strength fell to 299 after partition. The princely States joined gradually from 1947 onward, so statement 3 is wrong.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. संविधान सभा की पहली बैठक में 211 सदस्य उपस्थित थे, क्योंकि मुस्लिम लीग अनुपस्थित रही। 2. विभाजन के बाद सभा की संख्या घटकर 299 रह गई। 3. रियासतों के सभी सदस्य पहले सत्र तक शामिल हो चुके थे। उपर्युक्त में से कितने कथन सही हैं?","optionsHi":["केवल एक","केवल दो","तीनों","इनमें से कोई नहीं"],"explanationHi":"पहली बैठक में लगभग 211 सदस्य उपस्थित थे और विभाजन के बाद संख्या 299 रह गई। रियासतें 1947 से आगे धीरे-धीरे शामिल हुईं, इसलिए कथन 3 गलत है।"},
  {"id":"polity-preamble-220","question":"Which one of the following is a unitary rather than a federal feature of the Constitution?","options":["Rajya Sabha, as a House representing the States, forming a part of Parliament","Supremacy of a written Constitution that binds both the Union and the States","Division of legislative powers between the Union and the States in three Lists","A single Election Commission for both Union and State legislative elections"],"answer":3,"explanation":"A single Election Commission conducting both Union and State legislative elections is a unitary feature; the other three are classic federal features.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"निम्नलिखित में से कौन-सी संविधान की संघीय नहीं, बल्कि एकात्मक विशेषता है?","optionsHi":["राज्यसभा का, राज्यों का प्रतिनिधित्व करने वाले सदन के रूप में, संसद का भाग होना","लिखित संविधान की सर्वोच्चता जो संघ और राज्यों दोनों को बाँधती है","तीन सूचियों में संघ और राज्यों के बीच विधायी शक्तियों का विभाजन","संघ और राज्य विधानमंडलों दोनों के चुनावों के लिए एकल निर्वाचन आयोग"],"explanationHi":"संघ और राज्य विधानमंडलों दोनों के चुनाव कराने वाला एकल निर्वाचन आयोग एकात्मक विशेषता है; शेष तीन विशिष्ट संघीय विशेषताएँ हैं।"},
  {"id":"polity-preamble-221","question":"In which sequence do these expressions appear in the Preamble? 1. dignity of the individual 2. equality of status 3. liberty of thought 4. unity and integrity of the Nation","options":["3, 2, 1, 4","2, 3, 1, 4","3, 1, 2, 4","1, 3, 2, 4"],"answer":0,"explanation":"The Preamble lists Liberty (of thought …), then Equality (of status …), then Fraternity ‘assuring the dignity of the individual and the unity and integrity of the Nation’.","difficulty":"hard","source":"UPSC Prelims","questionHi":"ये अभिव्यक्तियाँ उद्देशिका में किस क्रम में आती हैं? 1. व्यक्ति की गरिमा 2. प्रतिष्ठा की समता 3. विचार की स्वतंत्रता 4. राष्ट्र की एकता और अखंडता","optionsHi":["3, 2, 1, 4","2, 3, 1, 4","3, 1, 2, 4","1, 3, 2, 4"],"explanationHi":"उद्देशिका पहले स्वतंत्रता (विचार की …), फिर समता (प्रतिष्ठा की …), फिर बंधुता सूचीबद्ध करती है जो ‘व्यक्ति की गरिमा और राष्ट्र की एकता और अखंडता’ सुनिश्चित करती है।"},
  {"id":"polity-preamble-222","question":"Consider the following statements: 1. Sikkim was admitted to the Union under Article 2. 2. Andhra State in 1953 was formed under Article 3 by separating territory from Madras State. 3. Changing the boundary of a State under Article 3 needs ratification by half the State legislatures. Which of the above is/are correct?","options":["1 and 2 only","1 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Sikkim, not part of India before, came in under Article 2 (36th Amendment); Andhra was carved out of Madras under Article 3. Article 3 laws need only a simple majority and no ratification by the States.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. सिक्किम को अनुच्छेद 2 के अंतर्गत संघ में प्रवेश दिया गया। 2. 1953 का आंध्र राज्य अनुच्छेद 3 के अंतर्गत मद्रास राज्य से क्षेत्र अलग करके बनाया गया। 3. अनुच्छेद 3 के अंतर्गत किसी राज्य की सीमा बदलने के लिए आधे राज्य विधानमंडलों का अनुसमर्थन आवश्यक है। उपर्युक्त में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1 और 2","केवल 1","केवल 2 और 3","1, 2 और 3"],"explanationHi":"सिक्किम, जो पहले भारत का भाग नहीं था, अनुच्छेद 2 (36वाँ संशोधन) के अंतर्गत आया; आंध्र को अनुच्छेद 3 के अंतर्गत मद्रास से अलग किया गया। अनुच्छेद 3 के कानूनों के लिए केवल साधारण बहुमत चाहिए, राज्यों के अनुसमर्थन की आवश्यकता नहीं।"},
  {"id":"polity-preamble-223","question":"Which of the following best captures the significance of the words ‘We, the people of India … do hereby adopt, enact and give to ourselves this Constitution’?","options":["The Constitution was approved by the people in a nationwide referendum held in 1949","The Constitution draws its authority from the people, not from a British statute","Every citizen is bound to take an oath of allegiance to the Constitution at age eighteen","The Constitution can be amended only with the consent of the people through a referendum"],"answer":1,"explanation":"The enacting words assert popular sovereignty as the source of the Constitution. There was no referendum on it, there is no citizen's oath, and amendments are made by Parliament (with some States) under Article 368.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"‘हम, भारत के लोग … एतद्द्वारा इस संविधान को अंगीकृत, अधिनियमित और आत्मार्पित करते हैं’ शब्दों के महत्व को निम्नलिखित में से कौन-सा सबसे अच्छी तरह बताता है?","optionsHi":["संविधान को 1949 में हुए राष्ट्रव्यापी जनमत संग्रह में जनता ने अनुमोदित किया","संविधान अपनी सत्ता जनता से प्राप्त करता है, किसी ब्रिटिश संविधि से नहीं","प्रत्येक नागरिक को अठारह वर्ष की आयु में संविधान के प्रति निष्ठा की शपथ लेनी होती है","संविधान में संशोधन केवल जनमत संग्रह द्वारा जनता की सहमति से ही हो सकता है"],"explanationHi":"अधिनियमन के ये शब्द जन-संप्रभुता को संविधान का स्रोत बताते हैं। उस पर कोई जनमत संग्रह नहीं हुआ, नागरिकों की कोई शपथ नहीं है, और संशोधन संसद (कुछ मामलों में राज्यों के साथ) अनुच्छेद 368 के अंतर्गत करती है।"},
];

export default questions;
